insert into public.spots (id, city, name, cat, price, hood, address, "desc", tip, pick, photo, credit, source) values
  ('s01', 'paris', 'Bouillon Chartier', 'Restaurant', 'p1', 'Grands Boulevards', '7 Rue du Faubourg Montmartre, 75009 Paris', 'Poussez la porte tournante et vous voilà en 1896 : verrière, banquettes en moleskine, serveurs en gilet noir qui notent l''addition sur la nappe en papier. On y vient pour l''œuf mayo, le bœuf bourguignon ou le confit de canard à des prix qui semblent sortis d''une autre époque, dans un brouhaha joyeux typiquement parisien.', 'Pas de réservation : venez avant 12h ou après 14h pour éviter l''attente.', true, 'img/s01.jpg', 'Michel wal · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paris_Chartier_1304.jpg'),
  ('s02', 'paris', 'Musée d''Orsay', 'Culture', 'p2', '7e arrondissement', 'Esplanade Valéry Giscard d''Estaing, 75007 Paris', 'Installé dans une ancienne gare Belle Époque, Orsay réunit la plus belle collection impressionniste au monde : Monet, Renoir, Van Gogh, Degas. Montez au 5e étage pour admirer Paris à travers l''immense horloge vitrée, une des plus belles vues de la ville sur la Seine et le Sacré-Cœur.', 'Gratuit le premier dimanche du mois, mais réservez quand même un créneau en ligne.', false, 'img/s02.jpg', 'Daniel Lu (User:dllu) · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Musee_d_Orsay_main_hall_Paris_2023_dllu.jpg'),
  ('s03', 'paris', 'Canal Saint-Martin', 'Activité', 'free', '10e arrondissement', 'Quai de Valmy, 75010 Paris', 'Écluses, passerelles en fer forgé et alignements de platanes : le canal est le coin préféré des Parisiens pour flâner, boire un verre en terrasse ou pique-niquer les jambes au-dessus de l''eau. Les rives sont bordées de boutiques indépendantes, de cafés et de librairies.', 'Le dimanche, les quais sont piétons : idéal à vélo.', false, 'img/s03.jpg', 'Superbass · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2022-04-14-Passerelle_de_la_Grange-aux-Belles-8583.jpg'),
  ('s25', 'paris', 'Musée du Louvre', 'Culture', 'p2', '1er arrondissement', 'Rue de Rivoli, 75001 Paris', 'Ancien palais des rois de France, le Louvre abrite la Joconde, la Vénus de Milo et la Victoire de Samothrace, mais aussi des salles entières presque désertes où l''on se perd avec bonheur. La pyramide de verre de Pei, illuminée le soir, vaut à elle seule le détour.', 'Réservez un créneau en ligne et entrez par le Carrousel du Louvre, souvent moins chargé.', false, 'img/s25.jpg', 'Benh LIEU SONG (Flickr) · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Louvre_Museum_Wikimedia_Commons.jpg'),
  ('s26', 'paris', 'Basilique du Sacré-Cœur', 'Activité', 'free', 'Montmartre', '35 Rue du Chevalier de la Barre, 75018 Paris', 'Perchée au sommet de la butte Montmartre, la basilique blanche offre l''un des plus beaux panoramas de Paris depuis son parvis. Autour, les ruelles pavées, la place du Tertre et ses peintres et les escaliers bordés de lampadaires gardent un charme de village.', 'Redescendez par la rue de l''Abreuvoir, l''une des plus jolies de Paris.', false, 'img/s26.jpg', 'Arthur Weidmann · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sacré_Coeur_Façade_1.jpg'),
  ('s27', 'paris', 'Jardin du Luxembourg', 'Activité', 'free', '6e arrondissement', 'Rue de Médicis, 75006 Paris', 'Les fameuses chaises vertes autour du grand bassin, les petits voiliers que poussent les enfants, la fontaine Médicis à l''ombre des platanes : le Luxembourg est le jardin le plus parisien qui soit, devant le Palais du Sénat.', 'Les chaises sont gratuites : installez-vous au bord du bassin avec un livre.', false, 'img/s27.jpg', 'Kirua · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:LuxembourgMontparnasse.JPG'),
  ('s29', 'paris', 'Marché des Enfants Rouges', 'Restaurant', 'p1', 'Le Marais', '39 Rue de Bretagne, 75003 Paris', 'Le plus vieux marché couvert de Paris (1615) se transforme à midi en tour du monde gourmand : couscous, bento japonais, crêpes bretonnes ou cuisine libanaise, à déguster sur de grandes tables partagées au cœur du Haut-Marais.', 'Fermé le lundi. Arrivez avant 12h30 pour avoir une place.', false, 'img/s29.jpg', 'besopha · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Marché_des_Enfants-Rouges,_Paris_May_2016.jpg'),
  ('s30', 'paris', 'Sainte-Chapelle', 'Culture', 'p2', 'Île de la Cité', '10 Boulevard du Palais, 75001 Paris', 'Joyau du gothique construit par Saint Louis, la chapelle haute est entièrement entourée de 1 113 vitraux du XIIIe siècle. Quand le soleil traverse les verrières, la pièce s''embrase de bleus et de rouges : un des moments les plus saisissants de Paris.', 'Venez par une journée ensoleillée, en fin de matinée, pour voir les vitraux s''allumer.', false, 'img/s30.jpg', 'Tiraden · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sainte-Chapelle_de_Paris_vue_du_Palais_de_justice.JPG'),
  ('s31', 'paris', 'Harry''s New York Bar', 'Bar & nuit', 'p2', 'Opéra', '5 Rue Daunou, 75002 Paris', 'Boiseries sombres, fanions d''universités américaines et barmen en veste blanche : ce bar ouvert en 1911 revendique l''invention du Bloody Mary et du Side Car. Hemingway et Gershwin y avaient leurs habitudes ; l''ambiance feutrée n''a presque pas changé.', 'Le piano-bar du sous-sol s''anime en fin de soirée.', false, 'img/s31.jpg', 'Mitch Barrie from Costa Mesa, CA, USA · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Harrys_New_York_Bar_6,_Paris_2012.jpg'),
  ('s32', 'paris', 'Tour Eiffel', 'Activité', 'p2', '7e arrondissement', 'Champ de Mars, 5 Avenue Anatole France, 75007 Paris', 'Monter dans la Dame de fer reste une émotion, surtout par les escaliers jusqu''au 2e étage, quand la ville apparaît peu à peu entre les poutrelles. À la nuit tombée, elle scintille cinq minutes au début de chaque heure : un spectacle à admirer depuis le Trocadéro.', 'Les escaliers jusqu''au 2e étage coûtent moins cher que l''ascenseur et la file est plus courte.', false, 'img/s32.jpg', 'Benh LIEU SONG · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tour_Eiffel_Wikimedia_Commons.jpg'),
  ('s33', 'paris', 'Shakespeare and Company', 'Culture', 'free', 'Quartier latin', '37 Rue de la Bûcherie, 75005 Paris', 'Face à Notre-Dame, cette librairie anglophone mythique est un labyrinthe de livres du sol au plafond, avec un piano, des recoins de lecture et des lits où dorment encore de jeunes écrivains de passage. Un lieu hors du temps pour les amoureux de littérature.', 'Le café voisin, de la même maison, a vue sur la cathédrale.', false, 'img/s33.jpg', 'Shadowgate from Novara, ITALY · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shakespeare_and_Company_bookstore,_Paris_13_August_2013.jpg'),
  ('s34', 'paris', 'Le Procope', 'Restaurant', 'p3', 'Saint-Germain-des-Prés', '13 Rue de l''Ancienne Comédie, 75006 Paris', 'Fondé en 1686, le plus ancien café de Paris a accueilli Voltaire, Diderot et Benjamin Franklin. Dans ses salons rouges aux lustres de cristal, on déguste une cuisine française de tradition, coq au vin en tête, entouré de portraits et de souvenirs révolutionnaires.', 'Demandez une table à l''étage, dans les salons d''époque.', false, 'img/s34.jpg', 'Jean-Marie Hullot from France · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Le_Procope_1,_Paris_2010.jpg'),
  ('s35', 'paris', 'Parc des Buttes-Chaumont', 'Activité', 'free', '19e arrondissement', '1 Rue Botzaris, 75019 Paris', 'Falaises, grotte avec cascade, pont suspendu et temple perché au-dessus d''un lac : le parc le plus spectaculaire de Paris a été sculpté dans une ancienne carrière sous Napoléon III. Les pelouses en pente sont parfaites pour un pique-nique au coucher du soleil.', 'Montez au temple de la Sibylle pour la vue jusqu''au Sacré-Cœur.', false, 'img/s35.jpg', 'O.Taris · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:ParcDesButtesChaumont.JPG'),
  ('par16', 'paris', 'Café de Flore', 'Restaurant', 'p2', 'Saint-Germain-des-Prés', '172 Boulevard Saint-Germain, 75006 Paris', 'Banquettes rouges, miroirs et serveurs en tablier blanc : le Flore est le café littéraire par excellence, où Sartre et Simone de Beauvoir écrivaient chaque jour. On s''y attable pour un chocolat chaud épais ou un croque-monsieur en regardant défiler Saint-Germain.', 'Le premier étage, plus calme, était la salle préférée des écrivains.', false, 'img/par16.jpg', 'Celette · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Café_de_Flore,_172_boulevard_Saint-Germain,_Paris_6e.jpg'),
  ('par17', 'paris', 'Angelina', 'Restaurant', 'p2', 'Tuileries', '226 Rue de Rivoli, 75001 Paris', 'Sous les arcades de la rue de Rivoli, ce salon de thé Belle Époque est célèbre pour son chocolat chaud « L''Africain », presque aussi épais qu''une crème, et son mont-blanc à la crème de marrons. Coco Chanel y avait sa table attitrée.', 'La file avance vite ; la boutique à côté vend le chocolat chaud à emporter.', false, 'img/par17.jpg', 'Robert Schediwy · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:AngelinaParis.JPG'),
  ('par18', 'paris', 'Le Train Bleu', 'Restaurant', 'p3', 'Gare de Lyon', 'Place Louis-Armand, Gare de Lyon, 75012 Paris', 'Au-dessus des quais de la gare de Lyon, ce buffet de 1900 est une folie de dorures, de fresques et de lustres monumentaux qui racontent les destinations du train vers la Méditerranée. Cuisine de brasserie raffinée, gigot découpé en salle et service à l''ancienne.', 'Le bar-salon, moins cher que le restaurant, permet de profiter du décor autour d''un verre.', false, 'img/par18.jpg', 'Arnaud 25 · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Train_bleu_01.jpg'),
  ('par19', 'paris', 'Galeries Lafayette Haussmann', 'Activité', 'free', 'Opéra', '40 Boulevard Haussmann, 75009 Paris', 'Sous une immense coupole Art nouveau aux vitraux colorés, le grand magasin parisien est un spectacle en soi. Montez jusqu''à la terrasse gratuite du dernier étage : vue imprenable sur l''Opéra Garnier, la tour Eiffel et les toits en zinc de Paris.', 'La passerelle de verre sous la coupole donne le vertige : photo garantie.', false, 'img/par19.jpg', 'Benh LIEU SONG (Flickr) · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Galerie_Lafayette_Haussmann_Dome.jpg'),
  ('par20', 'paris', 'Musée de l''Orangerie', 'Culture', 'p1', 'Tuileries', 'Jardin des Tuileries, Place de la Concorde, 75001 Paris', 'Deux salles ovales baignées de lumière naturelle abritent les immenses Nymphéas de Monet, qui vous enveloppent à 360°. Un moment de contemplation unique, complété au sous-sol par des Renoir, Cézanne et Modigliani.', 'Venez à l''ouverture pour profiter des Nymphéas presque seul.', false, 'img/par20.jpg', 'Guilhem Vellut from Paris, France · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Musée_de_l''Orangerie,_Jardin_des_Tuileries,_Paris_8_May_2016.jpg'),
  ('par21', 'paris', 'Musée Rodin', 'Culture', 'p2', '7e arrondissement', '77 Rue de Varenne, 75007 Paris', 'Le Penseur, Le Baiser, La Porte de l''Enfer : les chefs-d''œuvre de Rodin sont exposés dans un hôtel particulier du XVIIIe et surtout dans un grand jardin de roses, où les sculptures dialoguent avec le dôme doré des Invalides.', 'Le billet jardin seul est moins cher et suffit pour voir les plus grandes œuvres.', false, 'img/par21.jpg', 'Dalbera · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Le_musée_Rodin.jpg'),
  ('par22', 'paris', 'Arc de Triomphe', 'Activité', 'p2', 'Champs-Élysées', 'Place Charles de Gaulle, 75008 Paris', 'Après 284 marches, la terrasse de l''Arc offre la vue la plus spectaculaire sur l''étoile des douze avenues et l''axe parfait qui file du Louvre à la Défense. Sous la voûte brûle la flamme du Soldat inconnu, ravivée chaque soir à 18h30.', 'Accès par le passage souterrain : ne traversez jamais le rond-point.', false, 'img/par22.jpg', 'ZeusUpsistos · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Arc_de_Triomphe_-_Août_2026.jpg'),
  ('par23', 'paris', 'Cathédrale Notre-Dame', 'Culture', 'free', 'Île de la Cité', '6 Parvis Notre-Dame, Place Jean-Paul II, 75004 Paris', 'Rouverte en 2024 après l''incendie, Notre-Dame éblouit par sa pierre blonde restaurée, sa nef lumineuse et ses rosaces flamboyantes. Huit siècles d''histoire de France se lisent sur ses portails sculptés et ses gargouilles.', 'Entrée gratuite : réservez un créneau en ligne pour éviter la longue file.', false, 'img/par23.jpg', 'P e z i · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Notre-Dame_de_Paris_2013-07-24.jpg'),
  ('par24', 'paris', 'Place des Vosges', 'Activité', 'free', 'Le Marais', 'Place des Vosges, 75004 Paris', 'La plus ancienne place de Paris aligne 36 pavillons de brique rouge et pierre autour d''un square ombragé. Sous les arcades, galeries d''art et cafés ; au n°6, la maison de Victor Hugo se visite gratuitement.', 'Les pelouses sont ouvertes : parfait pour une pause entre deux balades dans le Marais.', false, 'img/par24.jpg', 'Coyau · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Place_des_Vosges,_Paris,_porte_du_n°_15.JPG'),
  ('par25', 'paris', 'Moulin Rouge', 'Bar & nuit', 'p3', 'Pigalle', '82 Boulevard de Clichy, 75018 Paris', 'Depuis 1889, le moulin aux ailes rouges fait tourner les têtes avec son french cancan, ses plumes, ses strass et ses numéros spectaculaires. Une revue de music-hall où l''on vient pour la démesure et l''esprit fêtard de Pigalle.', 'La revue sans dîner est nettement moins chère ; réservez plusieurs semaines à l''avance.', false, 'img/par25.jpg', 'CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Moulin_rouge.jpg'),
  ('par26', 'paris', 'Caveau de la Huchette', 'Bar & nuit', 'p2', 'Quartier latin', '5 Rue de la Huchette, 75005 Paris', 'Dans une cave voûtée du XVIe siècle, ce club de jazz fait danser le swing et le boogie-woogie depuis 1946. Musiciens live tous les soirs et danseurs de tous âges : l''ambiance qui a inspiré La La Land.', 'L''entrée coûte une quinzaine d''euros ; les meilleurs danseurs arrivent vers 22h.', false, 'img/par26.jpg', 'Richardprins · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Le_Caveau_de_la_Huchette.jpg'),
  ('par27', 'paris', 'Palais Garnier', 'Culture', 'p2', 'Opéra', 'Place de l''Opéra, 75009 Paris', 'Escalier de marbre monumental, grand foyer couvert d''or et plafond peint par Chagall : l''opéra de Napoléon III est un décor de rêve, celui du Fantôme de l''Opéra. La visite libre permet de voir la salle quand il n''y a pas de répétition.', 'Des places de ballet à petit prix sont parfois mises en vente le jour même.', false, 'img/par27.jpg', 'Alexander Hoernigk · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paris_Palais_Garnier_2010-04-06_16.55.07.jpg'),
  ('par28', 'paris', 'Catacombes de Paris', 'Culture', 'p2', '14e arrondissement', '1 Avenue du Colonel Henri Rol-Tanguy, 75014 Paris', 'À 20 mètres sous les rues, un parcours de 1,5 km dans d''anciennes carrières où reposent les ossements de six millions de Parisiens, rangés en murs de crânes et de tibias. Une plongée étonnante et un peu frissonnante dans l''histoire de la ville.', 'Billets horodatés uniquement en ligne ; prévoyez une petite laine, il fait 14°C.', false, 'img/par28.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Catacumbas,_París,_Francia,_2022-11-01,_DD_111-113_HDR.jpg'),
  ('par29', 'paris', 'Marché aux puces de Saint-Ouen', 'Activité', 'free', 'Porte de Clignancourt', 'Rue des Rosiers, 93400 Saint-Ouen', 'Le plus grand marché d''antiquités au monde aligne des centaines de stands : mobilier vintage, affiches anciennes, vinyles, lustres et objets improbables. Même sans rien acheter, se perdre dans ses allées est un vrai voyage dans le temps.', 'Ouvert du samedi au lundi ; le marché Paul Bert est le plus photogénique.', false, 'img/par29.jpg', 'Lektz · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Enseignes_Puces_Saint-Ouen.jpg'),
  ('par30', 'paris', 'Croisière Bateaux-Mouches', 'Activité', 'p2', 'Pont de l''Alma', 'Port de la Conférence, Pont de l''Alma, 75008 Paris', 'Une heure au fil de la Seine pour voir défiler la tour Eiffel, le Louvre, Notre-Dame et une trentaine de ponts. À la tombée de la nuit, quand les monuments s''illuminent, la balade devient franchement magique.', 'Prenez le départ de 21h en été pour voir la tour Eiffel scintiller.', false, 'img/par30.jpg', 'JeanSebastienMouche · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bateau-Mouche-Galere.jpg'),
  ('par31', 'paris', 'La Coupole', 'Restaurant', 'p3', 'Montparnasse', '102 Boulevard du Montparnasse, 75014 Paris', 'Immense brasserie Art déco de 1927 aux piliers peints par les artistes de Montparnasse, La Coupole sert plateaux de fruits de mer, choucroute et curry d''agneau dans un décor qui a vu passer Picasso, Joséphine Baker et Hemingway.', 'Le curry d''agneau est la spécialité historique de la maison.', false, 'img/par31.jpg', 'LPLT · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:La_Coupole_-_Paris.JPG'),
  ('par32', 'paris', 'Les Deux Magots', 'Restaurant', 'p2', 'Saint-Germain-des-Prés', '6 Place Saint-Germain-des-Prés, 75006 Paris', 'Face à la plus vieille église de Paris, ce café mythique a accueilli Verlaine, Rimbaud, Picasso et Hemingway. Sa terrasse est l''une des plus belles de la ville pour observer la vie de Saint-Germain autour d''un chocolat chaud.', 'Le matin, la terrasse est calme et ensoleillée.', false, 'img/par32.jpg', 'David McSpadden from Daly City, United States · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Les_Deux_Magots,_Paris_May_2014.jpg'),
  ('lon01', 'londres', 'British Museum', 'Culture', 'free', 'Bloomsbury', 'Great Russell Street, London WC1B 3DG', 'Sous l''immense verrière de la Great Court, deux millions d''années d''histoire humaine : la pierre de Rosette, les momies égyptiennes, les frises du Parthénon et les échecs vikings de Lewis. Un tour du monde gratuit, à faire en plusieurs fois.', 'Entrée gratuite ; ouvert jusqu''à 20h30 le vendredi.', false, 'img/lon01.jpg', 'Ham · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:British_Museum_from_NE_2.JPG'),
  ('lon02', 'londres', 'National Gallery', 'Culture', 'free', 'Trafalgar Square', 'Trafalgar Square, London WC2N 5DN', 'Face à Trafalgar Square, plus de 2 000 chefs-d''œuvre de la peinture européenne : Les Tournesols de Van Gogh, Les Époux Arnolfini de Van Eyck, Turner, Vermeer et Léonard de Vinci. Tout cela gratuitement, dans des salles somptueuses.', 'Gratuit ; ouvert jusqu''à 21h le vendredi.', false, 'img/lon02.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Galería_Nacional,_Londres,_Inglaterra,_2014-08-07,_DD_036.JPG'),
  ('lon03', 'londres', 'Tate Modern', 'Culture', 'free', 'Bankside', 'Bankside, London SE1 9TG', 'Dans une ancienne centrale électrique au bord de la Tamise, le musée d''art moderne le plus visité au monde expose Picasso, Rothko, Warhol et Louise Bourgeois. Le Turbine Hall accueille des installations géantes et la terrasse du 10e étage offre une vue à 360°.', 'La terrasse panoramique du Blavatnik Building est gratuite.', false, 'img/lon03.jpg', 'Acabashi · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tate_Modern_-_Bankside_Power_Station.jpg'),
  ('lon04', 'londres', 'Natural History Museum', 'Culture', 'free', 'South Kensington', 'Cromwell Road, London SW7 5BD', 'Une cathédrale victorienne de terre cuite consacrée à la nature : squelette de baleine bleue suspendu dans le grand hall, dinosaures animés, météorites et salle des tremblements de terre. Impressionnant à tout âge.', 'Gratuit ; entrez par Exhibition Road pour éviter la file.', false, 'img/lon04.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Museo_de_Historia_Natural,_Londres,_Inglaterra,_2022-11-25,_DD_50-52_HDR.jpg'),
  ('lon05', 'londres', 'Victoria and Albert Museum', 'Culture', 'free', 'South Kensington', 'Cromwell Road, London SW7 2RL', 'Le plus grand musée d''arts décoratifs et de design au monde : mode, bijoux, sculptures, céramiques et salles d''époque. Son café, le premier musée-restaurant au monde, est décoré de céramiques et vitraux victoriens.', 'Ne manquez pas le café historique et le jardin intérieur.', false, 'img/lon05.jpg', 'Photograph by Mike Peel (www.mikepeel.net). · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:At_Victoria_and_Albert_Museum_2024_001.jpg'),
  ('lon06', 'londres', 'Tour de Londres', 'Culture', 'p3', 'Tower Hill', 'Tower Hill, London EC3N 4AB', 'Forteresse, palais royal et prison pendant 900 ans, la Tour abrite les Joyaux de la Couronne et ses célèbres corbeaux. Les Yeomen Warders, en uniforme Tudor, racontent avec humour ses histoires de complots et d''exécutions.', 'La visite guidée gratuite des Beefeaters est incluse et incontournable.', false, 'img/lon06.jpg', '[Duncan] from Nottingham, UK · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tower_of_London_from_the_Shard_(8515883950).jpg'),
  ('lon07', 'londres', 'Tower Bridge', 'Activité', 'p1', 'Tower Hill', 'Tower Bridge Road, London SE1 2UP', 'Le pont le plus célèbre de Londres se traverse gratuitement à pied, mais son exposition permet de marcher sur les passerelles hautes au sol de verre, à 42 mètres au-dessus de la Tamise, et de voir les machines victoriennes qui le lèvent.', 'Consultez les horaires d''ouverture du pont pour le voir se lever.', false, 'img/lon07.jpg', 'Fuzzypiggy · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tower_Bridge_at_Dawn.jpg'),
  ('lon08', 'londres', 'Abbaye de Westminster', 'Culture', 'p2', 'Westminster', '20 Deans Yard, London SW1P 3PA', 'Lieu de tous les couronnements depuis 1066, cette abbaye gothique abrite les tombes de rois et reines, de Newton, Darwin et Dickens dans le coin des poètes. Ses voûtes en éventail sont d''une finesse incroyable.', 'Assistez gratuitement à l''office chanté du soir (Evensong) pour entendre le chœur.', false, 'img/lon08.jpg', 'Antiquary · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Westminster_Abbey,_Westminster.jpg'),
  ('lon09', 'londres', 'Big Ben et Westminster', 'Activité', 'free', 'Westminster', 'Westminster Bridge Road, London SW1A 0AA', 'La tour de l''horloge la plus célèbre du monde et le palais néogothique du Parlement se contemplent le mieux depuis le pont de Westminster ou la rive sud. Le carillon de Big Ben sonne toutes les quinze minutes.', 'La plus belle photo se prend depuis la rive sud, près du London Eye.', false, 'img/lon09.jpg', 'Christian David · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Elizabeth_Tower_and_the_north_front_of_the_Palace_of_Westminster,_London.jpg'),
  ('lon10', 'londres', 'Buckingham Palace', 'Activité', 'free', 'Westminster', 'Buckingham Palace, London SW1A 1AA', 'La résidence officielle du roi se découvre surtout pendant la relève de la garde, avec fanfare, bonnets à poils et uniformes rouges. L''été, les salons d''apparat se visitent quand la famille royale est absente.', 'Relève de la garde vers 11h certains jours : vérifiez le calendrier.', false, 'img/lon10.jpg', 'Julian Herzog (Website) · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Buckingham_Palace_London_Morning_2020_01_(cropped).jpg'),
  ('lon11', 'londres', 'Hyde Park', 'Activité', 'free', 'Mayfair', 'Hyde Park, London W2 2UH', 'Le plus célèbre parc royal de Londres s''étend sur 142 hectares : barques sur la Serpentine, Speakers'' Corner où chacun peut prendre la parole, mémorial de Diana et écureuils peu farouches. L''hiver, il accueille un grand marché de Noël.', 'Louez une barque ou un pédalo sur la Serpentine.', false, 'img/lon11.jpg', '@LondonNPC #NationalParkCity · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hyde_Park_London_from_the_air.jpg'),
  ('lon12', 'londres', 'Camden Market', 'Restaurant', 'p1', 'Camden', 'Camden Lock Place, London NW1 8AF', 'Le long du canal de Regent''s, ce marché alternatif mêle boutiques punk, fripes vintage et des dizaines de stands de street food du monde entier. L''ambiance rock de Camden, entre écluses et anciennes écuries, est unique.', 'Venez en semaine pour éviter la foule du week-end.', false, 'img/lon12.jpg', 'en:User:Grim23 · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Camden_markets_entrance.JPG'),
  ('lon13', 'londres', 'Borough Market', 'Restaurant', 'p1', 'Southwark', '8 Southwark Street, London SE1 1TL', 'Le plus vieux marché alimentaire de Londres, sous des arches de fer près du London Bridge, est le paradis des gourmands : sandwichs au fromage grillé, huîtres, pies, currys et pâtisseries. On goûte, on grignote, on recommence.', 'Venez à l''heure du déjeuner en semaine ; certains stands ferment le lundi.', true, 'img/lon13.jpg', 'Øyvind Holmstad · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:London_2018_March_IMG_0663.jpg'),
  ('lon14', 'londres', 'Covent Garden', 'Activité', 'free', 'Covent Garden', 'The Piazza, London WC2E 8RF', 'Autour d''une halle de marché du XIXe siècle, la piazza de Covent Garden vibre avec ses artistes de rue, ses boutiques et l''Opéra royal. Ruelles pavées et petites cours comme Neal''s Yard, toute en couleurs, sont à deux pas.', 'Ne manquez pas Neal''s Yard, une petite cour colorée cachée.', false, 'img/lon14.jpg', 'Covent_Garden_Interior_May_2006.jpg: Diliff derivative wo... · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Covent_Garden_Interior_May_2006_crop.jpg'),
  ('lon15', 'londres', 'Cathédrale Saint-Paul', 'Culture', 'p2', 'City of London', 'St Paul''s Churchyard, London EC4M 8AD', 'Le chef-d''œuvre baroque de Christopher Wren et son dôme emblématique ont survécu au Blitz. Montez jusqu''à la Golden Gallery, à 85 mètres, en passant par la galerie des murmures où un chuchotement traverse le dôme.', 'La terrasse du centre commercial One New Change, juste en face, offre une vue gratuite sur le dôme.', false, 'img/lon15.jpg', 'Mark Fosh · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:St_Pauls_aerial_(cropped).jpg'),
  ('lon16', 'londres', 'Sky Garden', 'Activité', 'free', 'City of London', '1 Sky Garden Walk, London EC3M 8AD', 'Au sommet du gratte-ciel « Walkie-Talkie », un jardin tropical sous verrière offre une vue panoramique gratuite sur la Tamise, Tower Bridge et le Shard. Bars et restaurants permettent d''y prolonger la soirée.', 'Gratuit sur réservation en ligne, ouverte environ trois semaines avant.', false, 'img/lon16.jpg', 'Colin · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Walkie-Talkie_-_Sept_2015_(cropped).jpg'),
  ('lon17', 'londres', 'Observatoire royal de Greenwich', 'Culture', 'p2', 'Greenwich', 'Blackheath Avenue, London SE10 8XJ', 'Ici passe le méridien de Greenwich, et l''on peut se tenir un pied dans chaque hémisphère. Depuis la colline du parc, la vue sur les gratte-ciel de Canary Wharf et le Old Royal Naval College est l''une des plus belles de Londres.', 'Venez en bateau sur la Tamise ; la vue du parc est gratuite.', false, 'img/lon17.jpg', 'CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Royal_observatory_greenwich.jpg'),
  ('lon18', 'londres', 'Portobello Road', 'Activité', 'free', 'Notting Hill', 'Portobello Road, London W11 1LJ', 'Entre maisons pastel de Notting Hill, cette rue accueille le plus célèbre marché d''antiquités au monde : argenterie, cartes anciennes, vêtements vintage et stands de street food. Le samedi, toute la rue devient un immense marché.', 'Le samedi matin pour les antiquaires ; les rues voisines aux façades colorées sont superbes.', false, 'img/lon18.jpg', 'Schellack at English Wikipedia · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Portobello_road_sign.jpg'),
  ('lon19', 'londres', 'Ye Olde Cheshire Cheese', 'Bar & nuit', 'p1', 'Fleet Street', '145 Fleet Street, London EC4A 2BU', 'Reconstruit juste après le grand incendie de 1666, ce pub labyrinthique aux salles sombres, cheminées et sciure au sol a vu passer Dickens, Mark Twain et Conan Doyle. On y boit une ale dans une ambiance hors du temps.', 'Descendez dans les caves voûtées, les salles les plus atmosphériques.', false, 'img/lon19.jpg', 'Banjobacon at English Wikipedia · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Yeoldcheshirecheese.jpg'),
  ('lon20', 'londres', 'The Churchill Arms', 'Bar & nuit', 'p1', 'Kensington', '119 Kensington Church Street, London W8 7LN', 'Sa façade entièrement couverte de fleurs en fait le pub le plus photographié de Londres. À l''intérieur, objets de Churchill accrochés au plafond, bière pression et, surprise, une excellente cuisine thaïe dans la véranda.', 'La cuisine thaïe de la véranda est délicieuse et abordable.', false, 'img/lon20.jpg', 'CVB · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:119_Kensington_Church_Street.jpg'),
  ('lon21', 'londres', 'The George Inn', 'Bar & nuit', 'p1', 'Southwark', '75-77 Borough High Street, London SE1 1NH', 'Le dernier relais de diligences à galeries de Londres, du XVIIe siècle, appartient au National Trust. Sa cour pavée et ses salles basses lambrissées, que fréquentait Dickens, sont parfaites pour une pinte après Borough Market.', 'En été, la cour se remplit dès la sortie des bureaux.', false, 'img/lon21.jpg', 'Ewan Munro from London, UK · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:The_George_Inn_1.jpg'),
  ('lon23', 'londres', 'Fortnum & Mason', 'Restaurant', 'p2', 'Piccadilly', '181 Piccadilly, London W1A 1ER', 'Fournisseur de la Couronne depuis 1707, ce grand magasin vert d''eau est le temple du thé anglais. On y prend un afternoon tea complet ou on choisit simplement des biscuits, confitures et thés dans de superbes boîtes.', 'Le Parlour du rez-de-chaussée sert des glaces et scones à prix plus doux que le salon de thé.', false, 'img/lon23.jpg', 'Tony Hisgett from Birmingham, UK · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fortnum_and_Mason.jpg'),
  ('lon25', 'londres', 'Brick Lane', 'Restaurant', 'p1', 'Shoreditch', 'Brick Lane, London E1 6RF', 'Rue phare de l''East End, Brick Lane mêle curry houses bangladaises, bagels ouverts 24h/24, street art et marché vintage le dimanche. Le Beigel Bake sert ses bagels au bœuf salé depuis des décennies pour quelques livres.', 'Le Beigel Bake (n°159) est ouvert jour et nuit.', false, 'img/lon25.jpg', 'James Cridland · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Brick_Lane_street_signs.JPG'),
  ('lon26', 'londres', 'Kew Gardens', 'Activité', 'p2', 'Kew', 'Kew, Richmond, London TW9 3AE', 'Classé à l''UNESCO, le plus célèbre jardin botanique du monde déploie ses serres victoriennes géantes, sa pagode chinoise et un chemin suspendu dans la canopée des arbres. Une journée entière de verdure.', 'Le « Treetop Walkway » à 18 mètres de haut est inclus.', false, 'img/lon26.jpg', 'Diliff · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kew_Gardens_Palm_House,_London_-_July_2009.jpg'),
  ('lon27', 'londres', 'Harrods', 'Restaurant', 'p2', 'Knightsbridge', '87-135 Brompton Road, London SW1X 7XL', 'Le grand magasin le plus célèbre du monde vaut le détour pour ses Food Halls aux plafonds carrelés Art nouveau, où l''on déguste huîtres, sushis, pâtisseries et chocolats. Le soir, la façade s''illumine de milliers d''ampoules.', 'La façade illuminée vaut la photo à la nuit tombée.', false, 'img/lon27.jpg', 'user: Sokkk y · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Harrods_(London).jpg'),
  ('lon28', 'londres', 'Shakespeare''s Globe', 'Culture', 'p1', 'Bankside', '21 New Globe Walk, London SE1 9DT', 'Réplique fidèle du théâtre de Shakespeare, en bois et toit de chaume, au bord de la Tamise. Voir une pièce debout dans la fosse, comme au temps d''Élisabeth Ier, est une expérience unique et étonnamment abordable.', 'Les places debout coûtent environ 5 £ : réservez tôt.', false, 'img/lon28.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Restaurante_The_Swan,_Londres,_Inglaterra,_2014-08-11,_DD_113.jpg'),
  ('lon29', 'londres', 'Primrose Hill', 'Activité', 'free', 'Primrose Hill', 'Primrose Hill Road, London NW1 4NR', 'Cette colline herbeuse au nord de Regent''s Park offre l''une des plus belles vues gratuites sur la skyline de Londres. Le quartier voisin, aux maisons pastel et cafés, est l''un des plus charmants de la ville.', 'Montez-y au coucher du soleil avec un pique-nique.', false, 'img/lon29.jpg', 'Louise Ireland · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Primrose_Hill,_London_-16Sept2010.jpg'),
  ('lon30', 'londres', 'Leadenhall Market', 'Activité', 'free', 'City of London', 'Gracechurch Street, London EC3V 1LT', 'Ce marché couvert victorien, tout en fer forgé peint, verrières et pavés, a servi de décor à Harry Potter. À l''heure du déjeuner, les employés de la City s''y retrouvent dans les pubs et les petits restaurants.', 'Venez en semaine : le week-end, beaucoup de boutiques sont fermées.', false, 'img/lon30.jpg', 'Diliff · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Leadenhall_Market_In_London_-_Feb_2006_rotated.jpg'),
  ('lon31', 'londres', 'Tate Britain', 'Culture', 'free', 'Pimlico', 'Millbank, London SW1P 4RG', 'Cinq siècles d''art britannique, des préraphaélites à Turner et Hockney, dans un palais au bord de la Tamise. Bien plus calme que les grands musées.', 'Les salles Turner sont un trésor.', false, 'img/lon31.jpg', 'Tony Hisgett from Birmingham, UK · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tate_Britain_(5822081512)_(2).jpg'),
  ('lon32', 'londres', 'Columbia Road Flower Market', 'Activité', 'free', 'Shoreditch', 'Columbia Road, London E2 7RG', 'Chaque dimanche matin, une rue victorienne se couvre de fleurs et de plantes, au son des marchands qui crient leurs prix. Cafés et boutiques ravissants autour.', 'Le dimanche de 8h à 15h ; les meilleures affaires arrivent en fin de marché.', false, 'img/lon32.jpg', 'AgnosticPreachersKid · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1800_block_of_Columbia_Road.JPG'),
  ('mad01', 'madrid', 'Museo del Prado', 'Culture', 'p2', 'Paseo del Prado', 'Calle de Ruiz de Alarcón 23, 28014 Madrid', 'L''un des plus grands musées du monde réunit Les Ménines de Velázquez, les peintures noires de Goya et Le Jardin des délices de Jérôme Bosch. Chaque salle est une leçon de peinture, de Titien à Rubens.', 'Gratuit les deux dernières heures du jour : arrivez un peu avant l''ouverture gratuite.', false, 'img/mad01.jpg', 'Emilio J. Rodríguez Posada · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Museo_del_Prado_2016_(25185969599).jpg'),
  ('mad02', 'madrid', 'Museo Reina Sofía', 'Culture', 'p1', 'Atocha', 'Calle de Santa Isabel 52, 28012 Madrid', 'Le musée d''art moderne de Madrid abrite Guernica de Picasso, cri contre la guerre d''une puissance intacte, ainsi que Dalí et Miró. Ses ascenseurs de verre et son patio arboré valent aussi le détour.', 'Gratuit certains soirs de semaine et le dimanche après-midi.', false, 'img/mad02.jpg', 'Ввласенко · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lunar_Bird_by_Joan_Miró_in_the_Patio_of_the_Reina_Sofía_National_Art_Center_Museum.jpg'),
  ('mad03', 'madrid', 'Museo Thyssen-Bornemisza', 'Culture', 'p1', 'Paseo del Prado', 'Paseo del Prado 8, 28014 Madrid', 'La collection privée la plus riche du monde parcourt sept siècles d''art, des primitifs italiens à Hopper et Lichtenstein, en passant par les impressionnistes. Le complément parfait au Prado et au Reina Sofía.', 'La collection permanente est gratuite le lundi.', false, 'img/mad03.jpg', 'Luis García (Zaqarbal) · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Museo_Thyssen-Bornemisza_(Madrid)_07.jpg'),
  ('mad04', 'madrid', 'Palais royal', 'Culture', 'p1', 'Ópera', 'Calle de Bailén, 28071 Madrid', 'Avec plus de 3 000 pièces, c''est le plus grand palais royal d''Europe occidentale. Salle du trône, salle de porcelaine et armurerie royale éblouissent ; devant, les jardins de Sabatini et la vue sur la sierra.', 'Gratuit pour les citoyens de l''UE certains soirs de semaine.', false, 'img/mad04.jpg', 'Tim Adams · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palacio_Real_de_Madrid_Julio_2016_(cropped).jpg'),
  ('mad05', 'madrid', 'Parque del Retiro', 'Activité', 'free', 'Retiro', 'Plaza de la Independencia 7, 28001 Madrid', 'Le grand parc de Madrid, classé à l''UNESCO, invite à ramer sur le grand étang devant le monument d''Alphonse XII, à flâner dans la roseraie ou à écouter les musiciens le dimanche. Un poumon vert indispensable par temps chaud.', 'Louez une barque sur l''étang en fin de journée.', false, 'img/mad05.jpg', 'PepeZoom · CC BY-SA 3.0 es · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palacio_de_Cristal.jpg'),
  ('mad06', 'madrid', 'Palacio de Cristal', 'Culture', 'free', 'Retiro', 'Paseo de Venezuela, 28009 Madrid', 'Au cœur du Retiro, ce palais de verre et de fer de 1887 se reflète dans un étang où nagent tortues et canards. Il accueille gratuitement des installations d''art contemporain baignées de lumière.', 'Gratuit ; la lumière de fin d''après-midi est magique.', false, 'img/mad06.jpg', 'Carlos Delgado · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palacio_de_Cristal_-_01.jpg'),
  ('mad07', 'madrid', 'Plaza Mayor', 'Activité', 'free', 'Centro', 'Plaza Mayor, 28012 Madrid', 'Cette grande place à arcades du XVIIe siècle, entourée de façades rouges à balcons, a accueilli corridas, couronnements et autodafés. On y croque le célèbre bocadillo de calamares dans les bars alentour.', 'Mangez un sandwich aux calamars dans les rues voisines, bien moins cher que sur la place.', false, 'img/mad07.jpg', 'Sebastian Dubiel · CC BY-SA 3.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Plaza_Mayor_de_Madrid_06.jpg'),
  ('mad08', 'madrid', 'Puerta del Sol', 'Activité', 'free', 'Centro', 'Puerta del Sol, 28013 Madrid', 'Le kilomètre zéro des routes espagnoles est le cœur battant de Madrid. On y trouve la statue de l''ours à l''arbousier, symbole de la ville, et l''horloge dont les douze coups rythment le Nouvel An de toute l''Espagne.', 'Cherchez la plaque du kilomètre zéro sur le trottoir.', false, 'img/mad08.jpg', 'Alfredo Urdaci / PromoMadrid · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MADRID_100206_UDCI_023.jpg'),
  ('mad09', 'madrid', 'Mercado de San Miguel', 'Restaurant', 'p2', 'Centro', 'Plaza de San Miguel, 28005 Madrid', 'Sous une élégante structure de fer et de verre de 1916, ce marché gastronomique propose huîtres, jamón ibérico, croquetas, olives farcies et vermouth. On grignote debout, un verre à la main, à deux pas de la Plaza Mayor.', 'Venez en fin d''après-midi en semaine pour éviter la cohue.', false, 'img/mad09.jpg', 'Fernando · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mercado_de_San_Miguel_2025.jpg'),
  ('mad10', 'madrid', 'Chocolatería San Ginés', 'Restaurant', 'p1', 'Centro', 'Pasadizo de San Ginés 5, 28013 Madrid', 'Depuis 1894, cette chocolaterie aux murs de miroirs sert jour et nuit les meilleurs churros de Madrid, à tremper dans un chocolat chaud épais comme une crème. Les Madrilènes y finissent leurs nuits au petit matin.', 'Essayez les porras, des churros plus épais et moelleux.', true, 'img/mad10.jpg', 'Tamorlan · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chocolatería_"San_Gines"-Madrid-2009.jpg'),
  ('mad11', 'madrid', 'Sobrino de Botín', 'Restaurant', 'p3', 'La Latina', 'Calle de los Cuchilleros 17, 28005 Madrid', 'Fondé en 1725, c''est le plus vieux restaurant du monde selon le Guinness. Son four à bois d''origine rôtit cochon de lait et agneau de lait comme au XVIIIe siècle ; Goya y aurait été plongeur et Hemingway y a situé une scène.', 'Réservez et demandez une table dans la cave voûtée.', false, 'img/mad11.jpg', 'Ank Kumar · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2014_-_Sobrino_de_Botín_(Casa_Botín)_Restaurant,_Madrid,_Spain_(_Ank_Kumar_)_03.jpg'),
  ('mad12', 'madrid', 'Templo de Debod', 'Activité', 'free', 'Moncloa', 'Calle de Ferraz 1, 28008 Madrid', 'Un authentique temple égyptien de 2 200 ans, offert par l''Égypte, se reflète dans un bassin au sommet d''un parc. C''est le meilleur spot de Madrid pour le coucher du soleil, quand le ciel s''embrase derrière le temple.', 'Venez au coucher du soleil ; l''intérieur se visite gratuitement.', false, 'img/mad12.jpg', 'https://www.flickr.com/photos/jiuguangw · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Templo_de_Debod_in_Madrid.jpg'),
  ('mad13', 'madrid', 'El Rastro', 'Activité', 'free', 'La Latina', 'Calle de la Ribera de Curtidores, 28005 Madrid', 'Chaque dimanche matin, le plus célèbre marché aux puces d''Espagne envahit les rues en pente de La Latina : antiquités, vinyles, vêtements et bric-à-brac. On finit traditionnellement par un vermouth et des tapas dans le quartier.', 'Dimanche matin seulement ; finissez par l''apéro sur la Cava Baja.', false, 'img/mad13.jpg', 'Nicolas Vigier · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:El_Rastro_de_Madrid_50.jpg'),
  ('mad14', 'madrid', 'Gran Vía', 'Activité', 'free', 'Centro', 'Gran Vía, 28013 Madrid', 'Le « Broadway madrilène » aligne immeubles Belle Époque et Art déco, théâtres de comédies musicales et enseignes lumineuses. L''édifice Metrópolis et sa coupole dorée marquent son entrée, avec des rooftops pour l''admirer.', 'Le rooftop gratuit du magasin El Corte Inglés de Callao a une belle vue.', false, 'img/mad14.jpg', 'Alfredo Urdaci / PromoMadrid · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MADRID_100206_UDCI_019.jpg'),
  ('mad15', 'madrid', 'Círculo de Bellas Artes', 'Activité', 'p1', 'Centro', 'Calle de Alcalá 42, 28014 Madrid', 'Le toit de ce centre culturel offre l''une des plus belles vues sur Madrid, avec la coupole de l''édifice Metrópolis au premier plan et la statue de Minerve qui veille au-dessus. On y prend un verre face à la ville.', 'L''accès à la terrasse coûte quelques euros ; venez au coucher du soleil.', false, 'img/mad15.jpg', 'Luis García (Zaqarbal) · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Círculo_de_Bellas_Artes_(Madrid)_06.jpg'),
  ('mad16', 'madrid', 'Stade Santiago Bernabéu', 'Activité', 'p2', 'Chamartín', 'Avenida de Concha Espina 1, 28036 Madrid', 'Le stade du Real Madrid, entièrement rénové avec sa façade métallique futuriste, se visite : vestiaires, pelouse, salle des trophées et ses 15 Ligues des champions. Un pèlerinage pour tout fan de foot.', 'Réservez la visite en ligne, surtout les jours de match.', false, 'img/mad16.jpg', 'Carlos Delgado · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Estadio_Santiago_Bernabéu_-_01.jpg'),
  ('mad17', 'madrid', 'Cathédrale de l''Almudena', 'Culture', 'free', 'Ópera', 'Calle de Bailén 10, 28013 Madrid', 'Face au Palais royal, cette cathédrale achevée seulement en 1993 surprend par son intérieur coloré et ses vitraux modernes. Sa coupole se visite et offre une vue sur le palais et la Casa de Campo.', 'L''entrée est gratuite ; la coupole est payante.', false, 'img/mad17.jpg', 'Fernando · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Almudena_2022_-_overview.jpg'),
  ('mad18', 'madrid', 'Mercado de San Antón', 'Restaurant', 'p1', 'Chueca', 'Calle de Augusto Figueroa 24, 28004 Madrid', 'Au cœur du quartier festif de Chueca, ce marché moderne sur trois étages mêle étals de produits frais, comptoirs de tapas du monde et une terrasse sur le toit idéale pour l''apéritif.', 'La terrasse du dernier étage est parfaite en soirée.', false, 'img/mad18.jpg', 'Earlyspatz · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mercado_de_San_Anton_during_World_Pride.jpg'),
  ('mad19', 'madrid', 'Casa Labra', 'Restaurant', 'p1', 'Centro', 'Calle de Tetuán 12, 28013 Madrid', 'Depuis 1860, cette taverne sert ses célèbres croquettes de morue (soldaditos de Pavía) au comptoir. C''est ici que fut fondé le Parti socialiste espagnol en 1879. Ambiance de bar de quartier, à deux pas de la Puerta del Sol.', 'Commandez au comptoir de gauche, réglez au fur et à mesure.', false, 'img/mad19.jpg', 'Tamorlan · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Casa_Labra-2009.jpg'),
  ('mad20', 'madrid', 'Lhardy', 'Restaurant', 'p3', 'Centro', 'Carrera de San Jerónimo 8, 28014 Madrid', 'Depuis 1839, ce restaurant au décor d''époque sert le cocido madrileño, ragoût de pois chiches et viandes en trois services. Au rez-de-chaussée, la boutique propose un bouillon chaud servi d''un samovar d''argent.', 'Le bouillon de la boutique du rez-de-chaussée est une tradition hivernale.', false, 'img/mad20.jpg', 'Tamorlan · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Restaurante_Lhardy-2009.jpg'),
  ('mad21', 'madrid', 'Café Gijón', 'Restaurant', 'p2', 'Recoletos', 'Paseo de Recoletos 21, 28004 Madrid', 'Ouvert en 1888, ce café littéraire aux banquettes de velours et colonnes de bois a été le repaire des écrivains de la Génération de 27 et de Lorca. Sa terrasse sur le Paseo de Recoletos est idéale pour un café.', 'Le menu du jour en semaine est une bonne affaire.', false, 'img/mad21.jpg', 'Roberto Garcia · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Café_Gijón.jpg'),
  ('mad22', 'madrid', 'Matadero Madrid', 'Culture', 'free', 'Arganzuela', 'Plaza de Legazpi 8, 28045 Madrid', 'Les anciens abattoirs néo-mudéjars au bord du Madrid Río sont devenus un centre de création contemporaine : expositions, théâtre, cinéma et marchés de créateurs dans des halles de brique spectaculaires.', 'Combinez avec une balade dans le parc Madrid Río.', false, 'img/mad22.jpg', 'Tamorlan · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Casa_Terneras-Matadero-Legazpi.JPG'),
  ('mad23', 'madrid', 'Madrid Río', 'Activité', 'free', 'Arganzuela', 'Paseo de la Ermita del Santo, 28011 Madrid', 'Un parc linéaire de dix kilomètres le long du Manzanares, né de l''enfouissement d''une autoroute. Ponts design, plages urbaines avec jets d''eau et pistes cyclables en font le terrain de jeu des Madrilènes.', 'Louez un vélo public BiciMAD pour le parcourir.', false, 'img/mad23.jpg', 'Nicolas Vigier · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Madrid_in_May_2017_64_edited.jpg'),
  ('mad24', 'madrid', 'Real Jardín Botánico', 'Activité', 'p1', 'Paseo del Prado', 'Plaza de Murillo 2, 28014 Madrid', 'À côté du Prado, ce jardin du XVIIIe siècle abrite des milliers de plantes en terrasses, des serres et des arbres centenaires. Un havre de calme parfait entre deux musées.', 'L''entrée coûte quelques euros ; venez au printemps pour les floraisons.', false, 'img/mad24.jpg', 'FDV · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jardin-Botanico-Madrid-Linneo.jpg'),
  ('mad25', 'madrid', 'Corral de la Morería', 'Bar & nuit', 'p3', 'La Latina', 'Calle de la Morería 17, 28005 Madrid', 'Considéré comme le meilleur tablao flamenco du monde, il accueille depuis 1956 les plus grands danseurs, guitaristes et chanteurs. Dans une salle intime, la passion du flamenco se vit à quelques mètres.', 'La formule spectacle avec boisson est moins chère que le dîner.', false, 'img/mad25.jpg', 'Carlos Ramón Bonilla… · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:CORRAL_DE_LA_MORERIA_-_MADRID_-_panoramio.jpg'),
  ('mad27', 'madrid', 'Soirée à Malasaña', 'Bar & nuit', 'p1', 'Malasaña', 'Plaza del Dos de Mayo, 28004 Madrid', 'Berceau de la Movida des années 1980, Malasaña reste le quartier bohème de Madrid : bars indés, friperies, cafés et terrasses autour de la Plaza del Dos de Mayo. La nuit commence tard et finit très tard.', 'Les Madrilènes sortent rarement avant 23h.', false, 'img/mad27.jpg', 'Matiaest · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Monumento_a_Daoiz_y_Velarde_en_la_Plaza_del_2_de_Mayo_de_Madrid.jpg'),
  ('mad29', 'madrid', 'Museo Sorolla', 'Culture', 'p1', 'Chamberí', 'Paseo del General Martínez Campos 37, 28010 Madrid', 'La maison-atelier du peintre de la lumière méditerranéenne a gardé ses pinceaux, ses meubles et son jardin andalou. Ses toiles de plages ensoleillées sont exposées dans les pièces où il vivait.', 'Le jardin andalou est un havre de fraîcheur.', false, 'img/mad29.jpg', 'Luis García (Zaqarbal) · CC BY-SA 3.0 es · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Museo_Sorolla_(Madrid)_02.jpg'),
  ('mad30', 'madrid', 'Palacio de Cibeles', 'Activité', 'free', 'Retiro', 'Plaza de Cibeles 1, 28014 Madrid', 'Ancien palais des postes devenu mairie, cet édifice blanc spectaculaire domine la fontaine de Cybèle, où les supporters du Real fêtent les victoires. Son mirador au 8e étage offre une vue panoramique sur Madrid.', 'Le mirador est payant mais à petit prix ; réservez le créneau.', false, 'img/mad30.jpg', 'Carlos Delgado · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palacio_de_Comunicaciones_-_46.jpg'),
  ('mad31', 'madrid', 'Faro de Moncloa', 'Activité', 'p1', 'Moncloa', 'Avenida de la Memoria 2, 28040 Madrid', 'Une tour d''observation de 110 mètres qui offre une vue panoramique sur tout Madrid et la sierra de Guadarrama.', 'Vue superbe au coucher du soleil.', false, 'img/mad31.jpg', 'Carlos Delgado · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Faro_de_la_Moncloa_-_06.jpg'),
  ('mad32', 'madrid', 'Musée archéologique national', 'Culture', 'p1', 'Salamanca', 'Calle de Serrano 13, 28001 Madrid', 'Rénové de fond en comble, ce musée retrace l''histoire de la péninsule Ibérique, de la préhistoire au Moyen Âge. Son trésor : la Dame d''Elche, buste ibère mystérieux de 2 500 ans, et une réplique de la grotte d''Altamira.', 'Gratuit le samedi après-midi et le dimanche matin.', false, 'img/mad32.jpg', 'Jean-Pierre Dalbéra from Paris, France · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dama_de_Elche_(Musée_archéologique_national,_Madrid)_(4656548153).jpg'),
  ('s09', 'barcelone', 'Bunkers del Carmel', 'Activité', 'free', 'El Carmel', 'Carrer de Marià Labèrnia, 08032 Barcelona', 'Au sommet du Turó de la Rovira, les vestiges d''une batterie antiaérienne de la guerre civile offrent la vue la plus spectaculaire de Barcelone : de la Sagrada Família à la mer, tout se déploie à 360°. Au coucher du soleil, l''endroit devient le rendez-vous des Barcelonais.', 'Prévoyez une lampe pour la descente après le coucher du soleil.', false, 'img/s09.jpg', 'Barcelonatips · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bunkers_del_Carmel_Barcelona.jpg'),
  ('s10', 'barcelone', 'Sagrada Família', 'Culture', 'p2', 'Eixample', 'Carrer de Mallorca 401, 08013 Barcelona', 'Le chef-d''œuvre inachevé de Gaudí est une forêt de pierre : à l''intérieur, les colonnes se ramifient comme des arbres et les vitraux inondent la nef de lumières vertes, bleues et orangées. Une émotion qui marque à vie, même pour ceux qui ne sont pas fans d''architecture.', 'Billets uniquement en ligne en haute saison ; la lumière est la plus belle en fin d''après-midi.', true, 'img/s10.jpg', 'Matti Blume · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sagrada_Familia,_Barcelona_(P1170693).jpg'),
  ('s12', 'barcelone', 'Mercat de la Boqueria', 'Restaurant', 'p1', 'La Rambla', 'La Rambla 91, 08001 Barcelona', 'Sous sa verrière moderniste, le marché le plus célèbre de Barcelone déborde de fruits colorés, de jambons ibériques et de fruits de mer. Les petits comptoirs comme El Quim servent des tapas minute : œufs au chorizo, calamars et seiches à la plancha.', 'Les stands du fond sont moins chers que ceux de l''entrée ; fermé le dimanche.', false, 'img/s12.jpg', 'Moheen Reeyad · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Entrance_to_Mercat_de_la_Boqueria_(01).jpg'),
  ('s47', 'barcelone', 'Park Güell', 'Activité', 'p2', 'Gràcia', 'Carrer d''Olot, 08024 Barcelona', 'Le parc imaginé par Gaudí est un monde de conte de fées : pavillons en pain d''épices, salamandre en mosaïque et grand banc ondulé couvert de céramiques, face à la ville et à la mer. Les allées sur viaducs de pierre semblent pousser de la colline.', 'Réservez le premier créneau du matin pour éviter la foule.', false, 'img/s47.jpg', 'Canaan · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Güell_BCN_edited.jpg'),
  ('s48', 'barcelone', 'Casa Batlló', 'Culture', 'p2', 'Eixample', 'Passeig de Gràcia 43, 08007 Barcelona', 'Balcons en forme de masques, façade écaillée comme un dragon et toit ondulé en céramique : la maison la plus fantaisiste de Gaudí s''inspire de la mer. L''intérieur, sans angle droit, joue avec la lumière et des bleus de plus en plus intenses.', 'La façade s''admire gratuitement de nuit, quand elle est éclairée.', false, 'img/s48.jpg', 'Enfo · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:05_Casa_Batlló.jpg'),
  ('s49', 'barcelone', 'Museu Picasso', 'Culture', 'p2', 'El Born', 'Carrer de Montcada 15-23, 08003 Barcelona', 'Cinq palais gothiques de la rue Montcada racontent la jeunesse de Picasso à Barcelone, de ses dessins d''enfant à la série des Ménines. Un musée idéal pour comprendre comment le génie est né.', 'Gratuit le jeudi en fin d''après-midi, sur réservation.', false, 'img/s49.jpg', 'Pere López · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palau_Berenguer_d''Aguilar.jpg'),
  ('s50', 'barcelone', 'Plage de la Barceloneta', 'Activité', 'free', 'La Barceloneta', 'Platja de la Barceloneta, 08003 Barcelona', 'À dix minutes à pied de la vieille ville, la plage urbaine la plus animée de Barcelone mêle baigneurs, joueurs de volley et chiringuitos où l''on boit un tinto de verano les pieds dans le sable. L''ancien quartier de pêcheurs juste derrière cache d''excellents bars à tapas.', 'Remontez vers la Nova Icària pour plus de place.', false, 'img/s50.jpg', 'Kuba Bożanowski from Warsaw, Poland · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Barcelona_(16877599244).jpg'),
  ('s51', 'barcelone', 'Colline de Montjuïc', 'Activité', 'free', 'Sants-Montjuïc', 'Parc de Montjuïc, 08038 Barcelona', 'La colline verte qui domine le port rassemble jardins, musées, installations olympiques et un château avec vue sur la mer. On y monte par des escalators depuis la Plaça d''Espanya ou en téléphérique depuis la plage.', 'Montez par les escalators depuis la Plaça d''Espanya.', false, 'img/s51.jpg', 'Didier Descouens · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:(Barcelona)_Palau_Nacional_de_Montjuïc_-_La_cúpula_central_vista_des_de_la_terrassa_oest.jpg'),
  ('s54', 'barcelone', 'Palau de la Música Catalana', 'Culture', 'p2', 'Sant Pere', 'Carrer del Palau de la Música 4-6, 08003 Barcelona', 'Cette salle de concert moderniste est une explosion de mosaïques, de sculptures et de vitraux, couronnée d''une verrière en forme de soleil inversé. Y écouter un concert, guitare espagnole ou orchestre, est une expérience inoubliable.', 'Un billet de concert coûte parfois moins cher que la visite guidée.', false, 'img/s54.jpg', 'Ralf Roletschek · GFDL 1.2 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:22_11_01_Palau_DSCF2611_52502512616_cc1e7db845_k.jpg'),
  ('s56', 'barcelone', 'Balade dans le Barri Gòtic', 'Activité', 'free', 'Barri Gòtic', 'Plaça Nova, 08002 Barcelona', 'Ruelles médiévales, passages couverts, palais gothiques et places secrètes : le cœur historique de Barcelone se découvre au hasard. On tombe sur des vestiges romains, des boutiques centenaires et des musiciens sous les arcades.', 'Cherchez la Plaça Sant Felip Neri, la plus paisible du quartier.', false, 'img/s56.jpg', 'C messier · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palau_Reial_Major_2574.jpg'),
  ('s57', 'barcelone', 'Mercat de Santa Caterina', 'Restaurant', 'p1', 'Sant Pere', 'Av. de Francesc Cambó 16, 08003 Barcelona', 'Reconnaissable à son toit ondulé en céramique multicolore, ce marché est moins touristique que la Boqueria. Les habitants du quartier y font leurs courses et les petits bars servent des menus du midi copieux à prix doux.', 'Le bar Joan, à l''intérieur, sert un menu du midi bon marché.', false, 'img/s57.jpg', 'Albert Prat · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Façana_Santa_Caterina.jpg'),
  ('bcn12', 'barcelone', 'Casa Milà (La Pedrera)', 'Culture', 'p2', 'Eixample', 'Passeig de Gràcia 92, 08008 Barcelona', 'Sa façade de pierre ondule comme une falaise et ses balcons en fer forgé ressemblent à des algues. Le clou de la visite : le toit-terrasse, où les cheminées en forme de guerriers casqués veillent sur Barcelone.', 'La visite de nuit avec projections sur le toit est magique.', false, 'img/bcn12.jpg', 'Diliff · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Casa_Milà_-_Barcelona,_Spain_-_Jan_2007.jpg'),
  ('bcn13', 'barcelone', 'Cathédrale de Barcelone', 'Culture', 'p1', 'Barri Gòtic', 'Pla de la Seu, 08002 Barcelona', 'Façade gothique élancée, chapelles dorées et cloître secret où vivent treize oies blanches : la cathédrale est le cœur du quartier gothique. Montez sur le toit en ascenseur pour marcher parmi les pinacles.', 'Le dimanche midi, les Barcelonais dansent la sardane sur le parvis.', false, 'img/bcn13.jpg', 'Enric · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:047_Catedral_i_torre_romana_de_Ca_l''Ardiaca,_av._Catedral_(Barcelona).jpg'),
  ('bcn14', 'barcelone', 'Basilique Santa Maria del Mar', 'Culture', 'free', 'El Born', 'Plaça de Santa Maria 1, 08003 Barcelona', 'Construite par les marins et les dockers du quartier au XIVe siècle, cette église est un chef-d''œuvre de gothique catalan : une nef immense, élancée et dépouillée, baignée par la lumière de sa rosace. Le décor de La Cathédrale de la mer.', 'L''entrée est libre en dehors des créneaux de visite guidée.', false, 'img/bcn14.jpg', 'Josep Renalias · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Santa_Maria_del_Mar_-_Nau_interior.JPG'),
  ('bcn15', 'barcelone', 'Fundació Joan Miró', 'Culture', 'p2', 'Montjuïc', 'Parc de Montjuïc, 08038 Barcelona', 'Dans un bâtiment blanc lumineux sur la colline de Montjuïc, la fondation rassemble les couleurs vives et les formes joyeuses de Miró : peintures, sculptures et tapisseries géantes. Les terrasses ponctuées de sculptures regardent la ville.', 'Combinez avec une balade dans les jardins de Montjuïc.', false, 'img/bcn15.jpg', 'Canaan · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fundació_Miró.JPG'),
  ('bcn16', 'barcelone', 'Parc de la Ciutadella', 'Activité', 'free', 'El Born', 'Passeig de Picasso 21, 08003 Barcelona', 'Le grand parc du centre-ville cache un lac où l''on loue des barques, une cascade monumentale dorée sur laquelle a travaillé Gaudí jeune et des pelouses où jongleurs et musiciens se retrouvent le week-end.', 'Louez une barque sur le lac en fin d''après-midi.', false, 'img/bcn16.jpg', 'SACE (Servicios Aéreos Comerciales Españoles); Rodríguez ... · CC BY 1.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vista_aèria_Ciutadella_1960.jpg'),
  ('bcn17', 'barcelone', 'Arc de Triomf', 'Activité', 'free', 'Sant Pere', 'Passeig de Lluís Companys, 08003 Barcelona', 'Cet arc de brique rouge néo-mudéjar a servi d''entrée à l''Exposition universelle de 1888. Il ouvre une large promenade bordée de palmiers et de lampadaires qui mène jusqu''au parc de la Ciutadella.', 'Le matin, la lumière sur la brique est superbe.', false, 'img/bcn17.jpg', 'Bajajvikram · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Arc_de_Triomf_Barcelona.jpg'),
  ('bcn18', 'barcelone', 'Recinte Modernista de Sant Pau', 'Culture', 'p2', 'Sant Pau', 'Carrer de Sant Antoni Maria Claret 167, 08025 Barcelona', 'Cet ancien hôpital imaginé comme une cité-jardin est le plus grand ensemble moderniste du monde : pavillons aux toits de céramique colorée, coupoles et mosaïques reliés par des tunnels. Bien moins fréquenté que les sites de Gaudí.', 'Remontez à pied l''avenue Gaudí depuis la Sagrada Família.', false, 'img/bcn18.jpg', 'C messier · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Νοσοκομείο_Σαντ_Πάου_3421.jpg'),
  ('bcn19', 'barcelone', 'Tibidabo', 'Activité', 'p2', 'Sarrià-Sant Gervasi', 'Plaça del Tibidabo 3-4, 08035 Barcelona', 'Au sommet de la plus haute colline de Barcelone, ce parc d''attractions centenaire mêle manèges vintage et grande roue avec vue sur la ville et la mer. La basilique du Sacré-Cœur veille juste à côté.', 'Montez avec le funiculaire du Tibidabo ; vérifiez les jours d''ouverture.', false, 'img/bcn19.jpg', 'Enric · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:032_Parc_d''atraccions_Tibidabo_(Barcelona),_des_de_la_terrassa_del_Sagrat_Cor.jpg'),
  ('bcn20', 'barcelone', 'Els Quatre Gats', 'Restaurant', 'p2', 'Barri Gòtic', 'Carrer de Montsió 3, 08002 Barcelona', 'Inspiré du Chat Noir parisien, ce café moderniste de 1897 était le repaire des artistes catalans ; le jeune Picasso y exposa pour la première fois et en dessina le menu. On y dîne de cuisine catalane dans un décor d''époque.', 'Le café de l''entrée permet de profiter du décor sans dîner.', false, 'img/bcn20.jpg', 'Ralf Roletschek · GFDL 1.2 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:15-10-27-Els_Quatre_Gats-RalfR-WMA_2729.jpg'),
  ('bcn21', 'barcelone', 'Can Culleretes', 'Restaurant', 'p2', 'Barri Gòtic', 'Carrer d''en Quintana 5, 08002 Barcelona', 'Ouvert en 1786, c''est le plus ancien restaurant de Barcelone. Ses salles couvertes de photos dédicacées servent une cuisine catalane traditionnelle : canard aux pruneaux, cannellonis et crème catalane.', 'Le menu du midi en semaine est très avantageux.', false, 'img/bcn21.jpg', 'Enfo · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:88_Can_Culleretes,_interior,_mural_de_Francesc_Tey.JPG'),
  ('bcn22', 'barcelone', 'Mercat de Sant Antoni', 'Restaurant', 'p1', 'Sant Antoni', 'Carrer del Comte d''Urgell 1, 08011 Barcelona', 'Ce grand marché en croix de fer forgé, magnifiquement restauré, est le garde-manger des Barcelonais. Autour, le quartier de Sant Antoni est le plus branché du moment pour l''apéro et le vermouth.', 'Le dimanche matin, marché aux livres et aux vieilles BD autour des halles.', false, 'img/bcn22.jpg', 'Pere López · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mercat_de_Sant_Antoni_-_tancant.jpg'),
  ('bcn23', 'barcelone', 'El Born Centre Cultural', 'Culture', 'free', 'El Born', 'Plaça Comercial 12, 08003 Barcelona', 'Sous la structure en fer d''un ancien marché, les fouilles ont mis au jour les rues et maisons de 1714, quand la ville fut assiégée. On domine ce quartier fantôme depuis des passerelles : un voyage étonnant dans le temps.', 'L''accès au site archéologique est gratuit.', false, 'img/bcn23.jpg', 'Kippelboy · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:El_BornCC_setembre_2013_(2).JPG'),
  ('bcn24', 'barcelone', 'Bar Marsella', 'Bar & nuit', 'p1', 'El Raval', 'Carrer de Sant Pau 65, 08001 Barcelona', 'Ouvert en 1820, ce bar poussiéreux aux miroirs fatigués et lustres d''un autre temps est le temple de l''absinthe. On la sert avec un morceau de sucre et une fourchette, comme au temps d''Hemingway et Dalí.', 'Ouvert le soir seulement ; ne demandez pas la carte, l''absinthe suffit.', false, 'img/bcn24.jpg', 'Enric · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:004_Bar_Marsella,_c._Sant_Pau_65_(Barcelona),_interior.jpg'),
  ('bcn25', 'barcelone', 'Boadas', 'Bar & nuit', 'p2', 'La Rambla', 'Carrer dels Tallers 1, 08001 Barcelona', 'Le plus ancien bar à cocktails de Barcelone (1933) tient dans une petite salle triangulaire à deux pas de la Rambla. Barmen en veste blanche, daïquiris et mojitos parfaitement dosés : une institution.', 'Arrivez tôt : il n''y a que quelques places assises.', false, 'img/bcn25.jpg', 'Enfo · CC BY-SA 3.0 es · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:36_Boadas_Cocktail_Bar,_placa.jpg'),
  ('bcn26', 'barcelone', 'Razzmatazz', 'Bar & nuit', 'p2', 'Poblenou', 'Carrer dels Almogàvers 122, 08018 Barcelona', 'Cinq salles, cinq ambiances : indie, électro, pop, techno. Ce club géant installé dans une ancienne usine est le plus célèbre de Barcelone et accueille aussi des concerts de groupes internationaux.', 'Achetez votre entrée en ligne, c''est moins cher qu''à la porte.', false, 'img/bcn26.jpg', 'Zarateman · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Barcelona_-_Sala_Razzmatazz.jpg'),
  ('bcn27', 'barcelone', 'La Rambla', 'Activité', 'free', 'Ciutat Vella', 'La Rambla, 08002 Barcelona', 'Cette promenade bordée de platanes descend de la place de Catalogne jusqu''au port, entre kiosques à fleurs, mosaïque de Miró, Liceu et marché de la Boqueria. Un passage obligé, à parcourir en regardant les façades.', 'Gardez votre sac devant vous : les pickpockets y sont actifs.', false, 'img/bcn27.jpg', 'Ralf Roletschek · GFDL 1.2 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:15-10-27-Vista_des_de_l''estàtua_de_Colom_a_Barcelona-WMA_2791.jpg'),
  ('bcn28', 'barcelone', 'Plaça Reial', 'Activité', 'free', 'Barri Gòtic', 'Plaça Reial, 08002 Barcelona', 'Palmiers, arcades et lampadaires dessinés par le jeune Gaudí : cette place à l''élégance coloniale est bordée de terrasses et de clubs. On y boit un verre en soirée avant de filer danser.', 'Le club Jamboree, sous les arcades, propose du jazz en début de soirée.', false, 'img/bcn28.jpg', 'Paux127 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Plaça_Reial,_Barcelona.jpg'),
  ('bcn29', 'barcelone', 'Casa Vicens', 'Culture', 'p2', 'Gràcia', 'Carrer de les Carolines 20, 08012 Barcelona', 'La toute première maison de Gaudí, couverte de carreaux verts et blancs décorés d''œillets d''Inde, mélange influences mauresques et japonaises. Une visite plus intime que les grands sites, dans le charmant quartier de Gràcia.', 'Prolongez par un verre sur la Plaça del Sol à Gràcia.', false, 'img/bcn29.jpg', 'Pol Viladoms · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Casa_Vicens_2017_int_002.jpg'),
  ('bcn30', 'barcelone', 'Palau Güell', 'Culture', 'p2', 'El Raval', 'Carrer Nou de la Rambla 3-5, 08001 Barcelona', 'Ce palais conçu par Gaudí pour son mécène cache derrière une façade sobre un intérieur somptueux : salle centrale sous coupole percée d''étoiles, boiseries et toit couvert de cheminées en mosaïque.', 'L''audioguide est inclus et très bien fait.', false, 'img/bcn30.jpg', '( Tomàs ) · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palau_Güell_(Barcelona)_-_3.jpg'),
  ('s05', 'lisbonne', 'Pastéis de Belém', 'Restaurant', 'p1', 'Belém', 'Rua de Belém 84-92, 1300-085 Lisboa', 'Depuis 1837, cette pâtisserie fabrique ses pastéis de nata selon une recette secrète gardée par trois maîtres pâtissiers. Pâte feuilletée craquante, crème encore tiède, cannelle et sucre glace à volonté : on les mange sur place dans un dédale de salles couvertes d''azulejos bleus.', 'Prenez place à l''intérieur : la file pour emporter est souvent plus longue.', true, 'img/s05.jpg', 'fw42 from Germany · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pastel_de_nata_(18616473070).jpg'),
  ('s06', 'lisbonne', 'Miradouro da Senhora do Monte', 'Activité', 'free', 'Graça', 'Largo Monte, 1170-253 Lisboa', 'Le belvédère le plus haut de Lisbonne offre un panorama à couper le souffle sur le château, le Tage et l''océan de toits orange. Au coucher du soleil, les habitants s''y retrouvent sous les pins avec une bière ou une guitare.', 'Montez avec le tram 28 jusqu''à Graça puis finissez à pied.', false, 'img/s06.jpg', 'Filipe Rocha,user:sacavem (pt) http://pt.wikipedia.org/wi... · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Miradouro_Nossa_Senhora_do_Monte_II.jpg'),
  ('s07', 'lisbonne', 'Time Out Market', 'Restaurant', 'p2', 'Cais do Sodré', 'Av. 24 de Julho 49, 1200-479 Lisboa', 'Dans l''ancien marché de la Ribeira, une trentaine de stands tenus par des chefs et institutions lisboètes servent bifanas, poulpe grillé, croquetas et pastéis de nata. On compose son repas et on s''installe sur les grandes tables communes.', 'En semaine à midi, on trouve facilement une place.', false, 'img/s07.jpg', 'Osvaldo Gago / Osvaldo Gago · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mercado_Ribeira_Lisbon.JPG'),
  ('s08', 'lisbonne', 'LX Factory', 'Culture', 'free', 'Alcântara', 'Rua Rodrigues de Faria 103, 1300-501 Lisboa', 'Sous le pont du 25-Avril, cette ancienne usine textile est devenue un quartier créatif : librairie installée dans une imprimerie, ateliers de designers, street art géant, cafés et rooftops. Une ambiance arty idéale pour une fin d''après-midi.', 'Le marché du dimanche réunit créateurs et brocanteurs.', false, 'img/s08.jpg', 'Andrzej Otrębski · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisboa_LX_Factory_1.jpg'),
  ('s36', 'lisbonne', 'Tour de Belém', 'Culture', 'p1', 'Belém', 'Av. Brasília, 1400-038 Lisboa', 'Posée au bord du Tage depuis 1520, cette tour manuéline ciselée comme une pièce d''orfèvrerie gardait l''entrée de Lisbonne à l''époque des grandes découvertes. Ses balcons sculptés, ses créneaux en forme de croix et son rhinocéros de pierre sont classés à l''UNESCO.', 'Le billet combiné avec le monastère des Hiéronymites revient moins cher.', false, 'img/s36.jpg', 'Lisbon Photoshoots · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Belém_Tower_in_Lisbon,_Portugal.jpg'),
  ('s37', 'lisbonne', 'Monastère des Hiéronymites', 'Culture', 'p2', 'Belém', 'Praça do Império, 1400-206 Lisboa', 'Financé par l''or des épices, ce monastère est le chef-d''œuvre du style manuélin : colonnes torsadées, cordages et motifs marins sculptés dans la pierre blonde. Son cloître à deux étages est l''un des plus beaux d''Europe, et Vasco de Gama repose dans l''église.', 'L''église est gratuite, seul le cloître est payant.', false, 'img/s37.jpg', 'Holger Uwe Schmitt · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1502_legte_König_Manuel_I._den_Grundstein_für_das_Hieronymus_Kloster_in_Lissabon._06.jpg'),
  ('s38', 'lisbonne', 'Castelo de São Jorge', 'Culture', 'p2', 'Alfama', 'Rua de Santa Cruz do Castelo, 1100-129 Lisboa', 'Du haut de ses remparts maures, le château domine l''Alfama et offre la vue la plus complète sur Lisbonne et le Tage. On se balade sur les chemins de ronde entre les pins, les oliviers et les paons qui se promènent en liberté.', 'Restez jusqu''au coucher du soleil depuis les remparts.', false, 'img/s38.jpg', 'CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Castelo_Sao_Jorge_Lisboa_1.JPG'),
  ('s39', 'lisbonne', 'Elevador de Santa Justa', 'Activité', 'p1', 'Baixa', 'Rua do Ouro, 1150-060 Lisboa', 'Cet ascenseur néogothique en fer forgé de 1902 relie la Baixa au Chiado dans une cabine en bois d''époque. Sa plateforme sommitale offre une vue spectaculaire sur la ville basse, le château et les ruines du couvent du Carmo.', 'La plateforme est accessible gratuitement à pied depuis le Largo do Carmo.', false, 'img/s39.jpg', 'Luca Galuzzi (Lucag) · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisbon_(Lisboa)_historic_elevator_Santa_Justa_Luca_Galuzzi_2006.jpg'),
  ('s40', 'lisbonne', 'Oceanário de Lisboa', 'Activité', 'p2', 'Parque das Nações', 'Esplanada Dom Carlos I, 1990-005 Lisboa', 'L''un des plus beaux aquariums d''Europe s''organise autour d''un bassin central géant où nagent requins, raies et un poisson-lune spectaculaire. Loutres de mer, manchots et méduses complètent une visite apaisante, idéale par temps de pluie.', 'Comptez deux heures et réservez en ligne le week-end.', false, 'img/s40.jpg', 'Shadowgate from Novara, ITALY · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisbon_Oceanarium_(34535938846).jpg'),
  ('s43', 'lisbonne', 'Soirée au Bairro Alto', 'Bar & nuit', 'p1', 'Bairro Alto', 'Rua do Diário de Notícias, 1200-141 Lisboa', 'La nuit venue, ce quartier de ruelles pentues se transforme en immense bar à ciel ouvert : on commande une caipirinha ou une bière à quelques euros au comptoir et on la boit dans la rue, au milieu d''une foule joyeuse jusqu''à tard.', 'L''ambiance démarre vers 23h ; finissez au miradouro de São Pedro de Alcântara.', false, 'img/s43.jpg', 'CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bairro_Alto_Lisboa_1.JPG'),
  ('s44', 'lisbonne', 'Praça do Comércio', 'Activité', 'free', 'Baixa', 'Praça do Comércio, 1100-148 Lisboa', 'Cette immense place encadrée d''arcades jaunes s''ouvre directement sur le Tage, là où arrivaient autrefois les navires des Indes. Passez sous l''arc triomphal de la Rua Augusta, puis descendez les marches du Cais das Colunas jusqu''à l''eau.', 'Montez au sommet de l''Arco da Rua Augusta pour une vue plongeante.', false, 'img/s44.jpg', 'Deensel · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aerial_view_of_Praça_do_Comércio_and_Baixa_Pombalina_(cropped_and_retouched).jpg'),
  ('s45', 'lisbonne', 'Musée Calouste Gulbenkian', 'Culture', 'p1', 'Avenidas Novas', 'Av. de Berna 45A, 1067-001 Lisboa', 'La collection d''un magnat du pétrole passionné d''art : antiquités égyptiennes, tapis persans, Rembrandt, Monet et bijoux Art nouveau de Lalique. Le musée est entouré d''un jardin moderniste avec étangs et canards, parfait pour souffler.', 'Le jardin est en accès libre, et l''entrée est gratuite le dimanche après-midi.', false, 'img/s45.jpg', 'Kent Wang · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Calouste_Gulbenkian_Museum_Exterior_37.jpg'),
  ('s46', 'lisbonne', 'MAAT', 'Culture', 'p1', 'Belém', 'Av. Brasília, 1300-598 Lisboa', 'Ce musée à la silhouette ondulée recouverte de carreaux de céramique blanche semble sortir du Tage. Expositions d''art contemporain et de design dans une ancienne centrale électrique voisine, et un toit-promenade gratuit avec vue sur le pont du 25-Avril.', 'Le toit est accessible à pied gratuitement, même sans billet.', false, 'img/s46.jpg', 'Kent Wang · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Exterior_of_Museu_de_Arte,_Arquitetura_e_Tecnologia_67.jpg'),
  ('lis14', 'lisbonne', 'Alfama', 'Activité', 'free', 'Alfama', 'Largo do Chafariz de Dentro, 1100-139 Lisboa', 'Le plus vieux quartier de Lisbonne est un labyrinthe d''escaliers, de ruelles et de petites places où sèche le linge aux fenêtres. Le soir, des voix de fado s''échappent des tavernes : c''est ici que bat le cœur populaire de la ville.', 'Perdez-vous sans plan, puis cherchez une casa de fado pour le dîner.', false, 'img/lis14.jpg', 'dirk.olbertz · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Alfama,_Lisboa_-_2010-09-09.jpg'),
  ('lis15', 'lisbonne', 'Miradouro de Santa Luzia', 'Activité', 'free', 'Alfama', 'Largo de Santa Luzia, 1100-487 Lisboa', 'Une terrasse fleurie de bougainvilliers, des panneaux d''azulejos et une vue plongeante sur les toits de l''Alfama jusqu''au Tage : ce belvédère est l''un des plus romantiques de Lisbonne, sur le passage du tram 28.', 'Venez tôt le matin pour la lumière douce et le calme.', false, 'img/lis15.jpg', 'Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MiradouroSantaLuzia.JPG'),
  ('lis16', 'lisbonne', 'Miradouro de São Pedro de Alcântara', 'Activité', 'free', 'Bairro Alto', 'Rua de São Pedro de Alcântara, 1250-237 Lisboa', 'Ce jardin en terrasse fait face au château de São Jorge, de l''autre côté de la Baixa. Kiosque à boissons, musiciens de rue et bancs à l''ombre : le point de départ idéal d''une soirée au Bairro Alto.', 'Montez-y avec l''Elevador da Glória depuis la place des Restauradores.', false, 'img/lis16.jpg', 'CorreiaPM · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:JardimSPedroAlcantara.JPG'),
  ('lis17', 'lisbonne', 'Padrão dos Descobrimentos', 'Culture', 'p1', 'Belém', 'Av. Brasília, 1400-038 Lisboa', 'Haut de 52 mètres, ce monument en forme de proue de caravelle rend hommage aux navigateurs portugais, Henri le Navigateur en tête. Au pied, une immense rose des vents en marbre ; au sommet, une vue superbe sur Belém et le Tage.', 'Le belvédère au sommet est accessible en ascenseur.', false, 'img/lis17.jpg', 'Diego Delso · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Monumento_a_los_Descubrimientos,_Lisboa,_Portugal,_2012-05-12,_DD_19.JPG'),
  ('lis18', 'lisbonne', 'Museu Nacional do Azulejo', 'Culture', 'p1', 'Xabregas', 'Rua da Madre de Deus 4, 1900-312 Lisboa', 'Installé dans un couvent du XVIe siècle à l''église entièrement dorée, ce musée raconte cinq siècles de céramique portugaise. Ne manquez pas le grand panorama en azulejos de Lisbonne avant le tremblement de terre de 1755, long de 23 mètres.', 'Le café du cloître, décoré de carreaux anciens, est délicieux.', false, 'img/lis18.jpg', 'Biblioteca de Arte / Art Library Fundação Calouste Gulben... · No restrictions · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Igreja_do_Convento_da_Madre_de_Deus,_Lisboa_(Portugal).jpg'),
  ('lis19', 'lisbonne', 'Café A Brasileira', 'Restaurant', 'p1', 'Chiado', 'Rua Garrett 120, 1200-205 Lisboa', 'Ce café Art nouveau de 1905 aux boiseries sombres et miroirs dorés était le repaire du poète Fernando Pessoa, dont la statue de bronze attend en terrasse. On y commande une bica, l''expresso lisboète, au comptoir comme les habitués.', 'Le café est bien moins cher au comptoir qu''en terrasse.', false, 'img/lis19.jpg', 'VDT2021 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A_BRASILEIRA_DO_CHIADO.jpg'),
  ('lis20', 'lisbonne', 'Confeitaria Nacional', 'Restaurant', 'p1', 'Baixa', 'Praça da Figueira 18B, 1100-241 Lisboa', 'Fondée en 1829, la plus ancienne pâtisserie de Lisbonne a gardé ses vitrines en bois et ses comptoirs de marbre. On y goûte le bolo rei, les pastéis de nata ou les queijadas dans un décor qui n''a presque pas changé.', 'Le salon de thé à l''étage est plus calme que le comptoir.', false, 'img/lis20.jpg', 'Lee Cannon from Bayville aka West Fenwick, DE, USA · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisbon,_Confeitaria_Nacional,_April_2010.jpg'),
  ('lis21', 'lisbonne', 'Cervejaria Trindade', 'Restaurant', 'p2', 'Chiado', 'Rua Nova da Trindade 20C, 1200-303 Lisboa', 'Installée dans le réfectoire d''un ancien couvent, cette brasserie de 1836 est couverte d''azulejos représentant les saisons et les éléments. On y vient pour les crevettes à l''ail, le bifteck à la portugaise et la bière pression maison.', 'Le bifteck « à Trindade » est la spécialité de la maison.', false, 'img/lis21.jpg', 'ricardo from London · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Steak_and_Beer,_Cervejaria_Trindade,_Lisbon_(3456932552).jpg'),
  ('lis22', 'lisbonne', 'Casa do Alentejo', 'Restaurant', 'p2', 'Restauradores', 'Rua das Portas de Santo Antão 58, 1150-268 Lisboa', 'Derrière une porte discrète se cache un palais néo-mauresque avec patio arabe, salles d''azulejos et lustres. On y sert la cuisine généreuse de l''Alentejo : porc aux palourdes, migas et vins de la région.', 'Même sans manger, montez voir le patio et la salle de bal.', false, 'img/lis22.jpg', 'Sergio Calleja (Life is a trip) from Barcelona, Spain · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Casa_do_Alentejo.jpg'),
  ('lis23', 'lisbonne', 'Sé de Lisboa', 'Culture', 'free', 'Alfama', 'Largo da Sé, 1100-585 Lisboa', 'La plus vieille église de Lisbonne, bâtie en 1147, ressemble à une forteresse avec ses deux tours crénelées. Sa nef romane austère et sa grande rosace contrastent avec le tram jaune qui passe juste devant, une des photos les plus célèbres de la ville.', 'L''entrée de la nef est gratuite ; le cloître et le trésor sont payants.', false, 'img/lis23.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:West_facade_of_Lisbon_Cathedral_(retouched).jpg'),
  ('lis24', 'lisbonne', 'Panteão Nacional', 'Culture', 'p1', 'Alfama', 'Campo de Santa Clara, 1100-471 Lisboa', 'Son immense dôme blanc a mis près de trois siècles à être achevé. À l''intérieur, marbres colorés et tombeaux de grandes figures portugaises, dont la chanteuse de fado Amália Rodrigues ; sur la terrasse, vue panoramique sur le Tage.', 'Combinez la visite avec la Feira da Ladra, juste à côté.', false, 'img/lis24.jpg', 'Kent Wang · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Exterior_of_Igreja_de_Santa_Engrácia_70.jpg'),
  ('lis25', 'lisbonne', 'Feira da Ladra', 'Activité', 'free', 'Alfama', 'Campo de Santa Clara, 1170 Lisboa', 'Le « marché de la voleuse » est la grande brocante de Lisbonne depuis le Moyen Âge : azulejos anciens, vinyles, vieux appareils photo et babioles s''étalent sur des draps. Une plongée amusante dans la vie de quartier.', 'Le mardi et le samedi matin ; venez tôt pour les meilleures trouvailles.', false, 'img/lis25.jpg', 'Carlos Luis M C da Cruz · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Feira_da_ladra.jpg'),
  ('lis26', 'lisbonne', 'Jardim da Estrela', 'Activité', 'free', 'Estrela', 'Praça da Estrela, 1200-667 Lisboa', 'Ce jardin romantique du XIXe siècle, avec son kiosque à musique en fer forgé, ses canards et ses arbres exotiques, fait face à la basilique d''Estrela. Les familles lisboètes s''y retrouvent le week-end autour du petit café.', 'Montez sur le toit de la basilique voisine pour une vue étonnante.', false, 'img/lis26.jpg', 'Vitor Oliveira from Torres Vedras, PORTUGAL · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jardim_da_Estrela_-_Lisboa_-_Portugal_(15227514472).jpg'),
  ('lis27', 'lisbonne', 'Cristo Rei', 'Activité', 'p1', 'Almada', 'Av. Cristo Rei, 2800-058 Almada', 'De l''autre côté du Tage, cette statue du Christ aux bras ouverts domine Lisbonne du haut de ses 110 mètres. Son belvédère offre la vue la plus spectaculaire sur le pont du 25-Avril et toute la ville.', 'Prenez le ferry jusqu''à Cacilhas, puis le bus 101.', false, 'img/lis27.jpg', 'Deensel · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cristo_Rei_(36211699613)_(cropped).jpg'),
  ('lis28', 'lisbonne', 'Cais do Sodré', 'Bar & nuit', 'p1', 'Cais do Sodré', 'Rua Nova do Carvalho, 1200-292 Lisboa', 'L''ancien quartier des marins est devenu le cœur de la nuit lisboète, avec la fameuse « rue rose » peinte en fuchsia. Bars à cocktails, anciens cabarets et clubs se succèdent jusqu''au petit matin, dans une ambiance très mélangée.', 'Commencez par un verre au bord du Tage, au Cais do Sodré.', false, 'img/lis28.jpg', 'Jules Verne Times Two · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Old_Arsenal_da_Marinha_and_Doca_da_Caldeirinha,_Cais_do_Sodré,_Lisbon,_Portugal_julesvernex2.jpg'),
  ('lis30', 'lisbonne', 'Museu Nacional de Arte Antiga', 'Culture', 'p1', 'Lapa', 'Rua das Janelas Verdes, 1249-017 Lisboa', 'Le plus grand musée d''art du Portugal abrite les Panneaux de Saint-Vincent, les paravents japonais namban et La Tentation de saint Antoine de Jérôme Bosch. Son jardin-café domine le Tage : un secret bien gardé des Lisboètes.', 'Le jardin est accessible depuis le café, même en fin de visite.', false, 'img/lis30.jpg', 'Fulviusbsas · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MNAA.jpg'),
  ('lis31', 'lisbonne', 'Ascensor da Bica', 'Activité', 'p1', 'Bica', 'Rua de São Paulo 234, 1200-109 Lisboa', 'Ce petit funiculaire jaune de 1892 grimpe une ruelle pentue bordée de maisons colorées, avec le Tage en arrière-plan. C''est l''une des images les plus emblématiques de Lisbonne.', 'La montée à pied permet de prendre les meilleures photos.', false, 'img/lis31.jpg', 'Jorge Franganillo · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisboa_-_Elevador_da_Bica_(53861208616).jpg'),
  ('s14', 'rome', 'Panthéon', 'Culture', 'p1', 'Centro Storico', 'Piazza della Rotonda, 00186 Roma', 'Vieux de près de 2 000 ans, le Panthéon est le monument antique le mieux conservé de Rome. Sous sa coupole de béton, la plus grande non armée du monde, un oculus de 9 mètres laisse entrer un rayon de soleil qui tourne avec les heures, et la pluie quand il pleut. Raphaël y repose.', 'Entrée payante depuis 2023, à petit prix ; venez à l''ouverture pour le calme.', false, 'img/s14.jpg', 'NikonZ7II · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pantheon_(Rome)_-_Right_side_and_front.jpg'),
  ('s15', 'rome', 'Balade dans Trastevere', 'Activité', 'free', 'Trastevere', 'Piazza di Santa Maria in Trastevere, 00153 Roma', 'De l''autre côté du Tibre, Trastevere est la Rome des cartes postales : ruelles pavées couvertes de lierre, linge aux fenêtres, trattorias aux nappes à carreaux et places où l''on s''attarde le soir. La basilique Santa Maria in Trastevere brille de mosaïques dorées.', 'Montez ensuite au Gianicolo pour la vue au coucher du soleil.', false, 'img/s15.jpg', 'Krzysztof Golik · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Santa_Maria_in_Trastevere_church_in_Rome_(12).jpg'),
  ('s58', 'rome', 'Colisée', 'Culture', 'p2', 'Monti', 'Piazza del Colosseo, 00184 Roma', 'Le plus grand amphithéâtre jamais construit pouvait accueillir 50 000 spectateurs venus voir combats de gladiateurs et chasses aux fauves. Arpenter ses gradins, imaginer la foule et les coulisses souterraines reste un moment saisissant, deux mille ans plus tard.', 'Le billet inclut le Forum romain et le Palatin : gardez une journée.', false, 'img/s58.jpg', 'FeaturedPics · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Colosseo_2020.jpg'),
  ('s59', 'rome', 'Fontaine de Trevi', 'Activité', 'free', 'Trevi', 'Piazza di Trevi, 00187 Roma', 'Surgissant d''une petite place, ce décor baroque de Neptune, chevaux marins et cascades est plus grandiose qu''on ne l''imagine. La tradition veut qu''on jette une pièce par-dessus l''épaule pour être sûr de revenir à Rome, comme dans La Dolce Vita.', 'Venez avant 8h pour la voir sans la foule.', false, 'img/s59.jpg', 'NikonZ7II · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Trevi_Fountain_-_Roma.jpg'),
  ('s60', 'rome', 'Musées du Vatican', 'Culture', 'p2', 'Vatican', 'Viale Vaticano, 00165 Roma', 'Sculptures antiques, salles de Raphaël, galerie des cartes géographiques… et, au bout du parcours, la chapelle Sixtine et le Jugement dernier de Michel-Ange. Une des plus riches collections du monde, avec un escalier en spirale devenu iconique.', 'Gratuits le dernier dimanche du mois, mais la file est énorme ; réservez sinon.', false, 'img/s60.jpg', 'Colin · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vatican_Museums_Spiral_Staircase_Looking_Up_2012.jpg'),
  ('s61', 'rome', 'Basilique Saint-Pierre', 'Culture', 'free', 'Vatican', 'Piazza San Pietro, 00120 Città del Vaticano', 'La plus grande église du monde impressionne par ses proportions : la Pietà de Michel-Ange, le baldaquin de bronze du Bernin, et une coupole que l''on peut gravir pour une vue vertigineuse sur la place et Rome.', 'Épaules et genoux couverts obligatoires ; la montée à la coupole est payante.', false, 'img/s61.jpg', 'Alvesgaspar · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Basilica_di_San_Pietro_in_Vaticano_September_2015-1a.jpg'),
  ('s62', 'rome', 'Galleria Borghese', 'Culture', 'p2', 'Villa Borghese', 'Piazzale Scipione Borghese 5, 00197 Roma', 'Dans une villa du XVIIe siècle au milieu d''un parc, des sculptures du Bernin d''une virtuosité folle (Apollon et Daphné, l''Enlèvement de Proserpine) côtoient six toiles du Caravage. Un écrin intime, à taille humaine.', 'Visite par créneaux de deux heures, réservation obligatoire.', false, 'img/s62.jpg', 'Alessio Damato · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Galleria_borghese_facade.jpg'),
  ('s66', 'rome', 'Marché du Campo de'' Fiori', 'Activité', 'free', 'Campo de'' Fiori', 'Piazza Campo de'' Fiori, 00186 Roma', 'Le matin, la place se couvre d''étals de fruits, de légumes, de fleurs et d''épices sous la statue sombre de Giordano Bruno. Le soir, elle devient l''un des rendez-vous les plus animés de Rome pour l''aperitivo.', 'Le marché ferme vers 14h et n''a pas lieu le dimanche.', false, 'img/s66.jpg', 'Myrabella · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Campo_dei_Fiori.jpg'),
  ('s68', 'rome', 'Piazza Navona', 'Activité', 'free', 'Centro Storico', 'Piazza Navona, 00186 Roma', 'Bâtie sur un ancien stade romain dont elle garde la forme allongée, la place la plus élégante de Rome aligne trois fontaines, dont celle des Quatre-Fleuves du Bernin, face à l''église de Borromini. Peintres et musiciens l''animent jour et nuit.', 'Évitez les terrasses de la place, très chères ; allez une rue plus loin.', false, 'img/s68.jpg', 'This Photo was taken by Wolfgang Moroder. Feel free to us... · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Piazza_Navona_Gange_fontana_dei_Fiumi_Roma.jpg'),
  ('rom10', 'rome', 'Antico Caffè Greco', 'Restaurant', 'p2', 'Piazza di Spagna', 'Via dei Condotti 86, 00187 Roma', 'Ouvert en 1760, le plus vieux café de Rome est un musée vivant : salons tendus de velours rouge, plus de 300 tableaux et des serveurs en queue-de-pie. Goethe, Keats, Byron et Casanova y ont pris leur café, que l''on boit encore debout au comptoir.', 'Un expresso au comptoir coûte peu ; en salle, l''addition grimpe.', true, 'img/rom10.jpg', 'LluisdeZamora · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Caffè_Greco._Roma.jpg'),
  ('rom11', 'rome', 'Caffè Sant''Eustachio', 'Restaurant', 'p1', 'Centro Storico', 'Piazza di Sant''Eustachio 82, 00186 Roma', 'Depuis 1938, ce petit café torréfie son grain au feu de bois et prépare son « gran caffè » mousseux selon une recette tenue secrète derrière le comptoir. Beaucoup de Romains le considèrent comme le meilleur expresso de la ville.', 'Il est servi sucré par défaut : dites « amaro » pour sans sucre.', false, 'img/rom11.jpg', 'LPLT · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Caffè_Sant''Eustachio.JPG'),
  ('rom12', 'rome', 'Mercato di Testaccio', 'Restaurant', 'p1', 'Testaccio', 'Via Aldo Manuzio 66b, 00153 Roma', 'Le marché couvert du quartier populaire de Testaccio est le paradis du street-food romain : sandwichs à la queue de bœuf, supplì, pizza al taglio et fromages, à déguster entre les étals de primeurs.', 'Le stand Mordi e Vai est une institution ; fermé le dimanche.', false, 'img/rom12.jpg', 'Lalupa · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Testaccio_-_nuovo_mercato_P1040527.JPG'),
  ('rom13', 'rome', 'Babington''s Tea Room', 'Restaurant', 'p2', 'Piazza di Spagna', 'Piazza di Spagna 23, 00187 Roma', 'Au pied des marches de la Trinité-des-Monts, ce salon de thé anglais ouvert en 1893 par deux Anglaises sert scones, pancakes et thés rares dans un décor de bois sombre et de nappes blanches. Une parenthèse délicieusement britannique au cœur de Rome.', 'Idéal pour une pause en fin d''après-midi.', false, 'img/rom13.jpg', 'Slayer · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Babington''s_tea_rooms.jpg'),
  ('rom16', 'rome', 'Escalier de la Trinité-des-Monts', 'Activité', 'free', 'Piazza di Spagna', 'Piazza di Spagna, 00187 Roma', 'Les 135 marches de l''escalier baroque le plus célèbre du monde montent de la fontaine de la Barcaccia jusqu''à l''église de la Trinité-des-Monts. En haut, la vue file sur la via dei Condotti et les toits de Rome.', 'Il est interdit de s''asseoir sur les marches : on admire en marchant.', false, 'img/rom16.jpg', 'Photo2023 · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Piazza_di_Spagna_2018.jpg'),
  ('rom17', 'rome', 'Forum romain', 'Culture', 'p2', 'Monti', 'Via della Salara Vecchia 5/6, 00186 Roma', 'Le cœur de la Rome antique : temples, arcs de triomphe, colonnes et voie Sacrée où défilaient les généraux victorieux. Du haut du Palatin voisin, on embrasse toute la vallée des ruines, émouvante au coucher du soleil.', 'Le billet du Colisée inclut le Forum et le Palatin.', false, 'img/rom17.jpg', 'This Photo was taken by Wolfgang Moroder. Feel free to us... · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Foro_Romano_Musei_Capitolini_Roma.jpg'),
  ('rom18', 'rome', 'Château Saint-Ange', 'Culture', 'p2', 'Borgo', 'Lungotevere Castello 50, 00193 Roma', 'Mausolée de l''empereur Hadrien devenu forteresse des papes, ce château cylindrique est relié au Vatican par un passage secret. Sa terrasse offre l''une des plus belles vues sur Saint-Pierre et le Tibre, et le pont aux anges qui y mène est superbe.', 'Le café de la terrasse, avec vue sur Saint-Pierre, est une pause idéale.', false, 'img/rom18.jpg', 'Livioandronico2013 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Castel_Sant''Angelo_at_Night.jpg'),
  ('rom19', 'rome', 'Villa Borghese', 'Activité', 'free', 'Pinciano', 'Piazzale Napoleone I, 00197 Roma', 'Le grand parc de Rome mêle allées de pins parasols, petit lac avec temple d''Esculape et terrasse du Pincio dominant la piazza del Popolo. On s''y promène à pied, à vélo ou en rosalie, loin du bruit de la ville.', 'Le coucher du soleil depuis la terrasse du Pincio est inoubliable.', false, 'img/rom19.jpg', 'Oursana · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ingresso_monumentale_di_Villa_Borghese_a_Roma_su_piazzale_Flaminio_2018-02.jpg'),
  ('rom20', 'rome', 'Gianicolo', 'Activité', 'free', 'Trastevere', 'Passeggiata del Gianicolo, 00165 Roma', 'Cette colline au-dessus de Trastevere offre le plus vaste panorama sur les dômes et clochers de Rome. Chaque jour à midi, un coup de canon y est tiré depuis 1847 pour donner l''heure aux cloches de la ville.', 'Montez à pied depuis Trastevere par les escaliers de la via Garibaldi.', false, 'img/rom20.jpg', 'Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Janiculum.jpg'),
  ('rom21', 'rome', 'Sainte-Marie-Majeure', 'Culture', 'free', 'Esquilino', 'Piazza di Santa Maria Maggiore, 00185 Roma', 'L''une des quatre basiliques majeures de Rome cache des mosaïques du Ve siècle d''une fraîcheur étonnante et un plafond doré, dit-on, avec le premier or rapporté des Amériques. Le pape François y repose depuis 2025.', 'Gratuite et souvent moins fréquentée que Saint-Pierre.', false, 'img/rom21.jpg', 'NikonZ7II · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Basilica_di_Santa_Maria_Maggiore_-_Roma.jpg'),
  ('rom22', 'rome', 'Bouche de la Vérité', 'Activité', 'p1', 'Ripa', 'Piazza della Bocca della Verità 18, 00186 Roma', 'Selon la légende, ce masque de marbre antique mord la main des menteurs. Rendu célèbre par Vacances romaines avec Audrey Hepburn, il se trouve sous le porche de l''église Santa Maria in Cosmedin, à deux pas du Tibre.', 'Une petite offrande est demandée pour la photo ; venez tôt.', false, 'img/rom22.jpg', 'Sailko · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Età_imperiale,_chiusino_a_forma_di_mascherone_di_divinità_fluviale,_detta_bocca_della_verità,_collocata_qui_nel_1632.jpg'),
  ('rom23', 'rome', 'Thermes de Caracalla', 'Culture', 'p2', 'Aventino', 'Viale delle Terme di Caracalla, 00153 Roma', 'Ces thermes géants du IIIe siècle accueillaient 1 500 baigneurs à la fois. Les murs de brique hauts de 30 mètres et les mosaïques au sol donnent la mesure du luxe romain ; l''été, des opéras y sont joués en plein air.', 'Bien moins fréquentés que le Colisée ; les soirées d''opéra estivales sont magiques.', false, 'img/rom23.jpg', 'Ethan Doyle White · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baths_of_Caracalla,_facing_Caldarium.jpg'),
  ('rom24', 'rome', 'Via Appia Antica', 'Activité', 'free', 'Appio Latino', 'Via Appia Antica, 00178 Roma', 'La « reine des routes » romaines, pavée de grosses pierres d''origine, file entre pins parasols, tombeaux antiques et catacombes. Le dimanche, elle est fermée aux voitures : parfait pour une balade à vélo hors du temps.', 'Louez un vélo au Centre d''information de la via Appia.', false, 'img/rom24.jpg', 'Livioandronico2013 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Appian_Way.jpg'),
  ('rom25', 'rome', 'Musées du Capitole', 'Culture', 'p2', 'Campidoglio', 'Piazza del Campidoglio 1, 00186 Roma', 'Sur la place dessinée par Michel-Ange, le plus ancien musée public du monde abrite la Louve allaitant Romulus et Rémus et la statue équestre de Marc Aurèle. Sa terrasse domine tout le Forum romain.', 'Ne manquez pas la vue sur le Forum depuis le Tabularium.', false, 'img/rom25.jpg', 'Ricardo André Frantz (User:Tetraktys) · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Capitolio9.jpg'),
  ('rom26', 'rome', 'Jardin des Orangers', 'Activité', 'free', 'Aventino', 'Piazza Pietro d''Illiria, 00153 Roma', 'Sur la colline de l''Aventin, ce petit jardin d''orangers ouvre une terrasse sur le Tibre et le dôme de Saint-Pierre. Juste à côté, le trou de serrure des Chevaliers de Malte cadre parfaitement la coupole : une curiosité romaine.', 'Combinez avec le trou de serrure de la place des Chevaliers de Malte.', false, 'img/rom26.jpg', 'Lasagnolo9 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Giardino_degli_Aranci.JPG'),
  ('rom27', 'rome', 'Galleria Doria Pamphilj', 'Culture', 'p2', 'Centro Storico', 'Via del Corso 305, 00186 Roma', 'Dans un palais toujours habité par la famille princière, des galeries de miroirs dorés accueillent le portrait d''Innocent X par Velázquez, des Caravage et des Titien. On s''y sent invité dans l''intimité d''une grande famille romaine.', 'L''audioguide est commenté par un membre de la famille.', false, 'img/rom27.jpg', 'Sailko · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palazzo_doria_pamphili,_galleria_doria,_01.jpg'),
  ('rom28', 'rome', 'Vittoriano', 'Activité', 'free', 'Piazza Venezia', 'Piazza Venezia, 00186 Roma', 'Ce monument de marbre blanc éclatant, surnommé « la machine à écrire » par les Romains, domine la piazza Venezia. Ses terrasses offrent une vue imprenable sur le Forum et le Colisée ; un ascenseur vitré monte jusqu''au sommet.', 'L''accès aux terrasses basses est gratuit, l''ascenseur panoramique est payant.', false, 'img/rom28.jpg', 'ThePhotografer · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Altare_della_Patria_(Roma).jpg'),
  ('rom29', 'rome', 'San Pietro in Vincoli', 'Culture', 'free', 'Monti', 'Piazza di San Pietro in Vincoli 4/a, 00184 Roma', 'Cette basilique discrète abrite le Moïse de Michel-Ange, sculpture d''une puissance saisissante, et les chaînes qui auraient retenu saint Pierre. Un chef-d''œuvre visible gratuitement, à quelques minutes du Colisée.', 'Prévoyez une pièce pour éclairer le Moïse.', false, 'img/rom29.jpg', 'Rione I Monti · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:San_Pietro_in_Vincoli_-_esterno.jpg'),
  ('rom30', 'rome', 'Marché de Porta Portese', 'Activité', 'free', 'Trastevere', 'Via Portuense, 00153 Roma', 'Chaque dimanche matin, le plus grand marché aux puces de Rome s''étire sur des kilomètres : vêtements vintage, antiquités, vinyles et bric-à-brac. Une immersion très romaine, bruyante et joyeuse.', 'Le dimanche matin seulement ; arrivez avant 10h.', false, 'img/rom30.jpg', 'Borgo Pius · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:DSC08090_Portese_Door.jpg'),
  ('rom31', 'rome', 'Basilique Saint-Clément', 'Culture', 'p1', 'Celio', 'Via Labicana 95, 00184 Roma', 'Trois niveaux d''histoire superposés : une basilique du XIIe siècle, une église du IVe siècle en dessous et, tout en bas, un temple de Mithra et des maisons romaines où coule encore une source.', 'La descente aux niveaux inférieurs est payante mais fascinante.', false, 'img/rom31.jpg', 'Labicanense · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Basilica_di_San_Clemente_al_Laterano_-_esterno.jpg'),
  ('rom32', 'rome', 'Giolitti', 'Restaurant', 'p1', 'Centro Storico', 'Via degli Uffici del Vicario 40, 00186 Roma', 'Glacier historique depuis 1900, Giolitti sert plus de 50 parfums sous ses comptoirs Belle Époque, à deux pas du Panthéon.', 'Payez d''abord à la caisse, puis choisissez au comptoir.', false, 'img/rom32.jpg', 'Jebulon · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ceiling_Giolitti_Ice_Creams,_Rome,_Italy.jpg'),
  ('s17', 'berlin', 'East Side Gallery', 'Culture', 'free', 'Friedrichshain', 'Mühlenstraße 3-100, 10243 Berlin', 'Le plus long tronçon du Mur encore debout (1,3 km) est devenu une galerie à ciel ouvert : plus de 100 artistes l''ont peint en 1990, dont le célèbre baiser Brejnev-Honecker. Une promenade le long de la Spree, entre histoire et street art.', 'Commencez côté Ostbahnhof et finissez sur l''Oberbaumbrücke.', false, 'img/s17.jpg', 'Joachim F. Thurn · CC BY-SA 3.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bundesarchiv_B_145_Bild-F088809-0038,_Berlin,_East_Side_Gallery.jpg'),
  ('s20', 'berlin', 'Berghain', 'Bar & nuit', 'p2', 'Friedrichshain', 'Am Wriezener Bahnhof, 10243 Berlin', 'Dans une ancienne centrale électrique de béton, le club techno le plus mythique du monde ouvre le samedi soir pour des fêtes qui durent jusqu''au lundi matin. Système son légendaire, pas de photos et une sélection à l''entrée devenue célèbre.', 'Habillez-vous sobrement (noir), venez en petit groupe et ne parlez pas fort dans la file.', false, 'img/s20.jpg', 'Lear 21 · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1_Berlin_Berghain_NYE_01.jpg'),
  ('s69', 'berlin', 'Porte de Brandebourg', 'Activité', 'free', 'Mitte', 'Pariser Platz, 10117 Berlin', 'Coincée dans le no man''s land pendant 28 ans, la porte néoclassique surmontée de son quadrige est devenue le symbole de la réunification. Au bout de l''avenue Unter den Linden, elle ouvre sur le Tiergarten et le Reichstag.', 'Revenez la nuit, quand elle est éclairée et presque vide.', false, 'img/s69.jpg', 'Raugeier · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Brandenburger_Tor_(1988).jpg'),
  ('s70', 'berlin', 'Coupole du Reichstag', 'Activité', 'free', 'Mitte', 'Platz der Republik 1, 11011 Berlin', 'Au-dessus de l''hémicycle du Bundestag, la coupole de verre de Norman Foster se gravit par une rampe en spirale, avec vue à 360° sur Berlin. Un symbole de transparence démocratique, gratuit et spectaculaire.', 'Inscription gratuite obligatoire en ligne, quelques jours avant.', false, 'img/s70.jpg', 'Jörg Braukmann · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Reichstagsgebäude_von_Westen.jpg'),
  ('s71', 'berlin', 'Mémorial de l''Holocauste', 'Culture', 'free', 'Mitte', 'Cora-Berliner-Straße 1, 10117 Berlin', '2 711 stèles de béton de hauteurs différentes forment un labyrinthe ondulant où l''on perd peu à peu ses repères. Sous le mémorial, un centre d''information bouleversant raconte des histoires de familles et de victimes.', 'Le centre d''information est fermé le lundi.', false, 'img/s71.jpg', 'Alexander Blum · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Memorial_to_the_Murdered_Jews_of_Europeabove.jpg'),
  ('s72', 'berlin', 'Neues Museum', 'Culture', 'p1', 'Île aux Musées', 'Bodestraße 1-3, 10178 Berlin', 'Reconstruit par David Chipperfield en gardant les cicatrices de la guerre, ce musée abrite le buste de Néfertiti, d''une beauté saisissante, et de riches collections égyptiennes et préhistoriques sur l''Île aux Musées, classée à l''UNESCO.', 'Réservez un créneau horaire, surtout le week-end.', false, 'img/s72.jpg', 'Philip Pikart · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nofretete_Neues_Museum.jpg'),
  ('s73', 'berlin', 'Tempelhofer Feld', 'Activité', 'free', 'Tempelhof', 'Tempelhofer Damm, 12101 Berlin', 'Fermé en 2008, l''aéroport historique du pont aérien est devenu un parc immense où l''on fait du vélo, du roller ou du cerf-volant sur les anciennes pistes. Jardins partagés et barbecues : la liberté berlinoise à l''état pur.', 'Louez un vélo et roulez sur la piste d''atterrissage au coucher du soleil.', false, 'img/s73.jpg', 'Matti Blume · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aerial,_Berlin_(_1090064).jpg'),
  ('s75', 'berlin', 'Mauerpark', 'Activité', 'free', 'Prenzlauer Berg', 'Bernauer Straße 63-64, 13355 Berlin', 'Sur l''ancien tracé du Mur, ce parc s''anime chaque dimanche avec un grand marché aux puces, des stands de street food et un karaoké géant en plein air où des centaines de personnes encouragent les chanteurs amateurs.', 'Le karaoké de l''amphithéâtre commence vers 15h en été.', false, 'img/s75.jpg', 'Traktorminze · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin_Mauerpark_2022.jpg'),
  ('s77', 'berlin', 'Prater Garten', 'Bar & nuit', 'p1', 'Prenzlauer Berg', 'Kastanienallee 7-9, 10435 Berlin', 'Ouvert en 1837, le plus vieux Biergarten de Berlin installe ses longues tables sous les châtaigniers. On y boit la bière de la maison et on mange bretzels et saucisses dans une ambiance détendue, entre familles et étudiants.', 'Ouvert seulement à la belle saison, quand il fait beau.', false, 'img/s77.jpg', 'Superbass · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pratergarten_Berlin_Kastanienallee.JPG'),
  ('s78', 'berlin', 'Mémorial du Mur de Berlin', 'Culture', 'free', 'Mitte', 'Bernauer Straße 111, 13355 Berlin', 'Sur la Bernauer Straße, où le Mur coupait les maisons en deux, le dernier tronçon conservé avec son chemin de ronde et son mirador fait comprendre la réalité de la division. Récits d''évasions et tunnels sont racontés tout au long du parcours.', 'Montez sur la tour d''observation face au centre de documentation.', false, 'img/s78.jpg', 'HerrAdams · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin,_Bernauer_Straße,_Überblick_2014-07.jpg'),
  ('s79', 'berlin', 'Fernsehturm', 'Activité', 'p2', 'Alexanderplatz', 'Panoramastraße 1A, 10178 Berlin', 'Avec ses 368 mètres, la tour de télévision construite par la RDA est visible de partout. Sa boule panoramique, à 203 mètres, offre la vue la plus haute sur Berlin ; le restaurant tourne sur lui-même en une heure.', 'Les billets à heure fixe évitent la file d''attente.', false, 'img/s79.jpg', 'Taxiarchos228 · FAL · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin_-_Berliner_Fernsehturm_-_Fensterreinigung.jpg'),
  ('ber12', 'berlin', 'Café Einstein Stammhaus', 'Restaurant', 'p2', 'Schöneberg', 'Kurfürstenstraße 58, 10785 Berlin', 'Dans une villa de 1878, ce café viennois à Berlin sert apfelstrudel, wiener schnitzel et café sur plateau d''argent, entre boiseries, miroirs et serveurs en tablier. Son jardin ombragé est un havre de paix en été.', 'Le petit-déjeuner servi jusqu''en début d''après-midi est une institution.', true, 'img/ber12.jpg', 'Fridolin freudenfett · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:TiergartenKurfürstenstraßeCafeEinstein.jpg'),
  ('ber13', 'berlin', 'Checkpoint Charlie', 'Activité', 'free', 'Mitte', 'Friedrichstraße 43-45, 10117 Berlin', 'L''ancien poste-frontière entre secteurs américain et soviétique, où chars américains et russes se firent face en 1961. La guérite est une réplique, mais les panneaux historiques en plein air racontent bien cette page de la guerre froide.', 'Les panneaux gratuits de la Friedrichstraße suffisent ; le musée voisin est cher.', false, 'img/ber13.jpg', 'Lyricmac at en.wikipedia · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Checkpoint_Charlie1.jpg'),
  ('ber14', 'berlin', 'Gendarmenmarkt', 'Activité', 'free', 'Mitte', 'Gendarmenmarkt, 10117 Berlin', 'Souvent qualifiée de plus belle place de Berlin, elle réunit la salle de concert de Schinkel entre deux églises jumelles à coupoles. En décembre, son marché de Noël est l''un des plus élégants d''Allemagne.', 'Montez au dôme de la cathédrale française pour la vue sur la place.', false, 'img/ber14.jpg', 'Ansgar Koreng · CC BY 3.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:150418_Konzerthaus_Berlin_Gendarmenmarkt.jpg'),
  ('ber15', 'berlin', 'Cathédrale de Berlin', 'Culture', 'p1', 'Île aux Musées', 'Am Lustgarten, 10178 Berlin', 'Coiffée de sa grande coupole verte, la cathédrale protestante cache un intérieur somptueux de marbre et d''or, une crypte avec les cercueils des Hohenzollern et une galerie extérieure qui offre une vue panoramique sur l''Île aux Musées.', 'Les 270 marches jusqu''à la galerie du dôme valent l''effort.', false, 'img/ber15.jpg', 'Thomas Wolf, www.foto-tw.de · CC BY-SA 3.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berliner_Dom_vor_Sonnenuntergang.jpg'),
  ('ber16', 'berlin', 'Alte Nationalgalerie', 'Culture', 'p1', 'Île aux Musées', 'Bodestraße 1-3, 10178 Berlin', 'Ce temple néoclassique sur l''Île aux Musées rassemble les grands romantiques allemands, Caspar David Friedrich en tête, ainsi que Monet, Manet et Renoir. Une collection à taille humaine dans un écrin superbe.', 'Le « Museumspass » donne accès à tous les musées de l''île.', false, 'img/ber16.jpg', 'Manfred Brückels · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:AlteNationalgalerie_1a.jpg'),
  ('ber17', 'berlin', 'Château de Charlottenburg', 'Culture', 'p2', 'Charlottenburg', 'Spandauer Damm 10-22, 14059 Berlin', 'La plus grande résidence royale de Berlin déploie ses salons baroques et rococo dorés, sa porcelaine et son immense jardin à la française qui se prolonge en parc anglais avec lac et mausolée.', 'Le parc est en accès libre : parfait pour un pique-nique.', false, 'img/ber17.jpg', 'Times · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin_Charlottenburger_Schloss_Strassenseite.jpg'),
  ('ber18', 'berlin', 'Tiergarten', 'Activité', 'free', 'Tiergarten', 'Straße des 17. Juni, 10557 Berlin', 'Ancien terrain de chasse des princes, ce poumon vert de 210 hectares en plein cœur de Berlin mêle lacs, ruisseaux et sentiers boisés. Le Café am Neuen See y loue des barques et sert de la bière au bord de l''eau.', 'Le Café am Neuen See est idéal pour une pause au bord du lac.', false, 'img/ber18.jpg', 'beedubz · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin_Tiergarten_Siegessäule_Luftansicht.jpg'),
  ('ber19', 'berlin', 'Colonne de la Victoire', 'Activité', 'p1', 'Tiergarten', 'Großer Stern 1, 10557 Berlin', 'Surmontée d''une Victoire dorée surnommée « Goldelse » par les Berlinois, la colonne se dresse au milieu du Tiergarten. 285 marches mènent à une plateforme avec vue sur la porte de Brandebourg et la ville.', 'On y accède par des passages souterrains : ne traversez pas le rond-point.', false, 'img/ber19.jpg', 'Taxiarchos228 · FAL · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin_-_Siegessäule1.jpg'),
  ('ber20', 'berlin', 'Topographie de la Terreur', 'Culture', 'free', 'Kreuzberg', 'Niederkirchnerstraße 8, 10963 Berlin', 'Sur le site de l''ancien quartier général de la Gestapo et des SS, ce centre de documentation retrace les rouages de la terreur nazie. Le long d''un tronçon du Mur conservé, l''exposition en plein air est aussi saisissante que gratuite.', 'Comptez au moins 1h30 ; l''entrée est gratuite.', false, 'img/ber20.jpg', 'Josef Streichholz · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dokumentationszentrum_Topographie_des_Terrors.jpg'),
  ('ber21', 'berlin', 'DDR Museum', 'Culture', 'p1', 'Mitte', 'Karl-Liebknecht-Straße 1, 10178 Berlin', 'Un musée interactif pour comprendre la vie quotidienne en Allemagne de l''Est : on monte dans une Trabant, on fouille les tiroirs d''un appartement reconstitué et on découvre la surveillance de la Stasi. Ludique et instructif.', 'Achetez le billet en ligne pour un petit rabais.', false, 'img/ber21.jpg', 'Flocci Nivis · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:20220811_DDR-Museum_02.jpg'),
  ('ber22', 'berlin', 'KaDeWe', 'Restaurant', 'p2', 'Schöneberg', 'Tauentzienstraße 21-24, 10789 Berlin', 'Le plus grand magasin d''Europe continentale réserve son 6e étage à la gastronomie : des milliers de produits fins et des comptoirs où l''on déguste huîtres, sushis, saucisses et pâtisseries sous une verrière.', 'Le jardin d''hiver du 7e étage a une belle vue sur la Tauentzienstraße.', false, 'img/ber22.jpg', 'Jörg Zägel · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin,_Schoeneberg,_Tauentzienstrasse_21-24,_KaDeWe.jpg'),
  ('ber23', 'berlin', 'Hackesche Höfe', 'Activité', 'free', 'Mitte', 'Rosenthaler Straße 40-41, 10178 Berlin', 'Huit cours intérieures en enfilade, dont la première est couverte de céramiques Art nouveau, abritent boutiques de créateurs, cinéma, théâtre et cafés. Le point de départ idéal pour explorer le quartier de Spandauer Vorstadt.', 'Ne manquez pas la petite cour voisine du Haus Schwarzenberg, couverte de street art.', false, 'img/ber23.jpg', 'Arne Müseler · CC BY-SA 3.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hackesche_höfe_berlin.jpg'),
  ('ber24', 'berlin', 'Oberbaumbrücke', 'Activité', 'free', 'Kreuzberg', 'Oberbaumstraße, 10997 Berlin', 'Ce pont de brique rouge aux tourelles néogothiques relie Kreuzberg et Friedrichshain, autrefois séparés par le Mur. Le métro jaune qui passe sur l''étage supérieur, devant la Spree au coucher du soleil, est l''une des images les plus berlinoises.', 'Au coucher du soleil, depuis la rive de l''East Side Gallery.', false, 'img/ber24.jpg', 'Sarah Jane at Flickr · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Oberbaumbrücke_mit_U-Bahn.jpg'),
  ('ber25', 'berlin', 'Clärchens Ballhaus', 'Bar & nuit', 'p2', 'Mitte', 'Auguststraße 24, 10117 Berlin', 'Depuis 1913, cette salle de bal a survécu aux guerres et à la RDA. Guirlandes lumineuses, salle des miroirs à l''étage et jardin en été : on vient y danser le tango, le swing ou la salsa, quel que soit son niveau.', 'Des cours de danse sont proposés en début de soirée.', false, 'img/ber25.jpg', 'Clärchens Ballhaus · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Außenansicht_Clärchens_Ballhaus.jpg'),
  ('ber26', 'berlin', 'Café Kranzler', 'Restaurant', 'p2', 'Charlottenburg', 'Kurfürstendamm 18, 10719 Berlin', 'Avec sa rotonde à auvent rayé rouge et blanc, ce café emblématique du Kurfürstendamm a été le salon de Berlin-Ouest. On y monte pour un café et un gâteau avec vue plongeante sur la grande avenue commerçante.', 'Montez à la rotonde pour la vue sur le Ku''damm.', false, 'img/ber26.jpg', 'Taxiarchos228 · FAL · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin_-_Café_Kranzler1.jpg'),
  ('ber27', 'berlin', 'SO36', 'Bar & nuit', 'p1', 'Kreuzberg', 'Oranienstraße 190, 10999 Berlin', 'Club punk mythique de Kreuzberg depuis 1978, où ont joué les Dead Kennedys et où David Bowie et Iggy Pop venaient traîner. Concerts, soirées queer et bal turc : l''âme alternative de Berlin.', 'Consultez le programme : chaque soirée a une ambiance très différente.', false, 'img/ber27.jpg', 'Georg Slickers · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Berlin-kreuzberg_so36_20051019_307.jpg'),
  ('ber28', 'berlin', 'Badeschiff', 'Activité', 'p1', 'Treptow', 'Eichenstraße 4, 12435 Berlin', 'Une ancienne barge transformée en piscine flotte sur la Spree, avec vue sur l''Oberbaumbrücke et la tour de télévision. Sur la plage de sable autour, transats, musique et cocktails : l''été berlinois par excellence.', 'Venez en semaine en matinée pour éviter la foule.', false, 'img/ber28.jpg', 'JIP at English Wikipedia · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Badeschiff.jpg'),
  ('ber29', 'berlin', 'Teufelsberg', 'Activité', 'p1', 'Grunewald', 'Teufelsseechaussee 10, 14193 Berlin', 'Sur une colline artificielle faite de décombres de la guerre, une ancienne station d''écoute américaine aux dômes blancs déchirés est couverte de street art. La vue sur la forêt de Grunewald et Berlin y est spectaculaire.', 'Prévoyez une bonne balade à pied depuis la gare de Heerstraße.', false, 'img/ber29.jpg', 'Axel Mauruszat · Attribution · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Teufelsberg_ehem_Radaranlage.jpg'),
  ('ber30', 'berlin', 'Altes Museum', 'Culture', 'p1', 'Île aux Musées', 'Am Lustgarten, 10178 Berlin', 'Premier musée de l''Île aux Musées, ce temple à colonnade de Schinkel abrite les antiquités grecques, étrusques et romaines. Sa rotonde inspirée du Panthéon de Rome est un chef-d''œuvre d''architecture.', 'Le jardin du Lustgarten devant le musée est parfait pour une pause.', false, 'img/ber30.jpg', 'Avda · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Altes_Museum,_Berlin_2012.jpg'),
  ('s21', 'amsterdam', 'Vondelpark', 'Activité', 'free', 'Oud-Zuid', 'Vondelpark, 1071 AA Amsterdam', 'Le grand parc d''Amsterdam, avec ses étangs, ses pelouses et ses ponts, voit défiler cyclistes, coureurs et pique-niqueurs. En été, le théâtre en plein air y programme concerts et spectacles gratuits.', 'Le théâtre en plein air est gratuit l''été, du mercredi au dimanche.', false, 'img/s21.jpg', 'Dguendel · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam,_Vondelpark,_at_the_pond-2.jpg'),
  ('s22', 'amsterdam', 'Rijksmuseum', 'Culture', 'p2', 'Museumplein', 'Museumstraat 1, 1071 XX Amsterdam', 'Le grand musée national des Pays-Bas abrite La Ronde de nuit de Rembrandt et La Laitière de Vermeer, mais aussi des maquettes de navires, des maisons de poupées somptueuses et une bibliothèque à couper le souffle. On peut traverser son passage à vélo.', 'Réservez un créneau horaire en ligne ; la bibliothèque Cuypers est visible depuis la galerie.', true, 'img/s22.jpg', 'User:Voytikof · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_-_Rijksmuseum.jpg'),
  ('s23', 'amsterdam', 'Brouwerij ''t IJ', 'Bar & nuit', 'p1', 'Oost', 'Funenkade 7, 1018 AL Amsterdam', 'Au pied du moulin à vent De Gooyer, cette brasserie artisanale installée dans d''anciens bains publics sert ses bières bio à la pression. La terrasse sous le moulin est l''un des spots les plus typiques d''Amsterdam.', 'La terrasse se remplit dès 16h quand il fait beau.', false, 'img/s23.jpg', 'SJSV · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Brouwerijhetij.jpg'),
  ('s24', 'amsterdam', 'Foodhallen', 'Restaurant', 'p2', 'Oud-West', 'Bellamyplein 51, 1053 AT Amsterdam', 'Dans un ancien dépôt de tramways en brique, une vingtaine de stands servent bitterballen, dim sum, tacos, burgers et vins naturels. On compose son repas au comptoir et on partage de grandes tables dans une ambiance animée.', 'Idéal pour un groupe qui n''a pas les mêmes envies.', false, 'img/s24.jpg', 'SophieWikiAms · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:De_Hallen_Amsterdam_2024_Entree_Tollensstraat.jpg'),
  ('s80', 'amsterdam', 'Musée Van Gogh', 'Culture', 'p2', 'Museumplein', 'Museumplein 6, 1071 DJ Amsterdam', 'La plus grande collection au monde de Van Gogh suit le peintre de ses débuts sombres aux Tournesols et aux champs de blé éclatants, à travers 200 tableaux et ses lettres à son frère Théo. Émouvant de bout en bout.', 'Billets uniquement en ligne, à réserver plusieurs jours avant.', false, 'img/s80.jpg', 'C messier · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Van_Gogh_Museum_7206_rt_HDR.jpg'),
  ('s81', 'amsterdam', 'Maison d''Anne Frank', 'Culture', 'p2', 'Jordaan', 'Westermarkt 20, 1016 GV Amsterdam', 'Derrière la bibliothèque pivotante, l''Annexe où Anne Frank et sa famille se sont cachées pendant deux ans est restée vide, comme l''avait voulu son père. Le journal original y est exposé : une visite bouleversante.', 'Les billets sortent en ligne six semaines à l''avance, le mardi.', false, 'img/s81.jpg', 'Massimo Catarinella · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:AnneFrankHouseAmsterdamtheNetherlands.jpg'),
  ('s82', 'amsterdam', 'Balade dans le Jordaan', 'Activité', 'free', 'Jordaan', 'Egelantiersgracht, 1015 Amsterdam', 'Ancien quartier ouvrier devenu le plus charmant d''Amsterdam : canaux étroits, maisons penchées, cours intérieures fleuries, galeries et cafés bruns. On y flâne sans but entre street art et boutiques indépendantes.', 'Le marché du Noordermarkt a lieu le lundi matin et le samedi.', false, 'img/s82.jpg', 'Fons Heijnsbroek · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A_mixture_of_wall-paintings_on_the_wall,_at_the_corner_Prinsengracht_canal_and_Anjelierstraat,_Amsterdam_from_photographer,_Fons_Heijnsbroek.jpg'),
  ('s83', 'amsterdam', 'Albert Cuypmarkt', 'Activité', 'free', 'De Pijp', 'Albert Cuypstraat, 1073 BD Amsterdam', 'Le plus grand marché de rue des Pays-Bas aligne 260 étals au cœur du quartier multiculturel de De Pijp. On y croque des stroopwafels tout chauds, du hareng cru et des fromages de Gouda.', 'Fermé le dimanche ; goûtez un stroopwafel tout juste fait.', false, 'img/s83.jpg', 'Alf van Beem · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Albert_Cuyp_markt,_foto8.JPG'),
  ('s85', 'amsterdam', 'Café Hoppe', 'Bar & nuit', 'p1', 'Spui', 'Spui 18-20, 1012 XA Amsterdam', 'Ouvert en 1670, l''un des plus vieux cafés bruns d''Amsterdam garde son sol couvert de sable, ses tonneaux de genièvre et ses murs patinés. Le soir, les habitués débordent sur le trottoir du Spui, une bière à la main.', 'Le soir, on boit debout dehors avec les habitués.', false, 'img/s85.jpg', 'Paul2 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hoppe-amsterdam-zijgevel.jpg'),
  ('s87', 'amsterdam', 'A''DAM Lookout', 'Activité', 'p2', 'Noord', 'Overhoeksplein 5, 1031 KS Amsterdam', 'Au sommet de la tour A''DAM, une terrasse panoramique domine les canaux, le port et la gare centrale. Les plus audacieux montent sur « Over the Edge », une balançoire qui s''élance au-dessus du vide à 100 mètres de haut.', 'Le ferry gratuit depuis la gare centrale y mène en 5 minutes.', false, 'img/s87.jpg', 'Slaunger · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shell_Tower_Amsterdam-Noord_from_tour_boat_2016-09-12.jpg'),
  ('s88', 'amsterdam', 'NDSM-werf', 'Culture', 'free', 'Noord', 'NDSM-Plein, 1033 WC Amsterdam', 'Cet ancien chantier naval est devenu le quartier créatif d''Amsterdam : hangars géants transformés en ateliers d''artistes, street art monumental, grue-hôtel et festivals. Le plus grand marché aux puces d''Europe s''y tient certains week-ends.', 'Prenez le ferry gratuit F4 depuis la gare centrale.', false, 'img/s88.jpg', 'Ceescamel · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2022_NDSM-plein,_Asd-muurschildering_Anne_Frank.jpg'),
  ('s89', 'amsterdam', 'Begijnhof', 'Activité', 'free', 'Centrum', 'Begijnhof, 1012 Amsterdam', 'Derrière une porte discrète du Spui se cache une cour paisible du XIVe siècle, bordée de maisons étroites autour d''une pelouse. On y trouve la plus vieille maison en bois d''Amsterdam : un îlot de silence en plein centre.', 'Entrée par la porte du Spui ; parlez à voix basse, des gens y vivent.', false, 'img/s89.jpg', 'acediscovery · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Begijnhof_Amsterdam_April_2014.jpg'),
  ('ams13', 'amsterdam', 'Stedelijk Museum', 'Culture', 'p2', 'Museumplein', 'Museumplein 10, 1071 DJ Amsterdam', 'Surnommé « la baignoire » pour son extension blanche futuriste, le musée d''art moderne d''Amsterdam rassemble Mondrian, Malevitch, Matisse, Warhol et le meilleur du design hollandais. Un contrepoint parfait aux maîtres anciens du Rijksmuseum.', 'Ouvert jusqu''à 22h le vendredi.', false, 'img/ams13.jpg', 'John Lewis Marshall · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:De_nieuwe_vleugel_van_het_Stedelijk_Museum_Amsterdam.jpg'),
  ('ams15', 'amsterdam', 'Palais royal', 'Culture', 'p1', 'Dam', 'Dam 1, 1012 JS Amsterdam', 'Construit comme hôtel de ville au XVIIe siècle, au sommet de la puissance hollandaise, ce palais impressionne par sa salle des Bourgeois en marbre, au sol gravé de cartes du monde. Il sert encore à la famille royale pour les réceptions.', 'Vérifiez les dates : il ferme lors des événements royaux.', false, 'img/ams15.jpg', 'Deerpeter · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paleis_op_de_Dam_2026.jpg'),
  ('ams16', 'amsterdam', 'Place du Dam', 'Activité', 'free', 'Centrum', 'Dam, 1012 Amsterdam', 'Le cœur historique d''Amsterdam, là où une digue sur l''Amstel a donné son nom à la ville. Entourée du Palais royal, de la Nouvelle Église et du Monument national, la place est toujours animée par les artistes de rue et les pigeons.', 'Le grand magasin De Bijenkorf voisin a un café avec vue.', false, 'img/ams16.jpg', 'Deerpeter · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dam_Square_2026.jpg'),
  ('ams17', 'amsterdam', 'Bloemenmarkt', 'Activité', 'free', 'Centrum', 'Singel, 1017 AZ Amsterdam', 'Le seul marché aux fleurs flottant au monde aligne ses étals sur des péniches le long du canal Singel. Bulbes de tulipes, graines et souvenirs : une explosion de couleurs, surtout au printemps.', 'Vérifiez que vos bulbes ont un certificat si vous voyagez hors UE.', false, 'img/ams17.jpg', 'Shadowgate from Novara, ITALY · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_(16033009226).jpg'),
  ('ams18', 'amsterdam', 'Westerkerk', 'Culture', 'p1', 'Jordaan', 'Prinsengracht 281, 1016 GW Amsterdam', 'Sa tour de 85 mètres, la plus haute d''Amsterdam, est couronnée de la couronne impériale. On la gravit en visite guidée pour une vue sur le Jordaan et les canaux ; Rembrandt est enterré dans l''église.', 'Les montées à la tour se font par petits groupes : réservez.', false, 'img/ams18.jpg', 'Dietmar Rabich · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_(NL),_Westerkerk_--_2015_--_7179.jpg'),
  ('ams19', 'amsterdam', 'Oude Kerk', 'Culture', 'p1', 'De Wallen', 'Oudekerksplein 23, 1012 GX Amsterdam', 'Le plus vieux bâtiment d''Amsterdam (vers 1300) est une immense église gothique au plafond de bois, au sol couvert de pierres tombales, qui accueille aujourd''hui des installations d''art contemporain. Paradoxe : elle se dresse au milieu du quartier rouge.', 'Le jardin et le café de l''église sont des havres de calme.', false, 'img/ams19.jpg', 'Gerd Eichmann · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam-508-Oude_Kerk-2010-gje.jpg'),
  ('ams20', 'amsterdam', 'Waag et Nieuwmarkt', 'Activité', 'free', 'Nieuwmarkt', 'Nieuwmarkt 4, 1012 CR Amsterdam', 'Cette ancienne porte de ville du XVe siècle aux tourelles de conte trône sur la place du Nieuwmarkt, entourée de terrasses. Le samedi, un marché bio y vend fromages, pains et produits fermiers.', 'Le marché bio a lieu le samedi.', false, 'img/ams20.jpg', 'Patrick Verdier · Copyrighted free use · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_-_Waag.jpg'),
  ('ams21', 'amsterdam', 'Hortus Botanicus', 'Activité', 'p1', 'Plantage', 'Plantage Middenlaan 2a, 1018 DD Amsterdam', 'L''un des plus vieux jardins botaniques du monde (1638) mêle serres tropicales, palmier de 300 ans et plantes rapportées par la Compagnie des Indes. La serre aux papillons est un petit bonheur.', 'L''orangerie-café est parfaite pour une pause.', false, 'img/ams21.jpg', 'Agnes Monkelbaan · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hortus_Botanicus_Amsterdam._(actm.).jpg'),
  ('ams23', 'amsterdam', 'Het Scheepvaartmuseum', 'Culture', 'p2', 'Kattenburg', 'Kattenburgerplein 1, 1018 KK Amsterdam', 'Dans un ancien arsenal naval sous une verrière spectaculaire, le musée maritime raconte l''âge d''or hollandais. On monte à bord d''une réplique grandeur nature d''un navire de la Compagnie des Indes amarré devant.', 'Le navire Amsterdam est le clou de la visite.', false, 'img/ams23.jpg', 'Gouwenaar · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Het_scheepvaartmuseum1_Amsterdam.jpg'),
  ('ams24', 'amsterdam', 'NEMO Science Museum', 'Culture', 'p2', 'Oosterdok', 'Oosterdok 2, 1011 VX Amsterdam', 'Ce bâtiment vert en forme de proue de navire signé Renzo Piano abrite un musée des sciences interactif. Son toit-terrasse en pente, accessible gratuitement, offre une vue superbe sur le port et la vieille ville.', 'Le toit est gratuit et ouvert même sans billet.', false, 'img/ams24.jpg', 'Velvet · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_vue_Nemo.JPG'),
  ('ams25', 'amsterdam', 'Eye Filmmuseum', 'Culture', 'p1', 'Noord', 'IJpromenade 1, 1031 KT Amsterdam', 'Ce bâtiment blanc futuriste au bord de l''IJ abrite le musée du cinéma : expositions, salles de projection et archives. Son bar-restaurant à la terrasse face à l''eau est l''un des plus beaux d''Amsterdam.', 'Le ferry gratuit depuis la gare centrale y dépose en 3 minutes.', false, 'img/ams25.jpg', 'Jvhertum · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:EYE_Filmmuseum.jpg'),
  ('ams26', 'amsterdam', 'Paradiso', 'Bar & nuit', 'p2', 'Leidseplein', 'Weteringschans 6-8, 1017 SG Amsterdam', 'Dans une ancienne église du XIXe siècle aux vitraux préservés, Paradiso est la salle de concerts mythique d''Amsterdam, où sont passés les Rolling Stones, Prince et Amy Winehouse. Concerts puis club jusqu''au bout de la nuit.', 'Consultez la programmation : les soirées club suivent souvent les concerts.', false, 'img/ams26.jpg', 'Photo: Andreas Praefcke · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_Paradiso.jpg'),
  ('ams27', 'amsterdam', 'Melkweg', 'Bar & nuit', 'p2', 'Leidseplein', 'Lijnbaansgracht 234A, 1017 PH Amsterdam', 'Installée dans une ancienne laiterie, la « Voie lactée » est une salle de concerts et un centre culturel alternatif depuis 1970 : rock, électro, hip-hop, cinéma et expositions sous le même toit.', 'Billets moins chers en ligne qu''à l''entrée.', false, 'img/ams27.jpg', 'Kismenők · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Starset_-_Immersion_The_Final_Chapter_-_Melkweg_003.jpg'),
  ('ams28', 'amsterdam', 'Wynand Fockink', 'Bar & nuit', 'p1', 'Dam', 'Pijlsteeg 31, 1012 HH Amsterdam', 'Cachée dans une ruelle derrière le Dam, cette distillerie de 1679 sert ses liqueurs et genièvres dans une minuscule salle de dégustation. La tradition veut qu''on boive la première gorgée penché sur le verre rempli à ras bord, sans les mains.', 'Penchez-vous pour la première gorgée, comme le veut la tradition.', false, 'img/ams28.jpg', 'Gryffindor · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wynand_Focking_Amsterdam_2014_(6).jpg'),
  ('ams29', 'amsterdam', 'Café Américain', 'Restaurant', 'p2', 'Leidseplein', 'Leidsekade 97, 1017 PN Amsterdam', 'Ce café Art déco de 1902, avec ses vitraux, ses lustres et ses fresques, est l''un des plus beaux d''Amsterdam. On y prend le petit-déjeuner, un high tea ou un dîner dans un décor classé monument historique.', 'Le high tea de l''après-midi est un bon moyen de profiter du décor.', false, 'img/ams29.jpg', 'ECHAdam · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Café_Americain_2.jpg'),
  ('ams30', 'amsterdam', 'Magere Brug', 'Activité', 'free', 'Centrum', 'Kerkstraat, 1017 GC Amsterdam', 'Ce pont-levis blanc en bois sur l''Amstel, éclairé de centaines d''ampoules la nuit, est le plus romantique d''Amsterdam. On le voit encore s''ouvrir pour laisser passer les bateaux.', 'Revenez de nuit, quand les ampoules s''allument.', false, 'img/ams30.jpg', 'Jvhertum · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Magere_brug_amsterdam.jpg'),
  ('ams31', 'amsterdam', 'Moco Museum', 'Culture', 'p2', 'Museumplein', 'Honthorststraat 20, 1071 DE Amsterdam', 'Dans une villa du Museumplein, un musée d''art moderne et urbain consacré à Banksy, Warhol, Basquiat et aux artistes numériques.', 'Billets moins chers en ligne.', false, 'img/ams31.jpg', 'C messier · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Moco_Museum_Amsterdam_2159.jpg'),
  ('ams32', 'amsterdam', 'Nieuwe Kerk', 'Culture', 'p2', 'Dam', 'Dam 12, 1012 NL Amsterdam', 'L''église où sont couronnés les rois néerlandais accueille aujourd''hui de grandes expositions dans un cadre gothique spectaculaire.', 'Vérifiez l''exposition en cours avant d''y aller.', false, 'img/ams32.jpg', 'C messier · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_Nieuwe_Kerk_1697.jpg'),
  ('prg01', 'prague', 'Pont Charles', 'Activité', 'free', 'Malá Strana', 'Karlův most, 110 00 Praha 1', 'Gothique, pavé et bordé de trente statues de saints noircies par le temps, le pont Charles relie la Vieille-Ville au château depuis le XIVe siècle. À l''aube, dans la brume de la Vltava, c''est l''un des plus beaux endroits d''Europe.', 'Venez au lever du soleil, quand il est presque désert.', false, 'img/prg01.jpg', 'A.Savin · FAL · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prague_07-2016_View_from_Petrinska_Tower_img2.jpg'),
  ('prg02', 'prague', 'Château de Prague', 'Culture', 'p2', 'Hradčany', 'Hradčany, 119 08 Praha 1', 'Le plus grand complexe de château ancien du monde domine Prague : cathédrale gothique, palais royal, basilique romane et la Ruelle d''or aux maisonnettes colorées où vécut Kafka. La vue sur la ville aux cent clochers est inoubliable.', 'Les cours et jardins sont gratuits ; la relève de la garde a lieu chaque heure.', false, 'img/prg02.jpg', 'Stefan Bauer, http://www.ferras.at · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hradschin_Prag.jpg'),
  ('prg03', 'prague', 'Cathédrale Saint-Guy', 'Culture', 'p2', 'Hradčany', 'III. nádvoří 48/2, 119 01 Praha 1', 'Au cœur du château, cette cathédrale gothique aux flèches élancées a mis six siècles à être achevée. Ses vitraux, dont un signé Mucha, et la chapelle Saint-Venceslas couverte de pierres précieuses sont éblouissants.', 'La nef est visible gratuitement depuis l''entrée ; le billet du château donne accès à tout.', false, 'img/prg03.jpg', 'o¬. · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha,_Katedrála,_JV_01.jpg'),
  ('prg04', 'prague', 'Horloge astronomique', 'Activité', 'free', 'Staré Město', 'Staroměstské náměstí 1, 110 00 Praha 1', 'Vieille de 600 ans, la plus ancienne horloge astronomique encore en marche s''anime chaque heure : les douze apôtres défilent et un squelette sonne la cloche. Montez en haut de la tour de l''hôtel de ville pour la vue sur la place.', 'Le spectacle a lieu toutes les heures de 9h à 23h ; la tour est payante.', false, 'img/prg04.jpg', 'Uoaei1 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha_Astronomical_Clock_02.jpg'),
  ('prg05', 'prague', 'Place de la Vieille-Ville', 'Activité', 'free', 'Staré Město', 'Staroměstské náměstí, 110 00 Praha 1', 'Entourée de façades baroques et gothiques pastel, dominée par les flèches de l''église de Týn, cette place est le cœur de Prague depuis le Moyen Âge. Marchés de Noël et de Pâques y installent leurs chalets.', 'Évitez les terrasses de la place, chères ; allez une rue plus loin.', false, 'img/prg05.jpg', 'A.Savin · FAL · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prague_07-2016_View_from_Old_Town_Hall_Tower_img3.jpg'),
  ('prg06', 'prague', 'Synagogue espagnole', 'Culture', 'p2', 'Josefov', 'Vězeňská 1, 110 00 Praha 1', 'Son intérieur mauresque doré et coloré est l''un des plus beaux d''Europe. Elle fait partie du Musée juif, avec le vieux cimetière aux 12 000 tombes enchevêtrées et la synagogue Pinkas, bouleversante.', 'Un billet unique donne accès à tous les sites du Musée juif.', false, 'img/prg06.jpg', 'C. Löser · CC BY 3.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prag_Spanische-Synagoge_Feb-2014_IMG_2171.JPG'),
  ('prg07', 'prague', 'Colline de Petřín', 'Activité', 'free', 'Malá Strana', 'Petřínské sady, 118 00 Praha 1', 'Cette colline boisée couverte de vergers offre des vues superbes sur Prague. Au sommet, une mini tour Eiffel, un labyrinthe de miroirs et une roseraie ; on y monte à pied ou en funiculaire.', 'Le funiculaire est inclus dans le ticket de transport en commun.', false, 'img/prg07.jpg', 'Ludek · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Petrin_Praha.jpg'),
  ('prg08', 'prague', 'Mur John Lennon', 'Activité', 'free', 'Malá Strana', 'Velkopřevorské náměstí, 118 00 Praha 1', 'Depuis la mort de Lennon en 1980, ce mur est couvert de graffitis, de paroles de chansons et de messages de paix, sans cesse renouvelés. Sous le communisme, c''était un symbole de liberté.', 'Vous pouvez y laisser votre propre message.', false, 'img/prg08.jpg', 'Jirka Dl · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:John_Lennon_Wall,_Prague,_November_2014.jpg'),
  ('prg09', 'prague', 'Vyšehrad', 'Activité', 'free', 'Vyšehrad', 'V Pevnosti 159/5b, 128 00 Praha 2', 'Cette forteresse légendaire sur un rocher au-dessus de la Vltava abrite la basilique néogothique Saints-Pierre-et-Paul et le cimetière où reposent Dvořák, Smetana et Mucha. Calme et vue magnifique, loin de la foule.', 'Les remparts offrent une vue superbe sur le château au coucher du soleil.', false, 'img/prg09.jpg', 'Stanislav Jelen · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Parník_Vyšehrad_pod_Vyšehradem.jpg'),
  ('prg10', 'prague', 'Maison qui danse', 'Activité', 'p1', 'Nové Město', 'Jiráskovo náměstí 1981/6, 120 00 Praha 2', 'Surnommé « Ginger et Fred », cet immeuble déconstructiviste de Frank Gehry semble danser au bord de la Vltava. Son bar sur le toit offre une vue panoramique sur le château et le fleuve.', 'L''accès à la terrasse est inclus avec une consommation au bar.', false, 'img/prg10.jpg', 'Dino Quinzani · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Case_danzanti.jpg'),
  ('prg11', 'prague', 'Place Venceslas', 'Activité', 'free', 'Nové Město', 'Václavské náměstí, 110 00 Praha 1', 'Ce grand boulevard de 750 mètres est le théâtre de l''histoire tchèque, du Printemps de Prague à la Révolution de velours. Il est dominé par la statue équestre de saint Venceslas et la façade du Musée national.', 'Ne manquez pas le passage Lucerna et son cheval suspendu à l''envers, à deux pas.', false, 'img/prg11.jpg', 'SteinundBaum · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2022-10-15_Václavské_náměstí_1.jpg'),
  ('prg12', 'prague', 'Musée national', 'Culture', 'p1', 'Nové Město', 'Václavské náměstí 68, 110 00 Praha 1', 'Ce palais néo-Renaissance au sommet de la place Venceslas a rouvert après une grande rénovation. Son panthéon sous coupole, ses escaliers monumentaux et ses collections d''histoire naturelle impressionnent.', 'Montez à la coupole pour une vue plongeante sur la place.', false, 'img/prg12.jpg', 'VitVit · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha_Národní_muzeum_1.jpg'),
  ('prg13', 'prague', 'Café Louvre', 'Restaurant', 'p1', 'Nové Město', 'Národní 22, 110 00 Praha 1', 'Ouvert en 1902, ce grand café viennois aux murs rose pâle a accueilli Kafka et Einstein. On y prend le petit-déjeuner, une part de gâteau ou un plat tchèque, et on joue au billard dans la salle du fond.', 'Le petit-déjeuner est excellent et très abordable.', true, 'img/prg13.jpg', 'VitVit · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha_Café_Louvre.JPG'),
  ('prg14', 'prague', 'Café Slavia', 'Restaurant', 'p1', 'Nové Město', 'Smetanovo nábřeží 1012/2, 110 00 Praha 1', 'Face au Théâtre national et au château, ce café Art déco était le repaire des artistes et dissidents, dont Václav Havel. Ses grandes baies vitrées sur la Vltava en font l''un des cafés les plus romantiques de Prague.', 'Demandez une table près des fenêtres côté rivière.', false, 'img/prg14.jpg', 'VitVit · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palác_Lažanských_celek.JPG'),
  ('prg15', 'prague', 'Maison municipale', 'Restaurant', 'p2', 'Staré Město', 'Náměstí Republiky 5, 111 21 Praha 1', 'Chef-d''œuvre Art nouveau décoré par Mucha, la Maison municipale abrite un somptueux café aux lustres et dorures. On y savoure un café et une pâtisserie dans l''un des intérieurs les plus beaux d''Europe.', 'Le café du rez-de-chaussée permet de profiter du décor à prix raisonnable.', false, 'img/prg15.jpg', 'Thomas Ledl · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jugendstil_Prag_Gemeindehaus_1.jpg'),
  ('prg16', 'prague', 'U Fleků', 'Bar & nuit', 'p1', 'Nové Město', 'Křemencova 11, 110 00 Praha 1', 'Cette brasserie brasse sa bière brune depuis 1499. Dans ses salles lambrissées et son grand jardin, les serveurs passent avec des plateaux de chopes et l''accordéoniste fait chanter les tablées.', 'Méfiez-vous des petits verres de liqueur proposés d''office : ils sont facturés.', false, 'img/prg16.jpg', 'Vincent de Groot - http://www.videgro.net · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha_u_fleku.JPG'),
  ('prg17', 'prague', 'U Zlatého tygra', 'Bar & nuit', 'p1', 'Staré Město', 'Husova 228/17, 110 00 Praha 1', 'Le pub préféré de l''écrivain Bohumil Hrabal, où il emmena Bill Clinton et Václav Havel. On y boit la Pilsner Urquell la mieux servie de Prague, avec des habitués qui occupent les tables depuis des décennies.', 'Arrivez à l''ouverture (15h) : les places sont rares.', false, 'img/prg17.jpg', 'Michal Kmínek · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Městský_dům_U_zlatého_tygra_(Staré_Město),_Praha_1,_Husova_17,_Staré_Město.jpg'),
  ('prg19', 'prague', 'Bibliothèque de Strahov', 'Culture', 'p1', 'Hradčany', 'Strahovské nádvoří 1/132, 118 00 Praha 1', 'Ses salles baroques Théologique et Philosophique, aux plafonds peints et aux rayonnages dorés jusqu''au plafond, comptent parmi les plus belles bibliothèques du monde. On les admire depuis le seuil.', 'Un supplément photo est demandé.', false, 'img/prg19.jpg', 'Skot · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Strahovská_knihovna_–_Filozofický_sál.jpg'),
  ('prg20', 'prague', 'Jardin Wallenstein', 'Activité', 'free', 'Malá Strana', 'Letenská 123/4, 118 00 Praha 1', 'Ce jardin baroque caché derrière le palais du Sénat mêle allées de statues, bassin, paons en liberté et un étonnant mur de stalactites artificielles. Un havre de calme à deux pas de la foule.', 'Ouvert d''avril à octobre ; entrée gratuite.', false, 'img/prg20.jpg', 'VitVit · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Malá_Strana_Valdštejnská_zahrada_a_sala_terrena_2.jpg'),
  ('prg21', 'prague', 'Biergarten de Letná', 'Bar & nuit', 'p1', 'Letná', 'Letenské sady, 170 00 Praha 7', 'Sur la colline de Letná, ce Biergarten sous les marronniers offre la plus belle vue sur les ponts de Prague avec une bière à la main. Le soir d''été, toute la jeunesse pragoise s''y retrouve.', 'Le coucher du soleil sur les ponts est spectaculaire.', false, 'img/prg21.jpg', 'I would appreciate being notified if you use my work outs... · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha,_Holešovice,_podzim_na_Letné.jpg'),
  ('prg22', 'prague', 'Musée Kampa', 'Culture', 'p1', 'Malá Strana', 'U Sovových mlýnů 2, 118 00 Praha 1', 'Dans un ancien moulin au bord de la Vltava, ce musée d''art moderne d''Europe centrale expose Kupka et accueille des sculptures étonnantes, dont les bébés géants de David Černý qui rampent dans le parc.', 'Les bébés de David Černý sont visibles gratuitement dans le parc.', false, 'img/prg22.jpg', 'NoJin · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hlavní_budova_Musea_Kampa_z_terasy.jpg'),
  ('prg23', 'prague', 'Île de Kampa', 'Activité', 'free', 'Malá Strana', 'Na Kampě, 118 00 Praha 1', 'Séparée de Malá Strana par un petit canal, la « Venise de Prague » cache des moulins à eau, des maisons colorées et un parc au bord du fleuve. Un coin paisible juste sous le pont Charles.', 'Parfait pour un pique-nique au bord de la Vltava.', false, 'img/prg23.jpg', 'Chmee2 · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kampa5.jpg'),
  ('prg24', 'prague', 'Tour poudrière', 'Activité', 'p1', 'Staré Město', 'Náměstí Republiky 5, 110 00 Praha 1', 'Cette porte gothique noircie marque le début de la Voie royale empruntée par les rois de Bohême jusqu''au château. On peut monter à son sommet pour une vue sur la Vieille-Ville.', 'Suivez ensuite la Voie royale jusqu''au pont Charles.', false, 'img/prg24.jpg', 'A.Savin · FAL · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prague_07-2016_Powder_Tower_from_Republic_Square.jpg'),
  ('prg25', 'prague', 'Église Notre-Dame-du-Týn', 'Culture', 'p1', 'Staré Město', 'Staroměstské náměstí, 110 00 Praha 1', 'Ses deux flèches gothiques hérissées de clochetons, qui auraient inspiré Disney, dominent la place de la Vieille-Ville. L''intérieur baroque abrite la tombe de l''astronome Tycho Brahe.', 'Le soir, les flèches illuminées sont superbes depuis la place.', false, 'img/prg25.jpg', 'A.Savin · FAL · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prague_07-2016_View_from_Old_Town_Hall_Tower_img2.jpg'),
  ('prg27', 'prague', 'Clementinum', 'Culture', 'p1', 'Staré Město', 'Mariánské náměstí 5, 110 00 Praha 1', 'Cet ancien collège jésuite cache la bibliothèque baroque la plus spectaculaire de Prague, avec ses globes et ses fresques, et une tour astronomique qui offre l''une des plus belles vues de la ville.', 'Visite guidée uniquement, toutes les 30 minutes.', false, 'img/prg27.jpg', 'Skot · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Klementinum_–_průčelí_z_Mariánského_náměstí.jpg'),
  ('prg29', 'prague', 'Náplavka', 'Bar & nuit', 'p1', 'Nové Město', 'Rašínovo nábřeží, 128 00 Praha 2', 'Ces quais au bord de la Vltava se transforment le soir en terrasse géante : péniches-bars, stands de bière et musique. Le samedi matin, un marché fermier y attire les Pragois.', 'Le marché fermier du samedi matin est excellent.', false, 'img/prg29.jpg', 'Txllxt TxllxT · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha_-_Rašínovo_nábřeží_-_View_North.jpg'),
  ('prg30', 'prague', 'Tour de télévision de Žižkov', 'Activité', 'p1', 'Žižkov', 'Mahlerovy sady 1, 130 00 Praha 3', 'Cette tour futuriste de 216 mètres, sur laquelle grimpent les bébés géants de David Černý, offre une vue à 93 mètres sur tout Prague. Un contrepoint étonnant à la ville baroque.', 'Le quartier de Žižkov autour est plein de bars à bière bon marché.', false, 'img/prg30.jpg', 'Thomas Ledl · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prag_Fernsehturm.jpg'),
  ('prg31', 'prague', 'Musée Mucha', 'Culture', 'p1', 'Nové Město', 'Panská 7, 110 00 Praha 1', 'Un petit musée consacré à Alfons Mucha, maître de l''Art nouveau, avec ses affiches célèbres et ses dessins.', 'Visite courte, idéale avant la Maison municipale.', false, 'img/prg31.jpg', 'VitVit · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha-Nové_Město_Kounický_palác_1.jpg'),
  ('prg32', 'prague', 'Rudolfinum', 'Culture', 'p1', 'Josefov', 'Alšovo nábřeží 79/12, 110 00 Praha 1', 'Ce palais néo-Renaissance au bord de la Vltava abrite la salle Dvořák, où joue l''Orchestre philharmonique tchèque, et une galerie d''art contemporain. Un concert dans cette salle dorée est un grand moment.', 'Des billets à petit prix sont proposés pour les répétitions générales.', false, 'img/prg32.jpg', 'che · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praha_Rudolfinum_front.jpg'),
  ('prg33', 'prague', 'Théâtre national', 'Bar & nuit', 'p2', 'Nové Město', 'Národní 2, 110 00 Praha 1', 'Symbole du réveil national tchèque, ce théâtre au toit doré sur la Vltava accueille opéras, ballets et pièces. Sa salle rouge et or est l''une des plus belles d''Europe centrale.', 'Les places du dernier balcon sont très abordables.', false, 'img/prg33.jpg', 'Lynx1211 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Národní_divadlo_ze_Střeleckého_ostrova.jpg'),
  ('vie01', 'vienne', 'Château de Schönbrunn', 'Culture', 'p2', 'Hietzing', 'Schönbrunner Schloßstraße 47, 1130 Wien', 'La résidence d''été des Habsbourg déploie 1 441 pièces dont une quarantaine se visitent : salons rococo, galerie des glaces où Mozart joua enfant, appartements de Sissi. Ses jardins à la française montent jusqu''à la Gloriette, d''où la vue sur Vienne est magnifique.', 'Les jardins sont gratuits ; montez à la Gloriette pour la vue.', false, 'img/vie01.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_-_Schloss_Schönbrunn.JPG'),
  ('vie02', 'vienne', 'Belvédère', 'Culture', 'p2', 'Landstraße', 'Prinz-Eugen-Straße 27, 1030 Wien', 'Deux palais baroques reliés par des jardins en terrasses abritent la plus grande collection de Klimt au monde, dont Le Baiser, qui brille d''or. Schiele, Kokoschka et les impressionnistes complètent la visite.', 'Le billet pour le Belvédère supérieur suffit pour voir Le Baiser.', false, 'img/vie02.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_-_Schloss_Belvedere,_oberes_(1).JPG'),
  ('vie03', 'vienne', 'Cathédrale Saint-Étienne', 'Culture', 'free', 'Innere Stadt', 'Stephansplatz 3, 1010 Wien', 'Symbole de Vienne, cette cathédrale gothique est coiffée d''un toit de 230 000 tuiles vernissées formant l''aigle des Habsbourg. On peut grimper les 343 marches de sa tour sud ou descendre dans les catacombes.', 'L''entrée dans la nef est gratuite ; tours et catacombes sont payantes.', false, 'img/vie03.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_-_Stephansdom_(1).JPG'),
  ('vie04', 'vienne', 'Hofburg et musée Sissi', 'Culture', 'p2', 'Innere Stadt', 'Michaelerkuppel, 1010 Wien', 'Le palais impérial, siège du pouvoir des Habsbourg pendant six siècles, abrite les appartements impériaux, une collection d''argenterie éblouissante et un musée consacré à l''impératrice Sissi, ses robes et son destin tragique.', 'Le Sisi Ticket combine Hofburg, Schönbrunn et le musée du mobilier.', false, 'img/vie04.jpg', 'Walter Mittelholzer · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:ETH-BIB-Hofburg,_Wien-Weitere-LBS_MH02-30-0012.tif'),
  ('vie05', 'vienne', 'Kunsthistorisches Museum', 'Culture', 'p2', 'Innere Stadt', 'Maria-Theresien-Platz, 1010 Wien', 'Sous une coupole somptueuse, ce musée réunit la plus grande collection de Bruegel au monde, des Vermeer, Raphaël et Rembrandt. Le café installé sous la coupole est l''un des plus beaux d''Europe.', 'Le café sous la coupole vaut une pause à lui seul.', false, 'img/vie05.jpg', 'Hubertl · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:AT_13763_Exterior_of_the_Kunsthistorisches_Museum,_Vienna-4.jpg'),
  ('vie06', 'vienne', 'MuseumsQuartier', 'Activité', 'free', 'Neubau', 'Museumsplatz 1, 1070 Wien', 'Dans les anciennes écuries impériales, ce quartier des musées mêle architecture baroque et cubes contemporains. Dans les cours, des chaises longues colorées (les « Enzis ») accueillent les Viennois qui s''y prélassent.', 'Prenez un verre dans la cour, sur les Enzis, en soirée.', false, 'img/vie06.jpg', 'Roland Töfferl · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MQ_24_MuseumsQuartier_Wien_2025.jpg'),
  ('vie07', 'vienne', 'Leopold Museum', 'Culture', 'p2', 'Neubau', 'Museumsplatz 1, 1070 Wien', 'La plus grande collection au monde d''Egon Schiele, avec des œuvres de Klimt et du mouvement Sécession viennoise. Ses grandes baies vitrées cadrent la ville à la manière de tableaux.', 'La terrasse du café a une vue sur la Hofburg.', false, 'img/vie07.jpg', 'Gugerell · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_07_Leopold_Museum_a.jpg'),
  ('vie08', 'vienne', 'Albertina', 'Culture', 'p2', 'Innere Stadt', 'Albertinaplatz 1, 1010 Wien', 'Ce palais des Habsbourg abrite une collection d''art graphique exceptionnelle, le Lièvre de Dürer, et une galerie de Monet à Picasso. Ses salons d''apparat restaurés sont éblouissants.', 'La terrasse devant le musée offre une vue sur l''Opéra.', false, 'img/vie08.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_-_Albertina_(b).JPG'),
  ('vie09', 'vienne', 'Opéra d''État', 'Culture', 'p1', 'Innere Stadt', 'Opernring 2, 1010 Wien', 'L''un des plus prestigieux opéras du monde joue plus de 300 soirs par an. Les places debout, vendues le jour même pour quelques euros, permettent d''écouter les plus grandes voix dans une salle somptueuse.', 'Places debout à moins de 15 € : faites la queue 80 minutes avant.', false, 'img/vie09.jpg', 'Wiener Staatsoper GmbH · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wiener_Staatsoper_Front.jpg'),
  ('vie10', 'vienne', 'Naschmarkt', 'Restaurant', 'p1', 'Mariahilf', 'Naschmarkt, 1060 Wien', 'Le plus célèbre marché de Vienne s''étire sur 1,5 km avec ses étals d''épices, de fromages, d''olives et de poissons, entrecoupés de petits restaurants. Le samedi, une brocante se tient à son extrémité.', 'Le samedi matin, ne manquez pas le marché aux puces au bout du marché.', false, 'img/vie10.jpg', 'Dietmar Rabich · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien,_Naschmarkt_--_2018_--_3109.jpg'),
  ('vie11', 'vienne', 'Café Central', 'Restaurant', 'p2', 'Innere Stadt', 'Herrengasse 14, 1010 Wien', 'Sous ses voûtes néogothiques et ses colonnes de marbre, le plus célèbre café viennois a vu passer Freud, Trotski et Klimt. On y savoure une Melange et un apfelstrudel au son du piano, comme au temps de l''Empire.', 'Venez dès l''ouverture pour éviter la file d''attente.', true, 'img/vie11.jpg', 'Dietmar Rabich · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien,_Café_Central_--_2018_--_3135.jpg'),
  ('vie12', 'vienne', 'Café Sacher', 'Restaurant', 'p2', 'Innere Stadt', 'Philharmoniker Straße 4, 1010 Wien', 'Dans l''hôtel légendaire face à l''Opéra, on goûte l''original de la Sachertorte, gâteau au chocolat et confiture d''abricot inventé en 1832, servi avec une crème fouettée non sucrée, sous des tentures de velours rouge.', 'On peut acheter la Sachertorte dans sa boîte en bois à la boutique.', false, 'img/vie12.jpg', 'No machine-readable author provided. Gryffindor assumed (... · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Café_Sacher_shop_interior,_Vienna.jpg'),
  ('vie13', 'vienne', 'Café Sperl', 'Restaurant', 'p1', 'Mariahilf', 'Gumpendorfer Straße 11, 1060 Wien', 'Depuis 1880, ce café aux tables de billard, banquettes patinées et journaux en bois est resté intact. Moins touristique que les grands cafés, il incarne l''esprit du café viennois où l''on reste des heures pour un seul café.', 'Le dimanche, un pianiste joue en fin d''après-midi.', false, 'img/vie13.jpg', 'Till F. Teenck · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Café_Sperl_Wien.jpg'),
  ('vie14', 'vienne', 'Figlmüller', 'Restaurant', 'p2', 'Innere Stadt', 'Wollzeile 5, 1010 Wien', 'La maison du schnitzel : depuis 1905, on y sert une escalope panée géante, qui déborde de l''assiette, avec salade de pommes de terre. Une institution viennoise dans une ruelle près de la cathédrale.', 'Réservez : la file est souvent longue le soir.', false, 'img/vie14.jpg', 'Brücke-Osteuropa · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Figlmüller_Wollzeile_Wien.JPG'),
  ('vie15', 'vienne', 'Demel', 'Restaurant', 'p2', 'Innere Stadt', 'Kohlmarkt 14, 1010 Wien', 'Ancien fournisseur de la cour impériale, ce salon de thé baroque aux miroirs dorés est un paradis pour gourmands. Par la vitre, on voit les pâtissiers façonner les gâteaux ; la Annatorte et le strudel sont divins.', 'Les vitrines de la boutique sont un spectacle à elles seules.', false, 'img/vie15.jpg', 'No machine-readable author provided. Gryffindor assumed (... · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Café_Demel,_Vienna.jpg'),
  ('vie16', 'vienne', 'Prater et Grande Roue', 'Activité', 'p2', 'Leopoldstadt', 'Riesenradplatz 1, 1020 Wien', 'La Grande Roue de 1897, immortalisée dans Le Troisième Homme, tourne lentement au-dessus du Prater et offre une vue sur toute la ville. Autour, un parc d''attractions vintage et un immense parc boisé.', 'Le parc du Prater est gratuit ; seules les attractions sont payantes.', false, 'img/vie16.jpg', 'Thomas Ledl · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_Riesenrad.jpg'),
  ('vie17', 'vienne', 'Hundertwasserhaus', 'Activité', 'free', 'Landstraße', 'Kegelgasse 36-38, 1030 Wien', 'Façades multicolores, sols ondulés, fenêtres toutes différentes et arbres qui poussent sur les balcons : cet immeuble d''habitation imaginé par Hundertwasser est une œuvre d''art joyeuse et rebelle.', 'Le Kunst Haus Wien voisin, musée Hundertwasser, prolonge la visite.', false, 'img/vie17.jpg', 'Dietmar Rabich · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien,_Hundertwasserhaus_--_2018_--_3180.jpg'),
  ('vie18', 'vienne', 'Karlskirche', 'Culture', 'p1', 'Wieden', 'Karlsplatz 1, 1040 Wien', 'Cette église baroque à la coupole verte et aux deux colonnes sculptées se reflète dans un bassin. Un ascenseur panoramique monte jusqu''aux fresques de la coupole, que l''on admire de tout près.', 'L''ascenseur jusqu''à la coupole est inclus dans le billet.', false, 'img/vie18.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Iglesia_de_San_Carlos_Borromeo,_Viena,_Austria,_2020-01-31,_DD_164-166_HDR.jpg'),
  ('vie19', 'vienne', 'Donauinsel', 'Activité', 'free', 'Donaustadt', 'Donauinsel, 1220 Wien', 'Cette île de 21 km sur le Danube est le terrain de loisirs des Viennois : baignade, vélo, roller, barbecues et bars de plage. Fin juin, elle accueille le Donauinselfest, plus grand festival gratuit d''Europe.', 'Le Donauinselfest de fin juin est gratuit.', false, 'img/vie19.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_-_Donauinsel_mit_den_Donaubrücken.JPG'),
  ('vie21', 'vienne', 'Loos American Bar', 'Bar & nuit', 'p2', 'Innere Stadt', 'Kärntner Durchgang 10, 1010 Wien', 'Ce minuscule bar de 1908 dessiné par Adolf Loos joue avec les miroirs pour paraître immense : marbre, acajou et onyx. Un bijou d''architecture où l''on boit d''excellents cocktails jusque tard.', 'Il n''y a qu''une dizaine de places : venez tôt.', false, 'img/vie21.jpg', 'Thomas Ledl · CC BY-SA 3.0 at · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kärntner_Durchgang_10_Loos_Bar.jpg'),
  ('vie22', 'vienne', 'Café Landtmann', 'Restaurant', 'p2', 'Innere Stadt', 'Universitätsring 4, 1010 Wien', 'Face au Burgtheater, le café préféré de Freud est aujourd''hui celui des politiques et des acteurs. Boiseries élégantes, journaux du monde entier et une grande terrasse sur le Ring.', 'La terrasse sur le Ring est agréable dès les beaux jours.', false, 'img/vie22.jpg', 'Gryffindor · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palais_Lieben-Auspitz_Vienna_Sept._2006_001.jpg'),
  ('vie23', 'vienne', 'Hôtel de ville', 'Activité', 'free', 'Innere Stadt', 'Friedrich-Schmidt-Platz 1, 1010 Wien', 'Ce palais néogothique aux allures de cathédrale accueille sur sa place un grand marché de Noël en hiver, une patinoire en janvier et un festival de films en plein air gratuit en été.', 'Le festival de films de l''été est gratuit avec des stands de cuisine du monde.', false, 'img/vie23.jpg', 'Thomas Ledl · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_Rathaus_hochauflösend.jpg'),
  ('vie24', 'vienne', 'Prunksaal', 'Culture', 'p1', 'Innere Stadt', 'Josefsplatz 1, 1010 Wien', 'La salle d''apparat de la Bibliothèque nationale est l''une des plus belles bibliothèques baroques du monde : 200 000 livres anciens sous une coupole peinte, statues et globes du XVIIe siècle.', 'Venez en fin d''après-midi pour une lumière plus douce.', false, 'img/vie24.jpg', 'Daniel Gran · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Allegory_of_war_and_Law_-_Prunksaal_-_Austrian_National_Library.jpg'),
  ('vie25', 'vienne', 'Musikverein', 'Bar & nuit', 'p2', 'Innere Stadt', 'Musikvereinsplatz 1, 1010 Wien', 'Sa « salle dorée », célèbre pour le concert du Nouvel An, possède l''une des meilleures acoustiques au monde. Assister à un concert du Philharmonique de Vienne y est un rêve de mélomane.', 'Des places debout à petit prix sont vendues pour de nombreux concerts.', false, 'img/vie25.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Musikverein,_Viena,_Austria,_2020-01-31,_DD_170-172_HDR.jpg'),
  ('vie26', 'vienne', 'Cimetière central', 'Activité', 'free', 'Simmering', 'Simmeringer Hauptstraße 234, 1110 Wien', 'Immense et romantique, ce cimetière abrite les tombes de Beethoven, Schubert, Brahms et des Strauss, réunies dans un carré des musiciens. Ses allées arborées où courent les écureuils invitent à la promenade.', 'Le tram 71 vous y dépose depuis le centre.', false, 'img/vie26.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Simmering_(Wien)_-_Luegerkirche_(1).JPG'),
  ('vie27', 'vienne', 'Volksgarten', 'Activité', 'free', 'Innere Stadt', 'Volksgarten, 1010 Wien', 'Entre la Hofburg et le Parlement, ce jardin public abrite plus de 3 000 rosiers de 400 variétés et un petit temple grec. En été, le Volksgarten Pavillon devient un bar en plein air très prisé.', 'Venez en juin pour la floraison des roses.', false, 'img/vie27.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wien_-_Volksgarten.JPG'),
  ('vie28', 'vienne', 'Haus der Musik', 'Culture', 'p2', 'Innere Stadt', 'Seilerstätte 30, 1010 Wien', 'Un musée interactif consacré au son et à la musique : on y dirige virtuellement le Philharmonique de Vienne, on compose avec des dés comme Mozart et on découvre les grands compositeurs viennois.', 'Le soir, le billet est moins cher en semaine.', false, 'img/vie28.jpg', 'Eva Prader · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:HDM_Außenansicht_hoch.JPG'),
  ('vie30', 'vienne', 'Zum Schwarzen Kameel', 'Restaurant', 'p2', 'Innere Stadt', 'Bognergasse 5, 1010 Wien', 'Fournisseur de la cour depuis 1618, ce traiteur Art nouveau est réputé pour ses petits sandwichs ouverts au jambon de Vienne et raifort, à manger debout avec un verre de vin blanc. Une tradition viennoise.', 'Mangez au comptoir comme les habitués, avec un verre de Grüner Veltliner.', false, 'img/vie30.jpg', 'Gryffindor · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Zum_Schwarzen_Kameel_003.JPG'),
  ('vie31', 'vienne', 'Kahlenberg', 'Activité', 'free', 'Döbling', 'Kahlenberg, 1190 Wien', 'Cette colline boisée au nord de Vienne offre un panorama sur toute la ville, le Danube et les vignes.', 'Le bus 38A y monte depuis Heiligenstadt.', false, 'img/vie31.jpg', 'C.Stadler/Bwag · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Döbling_(Wien)_-_Kahlenberg.JPG'),
  ('vie32', 'vienne', 'Secession', 'Culture', 'p1', 'Wieden', 'Friedrichstraße 12, 1010 Wien', 'Le temple de l''Art nouveau viennois, à la coupole de feuilles d''or, abrite la frise Beethoven de Klimt.', 'La frise Beethoven est au sous-sol.', false, 'img/vie32.jpg', 'Conny Duck · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Secession_Building_Vienna.jpg'),
  ('cph01', 'copenhague', 'Nyhavn', 'Activité', 'free', 'Indre By', 'Nyhavn, 1051 København', 'Ce port du XVIIe siècle bordé de maisons colorées et de vieux voiliers en bois est la carte postale de Copenhague. Hans Christian Andersen y a vécu ; aujourd''hui, les terrasses y débordent dès le premier rayon de soleil.', 'Achetez une bière à emporter et asseyez-vous au bord du quai, comme les Danois.', false, 'img/cph01.jpg', 'Vincents productions · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nyhavn_5-15,_Kbh_2020.jpg'),
  ('cph02', 'copenhague', 'Jardins de Tivoli', 'Activité', 'p2', 'Vesterbro', 'Vesterbrogade 3, 1630 København', 'Ouvert en 1843, l''un des plus vieux parcs d''attractions du monde mêle montagnes russes en bois, jardins fleuris, pavillons orientaux et milliers de lampions la nuit. Il aurait inspiré Walt Disney.', 'Les soirs d''été, les illuminations sont magiques.', false, 'img/cph02.jpg', 'Sailing10 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tivoli_Garden_Easter.jpg'),
  ('cph03', 'copenhague', 'La Petite Sirène', 'Activité', 'free', 'Østerbro', 'Langelinie, 2100 København', 'Assise sur son rocher depuis 1913, la statue inspirée du conte d''Andersen est plus petite qu''on ne l''imagine, mais la promenade le long du port pour l''atteindre, via la citadelle de Kastellet, est superbe.', 'Venez tôt le matin pour la voir sans les cars de touristes.', false, 'img/cph03.jpg', 'Benoît Prieur · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Petite_sirène_de_Copenhague_(conforme_à_la_loi_danoise).JPG'),
  ('cph04', 'copenhague', 'Christiania', 'Activité', 'free', 'Christianshavn', 'Prinsessegade, 1440 København', 'Cette « ville libre » autogérée, installée depuis 1971 dans une ancienne caserne, mêle maisons bricolées, ateliers d''artistes, street art et cafés alternatifs au bord d''un lac. Un monde à part au cœur de la ville.', 'Ne prenez pas de photos dans la zone de Pusher Street.', false, 'img/cph04.jpg', 'Bruno Jargot · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Christiania_depuis_Notre_Sauveur.jpg'),
  ('cph05', 'copenhague', 'Château de Rosenborg', 'Culture', 'p2', 'Indre By', 'Øster Voldgade 4A, 1350 København', 'Ce château Renaissance en brique rouge, au milieu du jardin royal, abrite les joyaux de la Couronne danoise, des salles d''apparat et un trône en défense de narval gardé par trois lions d''argent.', 'Les joyaux de la Couronne sont au sous-sol.', false, 'img/cph05.jpg', 'Jakub Hałun · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Copenhagen,_view_from_Rundetårn_with_Rosenborg_Castle,_20220617_1004_6716.jpg'),
  ('cph06', 'copenhague', 'Christiansborg', 'Culture', 'p2', 'Slotsholmen', 'Prins Jørgens Gård 1, 1218 København', 'Siège du Parlement, du Premier ministre et de la Cour suprême, ce palais abrite aussi les salles de réception royales aux tapisseries modernes. Sa tour, la plus haute de la ville, offre une vue gratuite.', 'La tour panoramique est gratuite.', false, 'img/cph06.jpg', 'eimoberg from Changwon, South Korea · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Christiansborg_Slot.jpg'),
  ('cph07', 'copenhague', 'Amalienborg', 'Activité', 'free', 'Frederiksstaden', 'Amalienborg Slotsplads, 1257 København', 'Quatre palais rococo identiques autour d''une place octogonale forment la résidence de la famille royale danoise. Chaque jour à midi, la garde royale à bonnets à poils défile depuis Rosenborg.', 'Relève de la garde tous les jours à midi.', false, 'img/cph07.jpg', 'European Commission / Joshua Andrew Gross · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amalienborg_Palace_(cropped).jpg'),
  ('cph08', 'copenhague', 'Église de Notre-Sauveur', 'Activité', 'p1', 'Christianshavn', 'Sankt Annæ Gade 29, 1416 København', 'Sa flèche baroque en spirale se gravit par un escalier extérieur qui tourne autour du clocher jusqu''au sommet, à 90 mètres. Sensations et vue spectaculaire sur Copenhague garanties.', 'Fermé par grand vent ou pluie : vérifiez la météo.', false, 'img/cph08.jpg', 'Ireneusz Jerzy Borysiewicz · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:The_Church_of_Our_Saviour.jpg'),
  ('cph09', 'copenhague', 'Tour ronde', 'Activité', 'p1', 'Indre By', 'Købmagergade 52A, 1150 København', 'Plutôt qu''un escalier, une rampe en colimaçon pavée monte au sommet de cet observatoire du XVIIe siècle, construit pour qu''un carrosse puisse y grimper. Vue superbe sur les toits de la vieille ville.', 'L''observatoire ouvre certains soirs d''hiver pour observer les étoiles.', false, 'img/cph09.jpg', 'Erik Christensen · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Copenhagen.1.Rundetårn.jpg'),
  ('cph10', 'copenhague', 'Ny Carlsberg Glyptotek', 'Culture', 'p2', 'Vesterbro', 'Dantes Plads 7, 1556 København', 'Fondé par le brasseur Carlsberg, ce musée mêle sculptures antiques, Rodin et impressionnistes autour d''un jardin d''hiver tropical sous une coupole de verre, où palmiers et café invitent à la pause.', 'Gratuit le dernier mercredi du mois.', false, 'img/cph10.jpg', 'Dietmar Rabich · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kopenhagen_(DK),_Ny-Carlsberg-Glyptotek_--_2017_--_1466.jpg'),
  ('cph11', 'copenhague', 'SMK – Musée national des beaux-arts', 'Culture', 'free', 'Indre By', 'Sølvgade 48-50, 1307 København', 'Le plus grand musée d''art du Danemark relie un palais du XIXe siècle à une extension moderne vitrée sur le parc. Sa collection permanente, de Rembrandt à Matisse, est en accès libre.', 'La collection permanente est gratuite.', false, 'img/cph11.jpg', 'Ida Tietgen Høyrup · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:SMK_Entrance.jpg'),
  ('cph12', 'copenhague', 'Designmuseum Danmark', 'Culture', 'p2', 'Frederiksstaden', 'Bredgade 68, 1260 København', 'Dans un ancien hôpital rococo, le musée raconte l''histoire du design danois : chaises iconiques de Jacobsen et Wegner, lampes et objets du quotidien. Un incontournable pour comprendre le style scandinave.', 'Le jardin intérieur et le café sont paisibles.', false, 'img/cph12.jpg', 'Blunts · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kunstindustrimuseet_copenhagen.jpg'),
  ('cph13', 'copenhague', 'Torvehallerne', 'Restaurant', 'p2', 'Nørreport', 'Frederiksborggade 21, 1360 København', 'Deux halles de verre réunissent plus de 60 stands gourmands : smørrebrød, poissons fumés, pâtisseries, cafés de spécialité et fromages danois. Le meilleur endroit pour goûter la cuisine nordique sans se ruiner.', 'Goûtez un smørrebrød, la tartine ouverte danoise.', true, 'img/cph13.jpg', 'Jorge Franganillo · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Copenhagen_Torvehallerne_(30267894558).jpg'),
  ('cph14', 'copenhague', 'Reffen', 'Restaurant', 'p2', 'Refshaleøen', 'Refshalevej 167, 1432 København', 'Sur une ancienne friche industrielle au bord de l''eau, ce marché de street food réunit des dizaines de stands dans des conteneurs colorés. Coucher de soleil sur le port, musique et transats l''été.', 'Ouvert surtout d''avril à septembre ; venez en bateau-bus.', false, 'img/cph14.jpg', 'Turaids · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Reffen_Copenhagen_Street_Food_Market.jpg'),
  ('cph15', 'copenhague', 'Strøget', 'Activité', 'free', 'Indre By', 'Strøget, 1160 København', 'L''une des plus longues rues piétonnes d''Europe traverse le centre de la place de l''hôtel de ville à Kongens Nytorv, entre boutiques, musiciens de rue et petites places animées.', 'Les rues parallèles, plus calmes, cachent les plus jolies boutiques.', false, 'img/cph15.jpg', 'Aram Zucker-Scharff from Fairfax, VA, USA · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Strøget,_Copenhagen,_Denmark_(9280358703).jpg'),
  ('cph16', 'copenhague', 'Jardin botanique', 'Activité', 'free', 'Indre By', 'Gothersgade 128, 1123 København', 'Ce jardin romantique abrite une grande serre de verre et de fer de 1874 où règne un climat tropical, avec palmiers et escalier en colimaçon. Lacs et rocailles en font un havre de paix en ville.', 'La grande serre est gratuite.', false, 'img/cph16.jpg', 'Bärbel Miemietz · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2023-04-19_Palm_House_Copenhagen_01.jpg'),
  ('cph17', 'copenhague', 'Kastellet', 'Activité', 'free', 'Østerbro', 'Gl. Hovedvagt 1, 2100 København', 'Cette citadelle en forme d''étoile, entourée de douves et de remparts herbeux, est l''une des mieux conservées d''Europe. Ses casernes rouges et son moulin à vent en font une belle promenade vers la Petite Sirène.', 'Faites le tour des remparts à pied.', false, 'img/cph17.jpg', 'Bob Collowan · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kastellet,_Copenhagen_(aerial_view).jpg'),
  ('cph18', 'copenhague', 'Diamant noir', 'Culture', 'free', 'Slotsholmen', 'Søren Kierkegaards Plads 1, 1221 København', 'L''extension de granit noir poli de la Bibliothèque royale se reflète dans le port. À l''intérieur, un atrium vertigineux s''ouvre sur l''eau ; on y vient lire, voir une expo ou boire un café face au canal.', 'L''atrium et le café sont accessibles gratuitement.', false, 'img/cph18.jpg', 'kallerna · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Det_Kongelige_Bibliotek_Copenhagen.jpg'),
  ('cph19', 'copenhague', 'CopenHill', 'Activité', 'free', 'Amager', 'Vindmøllevej 6, 2300 København', 'Sur le toit d''une usine de valorisation des déchets, une piste de ski artificielle, un sentier de randonnée et le plus haut mur d''escalade du monde. Le sommet offre une vue étonnante sur le port et la Suède.', 'Le sentier jusqu''au sommet est gratuit.', false, 'img/cph19.jpg', 'kallerna · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amager_Bakke_Copenhagen_1.jpg'),
  ('cph20', 'copenhague', 'Superkilen', 'Activité', 'free', 'Nørrebro', 'Nørrebrogade 210, 2200 København', 'Ce parc urbain coloré célèbre la diversité du quartier de Nørrebro avec des objets venus de 60 pays : néons de Russie, bancs du Brésil, fontaine du Maroc, sur un sol rouge, noir ou vert.', 'Prolongez la balade dans le quartier multiculturel de Nørrebro.', false, 'img/cph20.jpg', 'Emily · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Superkilen_hill-top_view.jpg'),
  ('cph21', 'copenhague', 'Kødbyen', 'Bar & nuit', 'p2', 'Vesterbro', 'Flæsketorvet, 1711 København', 'L''ancien quartier des abattoirs, avec ses bâtiments blancs fonctionnalistes, est devenu le cœur de la nuit de Copenhague : restaurants branchés, bars à cocktails et clubs dans d''anciennes boucheries.', 'Dînez tôt puis enchaînez sur les bars du quartier.', false, 'img/cph21.jpg', 'Riemann at da.wikipedia · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Koedbyen_hvide.jpg'),
  ('cph22', 'copenhague', 'Hviids Vinstue', 'Bar & nuit', 'p1', 'Indre By', 'Kongens Nytorv 19, 1050 København', 'Le plus vieux bar à vin de Copenhague (1723) a gardé ses salles basses lambrissées et son ambiance chaleureuse. En hiver, on y boit le gløgg, le vin chaud épicé danois.', 'Le gløgg de Noël est une tradition.', false, 'img/cph22.jpg', 'Christian Bickel · CC BY-SA 2.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kbh_Hviits_Vinstue.jpg'),
  ('cph23', 'copenhague', 'La Glace', 'Restaurant', 'p1', 'Indre By', 'Skoubogade 3, 1158 København', 'La plus vieille pâtisserie de Copenhague (1870) sert gâteaux à la crème, chocolat chaud et la célèbre « Sportskage » dans un décor de salon bourgeois du XIXe siècle.', 'Goûtez la Sportskage, spécialité de la maison.', false, 'img/cph23.jpg', 'Leif Jørgensen · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Skoubogade_05.JPG'),
  ('cph24', 'copenhague', 'Kongens Have', 'Activité', 'free', 'Indre By', 'Øster Voldgade 4A, 1350 København', 'Le plus vieux jardin royal de Copenhague entoure le château de Rosenborg. Allées de tilleuls, roseraie et pelouses en font le lieu de pique-nique préféré des habitants l''été.', 'Parfait pour un pique-nique avec des produits de Torvehallerne.', false, 'img/cph24.jpg', 'Jonas Smith · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kongens_Have_Rosenborg_Slot.jpg'),
  ('cph25', 'copenhague', 'Assistens Kirkegård', 'Activité', 'free', 'Nørrebro', 'Kapelvej 2, 2200 København', 'Ce cimetière arboré est aussi un parc où les habitants se promènent et pique-niquent. Hans Christian Andersen et Søren Kierkegaard y reposent sous les grands arbres.', 'Un plan à l''entrée indique les tombes célèbres.', false, 'img/cph25.jpg', 'Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Assistens_Kirkegård_1.jpg'),
  ('cph26', 'copenhague', 'Louisiana Museum', 'Culture', 'p2', 'Humlebæk', 'Gl. Strandvej 13, 3050 Humlebæk', 'À 35 minutes de train, ce musée d''art moderne est l''un des plus beaux du monde : Giacometti, Warhol et Kusama dans des pavillons vitrés reliés par un parc de sculptures qui descend vers la mer.', 'Le billet combiné train + musée de la DSB est avantageux.', false, 'img/cph26.jpg', 'Jorchr · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Louisiana,_Danmark_3.jpg'),
  ('cph27', 'copenhague', 'Église de Grundtvig', 'Culture', 'free', 'Bispebjerg', 'På Bjerget 14B, 2400 København', 'Cette église expressionniste en brique jaune, dont la façade évoque un orgue géant, est l''un des chefs-d''œuvre de l''architecture du XXe siècle. Son intérieur dépouillé est saisissant.', 'Entrée gratuite ; combinez avec le cimetière voisin.', false, 'img/cph27.jpg', 'Jan Rasmussen · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Grundtvigs_Kirke_Copenhagen.jpg'),
  ('cph28', 'copenhague', 'Théâtre royal', 'Bar & nuit', 'p2', 'Indre By', 'Kongens Nytorv 9, 1050 København', 'Sur la plus grande place de Copenhague, ce théâtre néo-baroque accueille ballet, opéra et théâtre. Le Ballet royal danois est l''un des plus anciens du monde.', 'Des billets à prix réduit sont vendus le jour même.', false, 'img/cph28.jpg', 'Axel Kuhlmann · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Royal_Danish_Theatre,_Copenhagen.jpg'),
  ('cph29', 'copenhague', 'Mikkeller Bar', 'Bar & nuit', 'p2', 'Vesterbro', 'Viktoriagade 8B-C, 1655 København', 'Le bar historique de la célèbre brasserie artisanale danoise propose une vingtaine de bières pression créatives dans une petite cave minimaliste. Un temple pour les amateurs de craft beer.', 'Demandez une dégustation de petits verres pour goûter plusieurs bières.', false, 'img/cph29.jpg', 'Jukka from HELSINKI, Finland · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mikkeller_(32671065504).jpg'),
  ('cph31', 'copenhague', 'Bakken', 'Activité', 'free', 'Klampenborg', 'Dyrehavevej 62, 2930 Klampenborg', 'Le plus vieux parc d''attractions du monde (1583), à l''orée d''une forêt peuplée de cerfs, à quelques minutes de train.', 'L''entrée du parc est gratuite.', false, 'img/cph31.jpg', 'Erkan · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dyrehavsbakken.jpg'),
  ('bud01', 'budapest', 'Parlement hongrois', 'Culture', 'p2', 'Lipótváros', 'Kossuth Lajos tér 1-3, 1055 Budapest', 'Avec ses 691 pièces, sa coupole et ses flèches néogothiques se reflétant dans le Danube, le Parlement est l''un des plus beaux bâtiments d''Europe. La visite guidée mène jusqu''à la Sainte Couronne de Hongrie.', 'Réservez la visite guidée en ligne ; la vue de nuit depuis la rive de Buda est incroyable.', false, 'img/bud01.jpg', 'Lynx1211 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Országház_(Hungarian_Parliament_Building)(2).jpg'),
  ('bud02', 'budapest', 'Bastion des Pêcheurs', 'Activité', 'free', 'Várnegyed', 'Szentháromság tér, 1014 Budapest', 'Sept tourelles néoromanes blanches comme sorties d''un conte de fées surplombent le Danube et offrent la vue la plus célèbre sur le Parlement. Au lever du soleil, l''endroit est presque désert et féerique.', 'Les terrasses basses sont gratuites ; venez au lever du soleil.', false, 'img/bud02.jpg', 'Brian Adamson · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Halászbástya_2017.jpg'),
  ('bud03', 'budapest', 'Église Matthias', 'Culture', 'p1', 'Várnegyed', 'Szentháromság tér 2, 1014 Budapest', 'Son toit de tuiles vernissées colorées et sa flèche gothique dominent la colline du château. L''intérieur, entièrement peint de motifs floraux et géométriques, est unique au monde.', 'Les concerts d''orgue du soir sont superbes.', false, 'img/bud03.jpg', 'Thaler Tamas · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MatyasTemplomFotoThalerTamas20162.JPG'),
  ('bud04', 'budapest', 'Château de Buda', 'Activité', 'free', 'Várnegyed', 'Szent György tér 2, 1014 Budapest', 'L''ancien palais royal domine le Danube du haut de la colline de Buda. Ses cours, terrasses et la statue de l''oiseau Turul sont en accès libre, avec une vue imprenable sur Pest et le pont des Chaînes.', 'Montez en funiculaire, redescendez à pied par les escaliers.', false, 'img/bud04.jpg', 'Cristian Bortes · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:River_Beatrice_(ship,_2007)_005.jpg'),
  ('bud05', 'budapest', 'Bains Széchenyi', 'Activité', 'p2', 'Városliget', 'Állatkerti körút 9-11, 1146 Budapest', 'Dans un palais néobaroque jaune, les plus grands bains thermaux d''Europe offrent 18 bassins, dont de grands bassins extérieurs à 38°C où l''on joue aux échecs même sous la neige. Une expérience budapestoise incontournable.', 'Venez tôt le matin ou en semaine ; apportez tongs et serviette.', false, 'img/bud05.jpg', 'Marc Ryckaert (MJJR) · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budapest_Széchenyi_Baths_R01.jpg'),
  ('bud06', 'budapest', 'Bains Rudas', 'Activité', 'p2', 'Tabán', 'Döbrentei tér 9, 1013 Budapest', 'Ces bains turcs du XVIe siècle cachent un bassin octogonal sous une coupole ottomane percée d''étoiles de lumière. Sur le toit, un jacuzzi panoramique offre une vue spectaculaire sur le Danube.', 'Les bains de nuit du week-end sont une expérience unique.', false, 'img/bud06.jpg', 'Misibacsi at Hungarian Wikipedia · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rudas_gyogyfurdo_P7290076.jpg'),
  ('bud07', 'budapest', 'Szimpla Kert', 'Bar & nuit', 'p1', 'Erzsébetváros', 'Kazinczy utca 14, 1075 Budapest', 'Le premier et le plus célèbre des « ruin bars » : un immeuble délabré transformé en bar labyrinthique, rempli de meubles dépareillés, d''une vieille Trabant et de plantes. Le dimanche matin, il accueille un marché fermier.', 'Le marché fermier du dimanche matin est une bonne surprise.', false, 'img/bud07.jpg', 'Yelkrokoyade · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Szimpla_Kert_Budapest_1.jpg'),
  ('bud08', 'budapest', 'Grande Halle du marché', 'Restaurant', 'p1', 'Ferencváros', 'Vámház körút 1-3, 1093 Budapest', 'Sous une charpente métallique et un toit de tuiles colorées, le plus grand marché couvert de Budapest déborde de paprika, de saucissons et de foie gras. À l''étage, on goûte le lángos, galette frite à la crème et au fromage.', 'Le lángos de l''étage est un incontournable ; fermé le dimanche.', false, 'img/bud08.jpg', 'Fred Romero from Paris, France · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budapest_-_Központi_Vásárcsarnok_(2).jpg'),
  ('bud09', 'budapest', 'Basilique Saint-Étienne', 'Culture', 'p1', 'Lipótváros', 'Szent István tér 1, 1051 Budapest', 'La plus grande église de Budapest abrite la main momifiée de saint Étienne, premier roi de Hongrie. Sa coupole, à 96 mètres, offre une vue panoramique à 360° sur la ville.', 'L''ascenseur jusqu''à la coupole évite la plupart des marches.', false, 'img/bud09.jpg', 'Yelkrokoyade · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Basilique_Saint-Étienne_de_Pest.jpg'),
  ('bud10', 'budapest', 'Opéra d''État hongrois', 'Culture', 'p2', 'Terézváros', 'Andrássy út 22, 1061 Budapest', 'Magnifiquement restauré, cet opéra néo-Renaissance aux escaliers de marbre et dorures est l''un des plus beaux d''Europe. Visites guidées avec mini-concert ou opéra à prix bien plus doux qu''à Vienne.', 'Les places pour un opéra sont souvent moins chères que la visite guidée.', false, 'img/bud10.jpg', 'Salome mi · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:State_Opera_House,_Budapest,_Hungary_2023.jpg'),
  ('bud11', 'budapest', 'Place des Héros', 'Activité', 'free', 'Városliget', 'Hősök tere, 1146 Budapest', 'Au bout de l''avenue Andrássy, cette immense place célèbre les mille ans de la Hongrie avec une colonnade de chefs historiques et l''archange Gabriel au sommet. Elle ouvre sur le grand parc de la ville.', 'Continuez vers le parc Városliget et le château de Vajdahunyad.', false, 'img/bud11.jpg', 'User:Sveter (Please credit as "Petr Šmerkl, Wikipedia" in... · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Heroes_Square_Budapest_2010_01.jpg'),
  ('bud12', 'budapest', 'Maison de la Terreur', 'Culture', 'p1', 'Terézváros', 'Andrássy út 60, 1062 Budapest', 'Dans l''ancien siège de la police politique nazie puis communiste, ce musée retrace les deux dictatures qui ont frappé la Hongrie. Les cellules du sous-sol rendent la visite très forte.', 'Comptez deux heures ; fermé le lundi.', false, 'img/bud12.jpg', 'Serge Bystro from Moscow, Russia · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:House_of_Terror_Museum_in_Budapest_(10890338584).jpg'),
  ('bud13', 'budapest', 'Grande Synagogue', 'Culture', 'p2', 'Erzsébetváros', 'Dohány utca 2, 1074 Budapest', 'La plus grande synagogue d''Europe impressionne par son style mauresque et ses deux tours à bulbes. Dans le jardin, l''arbre de vie en métal porte les noms des victimes de la Shoah.', 'Tenue correcte exigée ; fermée le samedi.', false, 'img/bud13.jpg', 'Random photos 1989 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budapest,_Dohány_utca,_kilátás,_11.jpg'),
  ('bud14', 'budapest', 'Chaussures au bord du Danube', 'Activité', 'free', 'Lipótváros', 'Id. Antall József rakpart, 1054 Budapest', 'Soixante paires de chaussures en fer alignées au bord du fleuve rendent hommage aux Juifs fusillés ici en 1944-1945. Un mémorial simple et bouleversant, face aux collines de Buda.', 'Il se trouve à quelques minutes à pied du Parlement.', false, 'img/bud14.jpg', 'Nikodem Nijaki · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shoes_Danube_Promenade_IMGP1297.jpg'),
  ('bud15', 'budapest', 'Pont des Chaînes', 'Activité', 'free', 'Belváros', 'Széchenyi lánchíd, 1051 Budapest', 'Le premier pont permanent sur le Danube, gardé par des lions de pierre, relie Buda et Pest depuis 1849. Récemment restauré, il est superbe la nuit, quand ses chaînes s''illuminent.', 'Traversez-le à pied au coucher du soleil.', false, 'img/bud15.jpg', 'János Ecsedy · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Széchenyi_Lánchíd_éjjel.jpg'),
  ('bud17', 'budapest', 'Colline Gellért', 'Activité', 'free', 'Gellérthegy', 'Gellérthegy, 1118 Budapest', 'Du haut de cette colline, couronnée par la statue de la Liberté, on embrasse tout Budapest : les ponts, le Parlement et les deux rives du Danube. La montée à pied passe par des sentiers boisés et des belvédères.', 'Montez en fin d''après-midi pour voir la ville s''illuminer.', false, 'img/bud17.jpg', 'Czimmy at Hungarian Wikipedia · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pest-latkep.jpg'),
  ('bud18', 'budapest', 'New York Café', 'Restaurant', 'p2', 'Erzsébetváros', 'Erzsébet körút 9-11, 1073 Budapest', 'Surnommé « le plus beau café du monde », ce palais de 1894 éblouit par ses dorures, ses fresques, ses colonnes torsadées et ses lustres de cristal. Un café ou un gâteau dans ce décor est un moment inoubliable.', 'Venez dès l''ouverture pour éviter une longue file.', true, 'img/bud18.jpg', 'Gzzz · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Clocks_in_New_York_Café_Budapest_(2).jpg'),
  ('bud19', 'budapest', 'Gerbeaud', 'Restaurant', 'p2', 'Belváros', 'Vörösmarty tér 7-8, 1051 Budapest', 'Depuis 1858, cette pâtisserie à l''élégance impériale sert des gâteaux hongrois légendaires comme le Dobos, aux couches de caramel, et l''Esterházy. Sa terrasse donne sur la place Vörösmarty.', 'Goûtez le gâteau Dobos, spécialité hongroise.', false, 'img/bud19.jpg', 'Norbert Aepli, Switzerland (User:Noebu) · CC BY 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gerbeaud_Budapest_2005_078.jpg'),
  ('bud20', 'budapest', 'Centrál Kávéház', 'Restaurant', 'p2', 'Belváros', 'Károlyi utca 9, 1053 Budapest', 'Ce café littéraire de 1887, fréquenté par les écrivains et journalistes hongrois, sert des petits-déjeuners copieux et des plats hongrois dans un décor de boiseries et de lustres, plus calme que le New York.', 'Le petit-déjeuner est excellent.', false, 'img/bud20.jpg', 'Ato 01 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Central_Café_Budapest-2022.jpg'),
  ('bud21', 'budapest', 'Gundel', 'Restaurant', 'p3', 'Városliget', 'Gundel Károly út 4, 1146 Budapest', 'Le restaurant le plus célèbre de Hongrie, fondé en 1894, a créé la crêpe Gundel au chocolat et aux noix. Goulash raffiné, foie gras et vins de Tokaj dans un décor élégant avec jardin.', 'Le déjeuner en semaine est plus abordable que le dîner.', false, 'img/bud21.jpg', 'Gvarady · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gundel_restaurant.JPG'),
  ('bud22', 'budapest', 'Musée des Beaux-Arts', 'Culture', 'p2', 'Városliget', 'Dózsa György út 41, 1146 Budapest', 'Sur la place des Héros, ce temple néoclassique abrite une remarquable collection de maîtres européens, de Raphaël à Goya et El Greco, et une salle romane spectaculaire restaurée.', 'La salle romane, sous ses voûtes peintes, est un chef-d''œuvre.', false, 'img/bud22.jpg', 'Serge Bystro from Moscow, Russia · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budapest_XIV.,_Heroes''_Square,_Museum_Fine_Arts_(10890256794).jpg'),
  ('bud23', 'budapest', 'Château de Vajdahunyad', 'Activité', 'free', 'Városliget', 'Vajdahunyad sétány, 1146 Budapest', 'Ce château de conte de fées au bord d''un lac mélange tous les styles architecturaux hongrois. L''hiver, le lac se transforme en grande patinoire en plein air, l''une des plus belles d''Europe.', 'La patinoire d''hiver devant le château est magique.', false, 'img/bud23.jpg', 'Felix König · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vajdahunyad_vára_Budapest_September_2013.jpg'),
  ('bud24', 'budapest', 'Galerie nationale hongroise', 'Culture', 'p1', 'Várnegyed', 'Szent György tér 2, 1014 Budapest', 'Installée dans le palais royal de Buda, la galerie retrace mille ans d''art hongrois, des retables gothiques aux peintres du XXe siècle. Sa coupole offre une vue panoramique sur le Danube.', 'Montez à la coupole pour la vue.', false, 'img/bud24.jpg', 'Dguendel · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budapest,_Hungarian_National_Gallery,_a_row_of_paintings.jpg'),
  ('bud25', 'budapest', 'Funiculaire de Buda', 'Activité', 'p1', 'Várnegyed', 'Clark Ádám tér, 1013 Budapest', 'Depuis 1870, ce funiculaire en bois grimpe la colline du château en une minute, offrant une vue plongeante sur le pont des Chaînes et le Danube. Une montée charmante et historique.', 'Prenez-le à la montée et redescendez à pied.', false, 'img/bud25.jpg', 'Mikimami · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budavári_Sikló.jpg'),
  ('bud26', 'budapest', 'A38', 'Bar & nuit', 'p1', 'Újbuda', 'Petőfi híd, budai hídfő, 1117 Budapest', 'Une ancienne barge ukrainienne amarrée sur le Danube est devenue l''une des meilleures salles de concerts d''Europe. Restaurant sur le pont, terrasse face au fleuve et soirées jusqu''à l''aube.', 'La terrasse sur le pont est idéale au coucher du soleil.', false, 'img/bud26.jpg', 'Texaner · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A38_1.jpg'),
  ('bud27', 'budapest', 'Gozsdu Udvar', 'Bar & nuit', 'p1', 'Erzsébetváros', 'Király utca 13, 1075 Budapest', 'Une enfilade de cours reliant deux rues du quartier juif, bordée de bars, restaurants et terrasses. Le soir, c''est l''un des épicentres de la vie nocturne de Budapest ; le week-end, un marché d''artisans s''y installe.', 'Le marché d''artisans du week-end est sympa en journée.', false, 'img/bud27.jpg', 'torobala · CC BY-SA 2.5 hu · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gozsdu-udvar_(840._számú_műemlék)_2.jpg'),
  ('bud28', 'budapest', 'Hôpital dans le rocher', 'Culture', 'p2', 'Várnegyed', 'Lovas út 4/c, 1012 Budapest', 'Creusé dans les grottes sous la colline du château, cet hôpital secret a servi pendant la Seconde Guerre mondiale et la révolution de 1956, puis d''abri antiatomique. Une visite guidée fascinante.', 'Visite guidée uniquement, d''environ une heure.', false, 'img/bud28.jpg', 'Hospital in the Rock Marketing · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A_Múzeum_bejárata.jpg'),
  ('bud29', 'budapest', 'Pont de la Liberté', 'Activité', 'free', 'Belváros', 'Szabadság híd, 1093 Budapest', 'Ce pont vert aux oiseaux mythiques Turul relie la Grande Halle aux bains Gellért. L''été, les jeunes Budapestois s''assoient sur ses poutres au-dessus du fleuve pour regarder le coucher du soleil.', 'Les week-ends d''été, il est parfois fermé aux voitures et devient une grande terrasse.', false, 'img/bud29.jpg', 'KovácsD · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budapesti_Szabadság_híd_Pestről_2014.JPG'),
  ('bud30', 'budapest', 'Musée national hongrois', 'Culture', 'p1', 'Józsefváros', 'Múzeum körút 14-16, 1088 Budapest', 'C''est sur les marches de ce palais néoclassique qu''éclata la révolution de 1848. Le musée retrace l''histoire de la Hongrie, du manteau du couronnement aux souvenirs du communisme.', 'Le jardin qui l''entoure est agréable pour une pause.', false, 'img/bud30.jpg', 'hu:user:Pasztilla · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Magyar_Nemzeti_Múzeum.jpg'),
  ('bud31', 'budapest', 'Ruszwurm', 'Restaurant', 'p1', 'Várnegyed', 'Szentháromság utca 7, 1014 Budapest', 'La plus vieille pâtisserie de Budapest (1827), minuscule et charmante, sur la colline du château. Son krémes est une institution.', 'Goûtez le krémes, gâteau à la crème vanillée.', false, 'img/bud31.jpg', 'Хомелка · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Szentháromság_utca_7,_Budapest,_Будапешт_xx_01.jpg')
