-- CityPick's : les 360 spots du catalogue (12 villes x 30). A coller dans le SQL Editor APRES 1_schema.sql.
on conflict (id) do update set city = excluded.city, name = excluded.name, cat = excluded.cat, price = excluded.price, hood = excluded.hood, address = excluded.address, "desc" = excluded."desc", tip = excluded.tip, pick = excluded.pick, photo = excluded.photo, credit = excluded.credit, source = excluded.source;
